/**
 * Document ids ride in `P2P_FILE_SEND` / inventory / request frames next to a full
 * blob; longer ids would push those frames over the cap.
 * @param {*} id
 * @returns {boolean}
 * @private
 */
function isWireDocumentId (id) {
  if (id === null || id === undefined || typeof id === 'object') return false;
  const text = String(id);
  return text.length > 0 && text.length <= MAX_DOCUMENT_ID_LENGTH;
}

/**
 * Peer-owned content maps. Hub passes `new Peer(this.settings)` so lodash.merge
 * would otherwise alias nested `collections` / message logs into the observed
 * tree; commits then JSON-cloned Hub state on every socket.
 * @param {object} [input]
 * @returns {object}
 * @private
 */
function cloneJsonValue (value) {
  if (value == null || typeof value !== 'object') return value;
  if (Buffer.isBuffer(value)) return Buffer.from(value);
  if (Array.isArray(value)) return value.map(cloneJsonValue);
  const out = {};
  for (const key of Object.keys(value)) {
    out[key] = cloneJsonValue(value[key]);
  }
  return out;
}

function clonePlainObjectMap (value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const out = {};
  for (const key of Object.keys(value)) {
    out[key] = cloneJsonValue(value[key]);
  }
  return out;
}

function isolatePeerContent (input) {
  const defaults = {
    actors: {},
    channels: {},
    contracts: {},
    documents: {},
    documentRates: {},
    documentCreditRates: {},
    documentSealed: {},
    documentSealedBlobs: {},
    documentContentKeys: {},
    messages: {},
    services: {},
    collections: { documents: {} }
  };
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    return defaults;
  }
  const out = Object.assign({}, defaults);
  for (const key of Object.keys(defaults)) {
    if (key === 'collections') continue;
    if (input[key] && typeof input[key] === 'object' && !Array.isArray(input[key])) {
      out[key] = clonePlainObjectMap(input[key]);
    }
  }
  // Inventory still reads collections.documents for published / price / L1
  // metadata. Copy that subtree only; do not alias Hub collections.
  const srcDocs = input.collections && input.collections.documents;
  out.collections = { documents: clonePlainObjectMap(srcDocs) };
  return out;
}

/**
 * Node's URL parser keeps brackets on IPv6 hostnames (`tcp://[::1]:7777`
 * → hostname `[::1]`). Strip one pair so `net.createConnection` gets `::1`
 * and canonical keys stay `[::1]:port` rather than `[[::1]]:port`.
 * @param {*} hostname
 * @returns {string}
 * @private
 */
function hostnameWithoutIpv6Brackets (hostname) {
  const h = String(hostname || '');
  if (h.length >= 4 && h.charAt(0) === '[' && h.charAt(h.length - 1) === ']') {
    return h.slice(1, -1);
  }
  return h;
}

/**
 * Dial / candidate key: `host:port`, or `[v6]:port` so URL parse and retry maps agree.
 * @param {*} host
 * @param {*} port
 * @returns {string}
 * @private
 */
function canonicalPeerAddress (host, port) {
  const h = hostnameWithoutIpv6Brackets(String(host == null ? '' : host).trim());
  if (!h) return '';
  return h.includes(':') ? `[${h}]:${port}` : `${h}:${port}`;
}

