/**
 * Outer / generic types whose local registration side-effects are first-writer-wins.
 * Exact wire duplicates are already dropped via {@link Peer#messages} (buffer hash).
 * These types also no-op when the *logical* payload was already registered — including
 * re-signed copies of the same body (different AMP signature → different wire hash).
 * @private
 */
const LOGICAL_REGISTER_ONCE_TYPES = new Set([
  'CONTRACT_PUBLISH',
  'P2P_CONTRACT_PUBLISH',
  'DOCUMENT_PUBLISH',
  'DocumentPublish',
  'P2P_DOCUMENT_PUBLISH',
  'CONTRACT_PROPOSAL',
  'ContractProposal',
  'P2P_CONTRACT_PROPOSAL',
  'P2P_PEER_ANNOUNCE',
  'P2P_STATE_ANNOUNCE',
  // Tip / operator / identity registration frames (re-sign ≠ new event)
  'BitcoinBlock',
  'BITCOIN_BLOCK',
  'P2P_FLUSH_CHAIN',
  'FlushChain',
  'P2P_PEER_ALIAS',
  'DocumentContentKeyReveal',
  // Authorized sidechain patches: commitment-level replay (re-signed envelope ≠ new patch)
  'SIDECHAIN_STATE_PATCH'
]);

/**
 * Generic / base carriers may wrap a relay-as-is body (Hub transitional path).
 * Pin-check against the TCP peer would wrongly reject multisig / prior-hop authors.
 * @param {Message} message
 * @returns {boolean}
 * @private
 */
function isRelayAsIsGenericCarrier (message) {
  const outer = message && (message.type || message.friendlyType);
  if (!outer) return false;
  const carriers = new Set([
    'GENERIC_MESSAGE',
    'GenericMessage',
    'P2P_BASE_MESSAGE',
    'CHAT_MESSAGE',
    'ChatMessage'
  ]);
  if (!carriers.has(String(outer))) return false;
  try {
    const raw = messageDataToString(message.data);
    const pr = tryParseWireJsonBody(raw);
    if (!pr.ok || !pr.value || typeof pr.value !== 'object' || Array.isArray(pr.value)) {
      return false;
    }
    return isRelayAsIsWireType(pr.value.type);
  } catch (_) {
    return false;
  }
}

/**
 * @classdesc P2P node: TCP/NOISE sessions, gossip, and relay of {@link Message} (AMP) frames. Extends {@link Service}
 * (hence {@link Actor}). Opcode and receipt semantics must stay aligned with <strong>@fabric/http</strong> and Hub when you add types —
 * see {@link Message} wire vs friendly names and <code>constants</code> opcodes.
 * @class Peer
 * @extends Service
 */
class Peer extends Service {
  /**
   * Create an instance of {@link Peer}.
   * @param {Object} [config] Initialization Vector for this peer.
   * @param {Boolean} [config.listen] Whether or not to listen for connections.
   * @param {Boolean} [config.upnp] Whether or not to use UPNP for automatic configuration.
   * @param {Number} [config.port=7777] Port to use for P2P connections.
   * @param {Number} [config.listenPortAttempts=20] When the listen port is in use (`EADDRINUSE`),
   *   try the next port up to this many times (same host).
   * @param {Array} [config.peers=[]] List of initial peers.
   */
  constructor (config = {}) {
    super(config);

    this.name = 'Peer';
    this.settings = merge({
      constraints: {
        peers: {
          max: 0,
          shuffle: 8
        }
      },
      interface: '0.0.0.0',
      interval: 60000, // 1 minute
      network: 'regtest',
      networking: true, // Ensure networking is enabled by default
      listen: true,
      peers: [],
      // LevelDB path (Node) or IndexedDB name (browser)
      // In tests, default to no persistent registry to avoid reconnecting to
      // a developer machine's stale peer list (which can hang/timeout the suite).
      peersDb: (process.env.NODE_ENV === 'test') ? null : 'stores/hub/peers',
      port: 7777,
      listenPortAttempts: 20,
      reconnectToKnownPeers: true,
      // When true, answers INVENTORY_REQUEST: `offerBtc` (L1 offers) and `kind: 'documents'`
      // (Hub / browser catalog) using local `_state.content.documents` (+ optional rates/collections).
      serveLocalDocumentInventory: false,
      // When false (default), DOCUMENT_REQUEST queues for operator approve/deny.
      // When true, auto-sends P2P_FILE_SEND if held (convenient but amplifies egress).
      autoFulfillDocumentRequests: false,
      // When true (default), priced publishes seal AES-GCM; HTLC preimage = content key.
      sealPricedDocuments: true,
      // Attach P2TR HTLC fields on offerBtc inventory responses.
      attachInventoryHtlc: false,
      inventoryHtlcLocktimeHeight: null,
      inventoryBlobChunkBytes: Document.CHUNK_BYTES,
      // Privacy-preserving DocumentRequest rewrite + fee skim when maxSats set.
      relayPrivateDocumentRequests: false,
      documentRelayFeeSats: null,
      documentRelayFeeBps: 100,
      documentRelayMinRemainingSats: 1,
      documentRelayMaxHops: 4,
      // P2P_DOCUMENT_BID for a held per-blob chunk: false (default) only emits
      // `documentBid`; true asks the document's listed rate; a function
      // `(bid, held) => priceSats | null` prices it (null stays quiet).
      answerDocumentBids: false,
      // Opt-in only: approveDocumentRequest({ forceReveal: true }) without settlement.
      allowForceDocumentKeyReveal: false,
      // Re-send canonical DocumentPublish + pricing to new inbound peers.
      announceDocumentsOnPeerConnect: false,
      // If local inventory doesn't answer, optionally relay INVENTORY_REQUEST.
      relayInventoryRequest: false,
      // Optionally relay INVENTORY_RESPONSE to peers other than the sender.
      relayInventoryResponse: false,
      // When false, CONTRACT_PUBLISH is validated + flooded without storing
      // local contract state / patch allow-lists (gossip-relay nodes).
      registerInboundContracts: true,
      connectTimeout: 5000,
      // Inbound NOISE must finish before this; scanners that hold :7777 without
      // completing handshake would otherwise sit on the shared WASM bus.
      // Absolute deadline (not idle), so a byte-at-a-time handshake cannot extend it.
      handshakeTimeout: 10000,
      // Bytes a remote may send before the NOISE handshake completes.
      handshakeMaxBytes: NOISE_HANDSHAKE_MAX_BYTES,
      commitHistoryMax: 256,
      // Relay amplification controls for P2P_PEER_GOSSIP.
      gossip: {
        maxHops: GOSSIP_MAX_HOPS,
        maxRelaysPerOriginPerMinute: GOSSIP_MAX_RELAYS_PER_ORIGIN_PER_MINUTE,
        maxPayloadCache: GOSSIP_MAX_PAYLOAD_CACHE,
        maxWireHashCache: PEER_MAX_WIRE_HASH_CACHE
      },
      // Mesh chat amplify controls (local `chat` event still fires when limited).
      chat: {
        maxRelaysPerOriginPerMinute: CHAT_MAX_RELAYS_PER_ORIGIN_PER_MINUTE
      },
      maxPendingSealedDeliveries: PEER_MAX_PENDING_SEALED_DELIVERIES,
      maxPendingSealedBytes: PEER_MAX_PENDING_SEALED_BYTES,
      maxHeldChunkBytes: PEER_MAX_HELD_CHUNK_BYTES,
      pendingSealedTtlMs: PEER_PENDING_SEALED_TTL_MS,
      maxDocumentRelayRoutes: PEER_MAX_DOCUMENT_RELAY_ROUTES,
      state: Object.assign({
        actors: {},
        channels: {},
        contracts: {},
        documents: {},
        documentRates: {},
        documentCreditRates: {},
        documentSealed: {},
        documentSealedBlobs: {},
        documentContentKeys: {},
        messages: {},
        services: {}
      }, config.state),
      upnp: false,
      key: {},
      // Fabric P2P byte budget: Bitcoin L1 (1 MiB / 10 min) split across MAX_PEERS.
      bandwidth: {
        windowMs: BITCOIN_L1_BLOCK_INTERVAL_MS,
        windowBytes: BITCOIN_L1_BLOCK_BYTES,
        maxPeers: MAX_PEERS
      },
      // Inbound wire traffic budgeting (Bitcoin Core-style peer quality).
      wireTraffic: {
        windowMs: 60 * 1000,
        maxCreditsPerWindow: 520,
        chainSyncCreditCost: 55,
        flushChainCreditCost: 120,
        bitcoinBlockCreditCost: 3,
        relayCreditCost: PEER_RELAY_CREDIT_COST,
        defaultCreditCost: 1,
        overLimitPenalty: 22,
        sessionKeyViolationPenalty: PEER_SCORE_SESSION_KEY_VIOLATION_PENALTY
      },
      // Registry-score misbehavior penalties (see SECURITY.md).
      peerScore: {
        bodyHashMismatchPenalty: PEER_SCORE_BODY_HASH_MISMATCH_PENALTY,
        invalidSignaturePenalty: PEER_SCORE_INVALID_SIGNATURE_PENALTY,
        signerPinMismatchPenalty: PEER_SCORE_SIGNER_PIN_MISMATCH_PENALTY,
        contractOpsForbiddenPenalty: PEER_SCORE_CONTRACT_OPS_FORBIDDEN_PENALTY,
        logicalRegisterHijackPenalty: PEER_SCORE_LOGICAL_REGISTER_HIJACK_PENALTY,
        logicalRegisterDuplicatePenalty: PEER_SCORE_LOGICAL_REGISTER_DUPLICATE_PENALTY,
        logicalRegisterDuplicateWindowMs: PEER_SCORE_LOGICAL_REGISTER_DUPLICATE_WINDOW_MS,
        relayNestExceededPenalty: PEER_SCORE_RELAY_NEST_EXCEEDED_PENALTY,
        disconnectOnHardMisbehavior: true,
        banOnHardMisbehavior: true,
        banTtlMs: PEER_BAN_TTL_MS,
        maxRelayNestDepth: PEER_MAX_RELAY_NEST_DEPTH
      },
      // Inbound P2P_FLUSH_CHAIN: sender registry score must be strictly greater than this (relay uses same threshold).
      flushChainMinTrustedScore: 800,
      // Inbound P2P_FLUSH_CHAIN: allowed signer pubkeys (hex/Buffers); empty = reject all until configured.
      flushChainAuthorizedPubkeys: []
    }, config);

    this.settings.musig2 = Object.assign({
      autoAccept: false,
      maxSessions: PEER_MAX_MUSIG_SESSIONS,
      sessionTtlMs: PEER_MUSIG_SESSION_TTL_MS
    }, config.musig2);

    // FABRIC_INTERFACE / FABRIC_PEER_INTERFACE override bind when set.
    this.settings.interface = resolveFabricPeerInterface({
      interface: this.settings.interface,
      env: process.env
    });

    // Network Internals
    this.upnp = null;

    // Create a server only when listening is requested
    if (this.settings.listen) {
      this.server = net.createServer(this._NOISESocketHandler.bind(this));
    } else {
      // Minimal stub when neither listening nor networking is enabled
      this.server = {
        address: () => null,
        close: (cb) => cb && cb(),
        on: () => {}
      };
    }

    this.stream = new stream.Transform({
      transform (chunk, encoding, done) {
        done(null, chunk);
      }
    });

    const keyCfg = this.settings.key;
    const network = this.settings.network
      || (this.settings.bitcoin && this.settings.bitcoin.network)
      || 'regtest';
    if (keyCfg instanceof Key) {
      this.identity = new Identity(keyCfg);
      this.identity.settings.network = String(network);
      this.identity._state.content.network = String(network);
    } else {
      const base = (keyCfg && typeof keyCfg === 'object' && !Buffer.isBuffer(keyCfg))
        ? Object.assign({}, keyCfg)
        : (typeof keyCfg === 'string' ? { seed: keyCfg } : {});
      this.identity = new Identity(Object.assign(base, { network }));
    }
    // Protocol AMP / Schnorr / actor id use Identity#fabricKey (7777 mainnet / 7778 otherwise).
    // Master / fund root remains on identity.key for Bitcoin paths that need it.
    this.key = this.identity.fabricKey || new Key(this.settings.key);
    // this.wallet = new Wallet(this.settings.key);

    // this.hex = this.key.public.encodeCompressed('hex');
    // this.pkh = crypto.createHash('sha256').update(this.hex).digest('hex');

    // Public Details
    this.public = {
      ip: null,
      port: this.settings.port
    };

    // Internal properties
    this.actors = {};
    /** Connection name (`host:port`) → Actor id. */
    /** @type {Object<string, string>} */
    this._actorsByName = Object.create(null);
    this.contracts = {};
    this.chains = {};
    this.candidates = [];
    this.connections = {};
    this.history = [];
    this.peers = {};
    /** Pending DOCUMENT_REQUEST entries when {@link Peer#settings.autoFulfillDocumentRequests} is false. */
    this.pendingDocumentRequests = Object.create(null);
    /**
     * Authorized sealed-document key reveals: `"documentId|paymentHashHex"` → meta.
     * Populated only after verified settlement (never from public hash echo).
     */
    this._authorizedDocumentKeyReveals = new Map();
    /** contractId → Set of lowercase compressed pubkeys allowed to apply state ops. */
    this._contractPatchAllowList = Object.create(null);
    /** contractId → original CONTRACT_PUBLISH body (ARC genesis for ingest). */
    this._contractGenesis = Object.create(null);
    /** Buyer-side verified blob reassembly (DocumentBlobIndex). */
    this.blobTransfers = new DocumentBlobTransferBook();
    /** Ciphertext awaiting content-key reveal: documentId → meta. */
    this.pendingSealedDeliveries = Object.create(null);
    /** Per-blob sealed trees awaiting one `DocumentContentKeyReveal` per blob (types/document.js). */
    this.pendingSealedBlobs = Object.create(null);
    /** Running byte total of `pendingSealedBlobs`, and of unpinned rows per origin. */
    this._pendingSealedBytes = 0;
    this._pendingSealedOriginBytes = new Map();
    /**
     * Seller-private material for published sealed documents: documentId →
     * `{ keys: Map<index, K_i hex>, ciphertexts: Map<index, Buffer>, doc: Document|null }`.
     * Kept out of `_state` so keys and bytes never reach commits or observers.
     */
    this._sealedBlobSecrets = new Map();
    /** Seller: static payment hash `SHA256(K_i)` → `{ documentId, blobIndex }`. */
    this._sealedBlobByPaymentHash = new Map();
    /** Seller per-buyer quotes: paymentHashHex → `{ documentId, blobIndex, secretHex, priceSats, expiresAt, keyHashHex }`. */
    this._sealedBlobQuotes = new Map();
    /** Buyer: quotes received, paymentHashHex → `{ quote, origin, frameHex, received }`. */
    this._receivedBlobQuotes = new Map();
    /**
     * Opened convergent chunks, `"blobHashHex|paymentHashHex"` →
     * `{ keyHex, iv, scheme, convergence, ciphertext }`. A chunk another
     * document shares is opened from here instead of bought again. Bounded by
     * `maxHeldChunkBytes`, oldest first.
     */
    this._heldChunks = new Map();
    this._heldChunkBytes = 0;
    /**
     * Leaf records of convergent trees received here (`documentId` → hash-only
     * Document record, newest last, at most 256), so {@link Peer#seedDocument}
     * can sell the same tree again from the held chunks.
     */
    this._seedRecords = new Map();
    this._pendingDocumentRequestSeq = 0;
    /** Private reverse routes for rewritten DocumentRequests (never gossiped). */
    this._documentRelayRoutes = Object.create(null);
    this._documentRelaySeen = new Set();
    /** This Peer's own open bids: bid id → `{ bid, sentAt, book, sellers }`. */
    this._documentBids = new Map();
    /** Bids relayed here: bid id → `{ bid, prevHop, asks }` (the only route state; never gossiped). */
    this._documentBidRoutes = new Map();
    /** `host:port` → `{ windowStart, count }` for bids flooded onward. */
    this._documentBidRelayRate = new Map();
    // Peers: keyed by public key (id). Persistent registry in _state.peers.
    // Map connection address (IP:port) -> peer id (public key). Learned on P2P_SESSION_OFFER/OPEN.
    this._addressToId = {};
    /** Inbound address -> NOISE static pubkey hex (FLUSH_CHAIN allowlist only; never for AMP verify). */
    this._inboundNoiseStaticPubkeyByAddress = Object.create(null);
    this.mailboxes = {};
    this.memory = {};
    this.handlers = {};
    /** Wire-envelope dedup (SHA-256 of full buffer); FIFO-capped via {@link Peer#_rememberWireHash}. */
    this.messages = {};
    this._wireHashOrder = [];
    /**
     * Logical first-writer-wins registrations (content-addressed keys).
     * Catches re-signed duplicates of CONTRACT_PUBLISH / DOCUMENT_PUBLISH / etc.
     * @type {Map<string, { type: string, signer: string|null, at: number }>}
     */
    this._logicalRegisterOnce = new Map();
    this._logicalRegisterOrder = [];
    /** Logical gossip payload dedup (excludes signature / hop churn). */
    this._gossipPayloadSeen = new Map();
    this._gossipPayloadOrder = [];
    /** origin address → { count, windowStart } for gossip relay rate limiting. */
    this._gossipRelayByOrigin = new Map();
    /** origin address → { count, windowStart } for chat mesh relay rate limiting. */
    this._chatRelayByOrigin = new Map();
    /** Logical peering-offer payload dedup (ignores advisory peeringHop; frames relay as-is). */
    this._peeringPayloadSeen = new Map();
    this._peeringPayloadOrder = [];
    /** origin address → { count, windowStart } for peering-offer relay rate limiting. */
    this._peeringRelayByOrigin = new Map();
    /** `host:port` → { credits, windowStart, penalized } — inbound wire flood / de-rank (per peer). */
    this._wireInboundByOrigin = new Map();
    /** `host:port` → rolling L1-window byte counters (session + 10 min). */
    this._peerBandwidthByOrigin = new Map();
    /** `host:port` → { windowStart, penalized } — soft logical-duplicate derank once per window. */
    this._logicalDupPenaltyByOrigin = new Map();
    /**
     * Temporary bans after hard misbehavior: `addr:<host:port>` or `pk:<hex>` → { until, reason }.
     * @type {Map<string, { until: number, reason: string }>}
     */
    this._peerBans = new Map();
    /** `host:port` keys for {@link P2P_PEERING_OFFER} candidate queue dedup. */
    this._candidateKeys = new Set();
    /** `host:port` → next allowed dial (ms). Caps refused-candidate storms. */
    this._candidateRetryAt = new Map();
    /**
     * `host:port` strings we opened via {@link Peer#_connect} (outbound dials).
     * {@link P2P_SESSION_OFFER} must not destroy these when the same peer also opens an inbound
     * socket (mesh star): otherwise RPC paths that use the listen address (e.g. ChainSyncRequest)
     * see `peer not connected` while an ephemeral inbound key remains.
     */
    this._outboundDialTargets = new Set();
    /**
     * Addresses suppressed after a self-session (own Fabric key on the wire).
     * Map `host:port` → expiry ms (Date.now()).
     * @type {Map<string, number>}
     */
    this._selfDialSuppressUntil = new Map();
    this.sessions = {};
    /**
     * BIP-327 directed sessions keyed by sessionId hex.
     * @type {Map<string, object>}
     */
    this._musigSessions = new Map();
    this._musigSessionOrder = [];

    // Internal Stack Machine
    this.machine = new Machine({ key: this.settings.key });
    this.observer = null;

    this.meta = {
      messages: {
        inbound: 0,
        outbound: 0
      }
    };

    this.settings.state = isolatePeerContent(this.settings.state);
    this._state = {
      content: this.settings.state,
      peers: {}, // Peer registry keyed by public key (id). Persisted to LevelDB.
      chains: {},
      connections: {},
      status: 'sleeping'
    };

    return this;
  }

  /**
   * Stable id for gossip *logical* content (ignores advisory `gossipHop`; frames are forwarded bit-identical).
   * Mesh frames are relayed bit-identical; wire-hash dedup also prevents loops.
   * @param {object} msg Generic message (`type`, `object`, …)
   * @returns {string} hex sha256
   */
  _gossipPayloadDedupKey (msg) {
    const obj = Message.canonicalPeeringObject(msg && msg.object);
    const body = fabricCanonicalJson({ type: msg && msg.type, object: obj });
    return crypto.createHash('sha256').update(body).digest('hex');
  }

  _rememberWireHash (hash) {
    const max = (this.settings.gossip && this.settings.gossip.maxWireHashCache) || PEER_MAX_WIRE_HASH_CACHE;
    while (this._wireHashOrder.length >= max) {
      const drop = this._wireHashOrder.shift();
      delete this.messages[drop];
    }
    this.messages[hash] = true;
    this._wireHashOrder.push(hash);
  }

  /**
   * Content-addressed key for first-writer-wins registration types.
   * @param {string} type wire / generic type name
   * @param {object|null|undefined} object message body / object
   * @returns {string|null}
   */
  _logicalRegistrationKey (type, object) {
    const t = String(type || '');
    if (!LOGICAL_REGISTER_ONCE_TYPES.has(t)) return null;
    const obj = (object && typeof object === 'object' && !Array.isArray(object)) ? object : null;
    if (!obj) return null;

    if (t === 'CONTRACT_PUBLISH' || t === 'P2P_CONTRACT_PUBLISH') {
      return `contract:${new Actor(obj).id}`;
    }
    if (t === 'DOCUMENT_PUBLISH' || t === 'DocumentPublish') {
      const docId = obj.id != null ? String(obj.id) : '';
      if (!docId) return null;
      try {
        const hash = purchaseContentHashHex(docId, obj);
        return `document:${docId}:${hash}`;
      } catch (_) {
        return `document:${docId}`;
      }
    }
    if (t === 'P2P_DOCUMENT_PUBLISH') {
      const docId = obj.hash != null ? String(obj.hash) : (obj.id != null ? String(obj.id) : '');
      if (!docId) return null;
      const rate = obj.rate != null ? String(obj.rate) : '';
      const ch = obj.contentHash != null ? String(obj.contentHash) : '';
      return `docprice:${docId}:${rate}:${ch}`;
    }
    if (t === 'CONTRACT_PROPOSAL' || t === 'ContractProposal' || t === 'P2P_CONTRACT_PROPOSAL') {
      const root = obj.chain && obj.chain.merkleRoot != null
        ? String(obj.chain.merkleRoot)
        : (obj.merkleRoot != null ? String(obj.merkleRoot) : '');
      if (!root) return null;
      const cid = obj.contractId != null ? String(obj.contractId) : '';
      return `proposal:${cid}:${root}`;
    }
    if (t === 'P2P_PEER_ANNOUNCE') {
      return `announce:${new Actor(Message.canonicalPeeringObject(obj)).id}`;
    }
    if (t === 'P2P_STATE_ANNOUNCE') {
      const stateObj = (obj.state && typeof obj.state === 'object') ? obj.state : obj;
      return `state:${new Actor(stateObj).id}`;
    }
    if (t === 'BitcoinBlock' || t === 'BITCOIN_BLOCK') {
      const tip = obj.tip != null ? String(obj.tip)
        : (obj.hash != null ? String(obj.hash)
          : (obj.blockHash != null ? String(obj.blockHash)
            : (obj.content != null ? String(obj.content) : '')));
      if (!tip) return null;
      return `btcblock:${tip.toLowerCase()}`;
    }
    if (t === 'P2P_FLUSH_CHAIN' || t === 'FlushChain') {
      const snap = obj.snapshotBlockHash != null ? String(obj.snapshotBlockHash).trim().toLowerCase() : '';
      if (!snap) return null;
      return `flush:${snap}`;
    }
    if (t === 'P2P_PEER_ALIAS') {
      const alias = obj.alias != null ? String(obj.alias).trim() : '';
      const signer = obj.signer != null ? normalizePeerPubkeyHex(obj.signer) : '';
      if (!alias || !signer) return null;
      return `alias:${signer}:${alias}`;
    }
    if (t === 'DocumentContentKeyReveal') {
      // Bind the slot to SHA256(keyHex), not the attacker-supplied public hash field.
      // Mismatched / malformed reveals return null (no claim) — see isWellFormedKeyReveal.
      const docId = obj.documentId != null ? String(obj.documentId).trim() : '';
      const key = obj.keyHex != null ? String(obj.keyHex).trim().toLowerCase() : '';
      if (!docId || !/^[0-9a-f]{64}$/.test(key)) return null;
      const derived = paymentHashHexFromKey(key);
      const pay = obj.paymentHashHex != null ? String(obj.paymentHashHex).trim().toLowerCase() : '';
      if (pay && pay !== derived) return null;
      return `keyreveal:${docId}:${derived}`;
    }
    if (t === 'SIDECHAIN_STATE_PATCH') {
      try {
        const digest = sidechainState.patchCommitmentDigestHex({
          basisClock: obj.basisClock,
          basisDigest: obj.basisDigest,
          patches: obj.patches
        });
        if (!digest) return null;
        return `sidechain-patch:${digest}`;
      } catch (_) {
        return null;
      }
    }
    return null;
  }

  /**
   * Claim a logical registration key (first writer wins).
   * @param {string} type
   * @param {object|null|undefined} object
   * @param {string|null} [signerPubkeyHex]
   * @returns {{ duplicate: boolean, key: (string|null), prior: (object|null) }}
   */
  _claimLogicalRegistration (type, object, signerPubkeyHex = null) {
    const key = this._logicalRegistrationKey(type, object);
    if (!key) return { duplicate: false, key: null, prior: null };
    const prior = this._logicalRegisterOnce.get(key) || null;
    if (prior) return { duplicate: true, key, prior };
    const max = (this.settings.logicalRegister && this.settings.logicalRegister.maxCache) ||
      PEER_MAX_LOGICAL_REGISTER_CACHE;
    while (this._logicalRegisterOrder.length >= max) {
      const drop = this._logicalRegisterOrder.shift();
      this._logicalRegisterOnce.delete(drop);
    }
    const entry = {
      type: String(type || ''),
      signer: signerPubkeyHex ? normalizePeerPubkeyHex(signerPubkeyHex) : null,
      at: Date.now()
    };
    this._logicalRegisterOnce.set(key, entry);
    this._logicalRegisterOrder.push(key);
    return { duplicate: false, key, prior: null };
  }

  /**
   * Lower registry score and optionally destroy the TCP connection (hard misbehavior).
   * Hard disconnects also install a temporary ban (address + known pubkey).
   * @param {string|null|undefined} originName
   * @param {string} reason
   * @param {Object} [opts]
   * @param {number} [opts.penalty]
   * @param {boolean} [opts.disconnect]
   */
  _applyPeerMisbehavior (originName, reason, opts = {}) {
    const penalty = Number(opts.penalty);
    const pen = Number.isFinite(penalty) && penalty > 0 ? penalty : 20;
    const wantDisconnect = opts.disconnect === true;
    const ps = this.settings.peerScore || {};
    const hardDisconnect = ps.disconnectOnHardMisbehavior !== false;
    if (originName) {
      this._derankPeerForWireTraffic(originName, pen, reason);
    }
    this.emit('warning',
      `[FABRIC:PEER] Misbehavior (${reason}) from ${originName || 'unknown'} penalty=${pen}` +
      (wantDisconnect && hardDisconnect ? ' disconnect=1' : ''));
    if (wantDisconnect && hardDisconnect && originName) {
      if (ps.banOnHardMisbehavior !== false) {
        this._banPeer(originName, reason);
      }
      const conn = this.connections && this.connections[originName];
      if (conn && typeof conn.destroy === 'function') conn.destroy();
      // Drop registry of the live socket so reconnect/ban checks apply immediately.
      if (this.connections) delete this.connections[originName];
      if (this.peers && this.peers[originName] && typeof this.peers[originName] === 'object') {
        this.peers[originName].status = 'disconnected';
      }
    }
  }

  /**
   * Ban a connection address (and mapped pubkey when known) for {@link Peer#settings.peerScore.banTtlMs}.
   * @param {string} originName
   * @param {string} reason
   */
  _banPeer (originName, reason) {
    if (!originName) return;
    const ps = this.settings.peerScore || {};
    const ttl = Number(ps.banTtlMs);
    const banMs = Number.isFinite(ttl) && ttl > 0 ? ttl : PEER_BAN_TTL_MS;
    const until = Date.now() + banMs;
    const entry = { until, reason: String(reason || 'misbehavior') };
    this._peerBans.set(`addr:${originName}`, entry);
    const peerId = (this._addressToId && this._addressToId[originName]) || null;
    const reg = (this._state.peers && (this._state.peers[peerId] || this._state.peers[originName])) || null;
    const pk = normalizePeerPubkeyHex(
      (reg && reg.publicKey) ||
      (this.peers[originName] && this.peers[originName].publicKey) ||
      peerId
    );
    if (pk && pk.length >= 64) {
      this._peerBans.set(`pk:${pk}`, entry);
    }
    this.emit('warning',
      `[FABRIC:PEER] Banned ${originName}${pk ? ` pk=${pk.slice(0, 16)}…` : ''} until=${new Date(until).toISOString()} (${entry.reason})`);
  }

  /**
   * @param {string|null|undefined} originName
   * @param {string|null|undefined} [pubkeyHex]
   * @returns {boolean}
   */
  _isPeerBanned (originName = null, pubkeyHex = null) {
    const now = Date.now();
    for (const [k, v] of this._peerBans) {
      if (!v || !(v.until > now)) this._peerBans.delete(k);
    }
    if (originName && this._peerBans.has(`addr:${originName}`)) return true;
    const pk = normalizePeerPubkeyHex(pubkeyHex);
    if (pk && this._peerBans.has(`pk:${pk}`)) return true;
    if (originName) {
      const peerId = (this._addressToId && this._addressToId[originName]) || null;
      const reg = (this._state.peers && (this._state.peers[peerId] || this._state.peers[originName])) || null;
      const mapped = normalizePeerPubkeyHex(
        (reg && reg.publicKey) ||
        (this.peers[originName] && this.peers[originName].publicKey) ||
        peerId
      );
      if (mapped && this._peerBans.has(`pk:${mapped}`)) return true;
    }
    return false;
  }

  /**
   * Soft (once/window) or hijack (CONTRACT_PUBLISH other signer) penalty for logical duplicates.
   * @param {string|null|undefined} originName
   * @param {string} type
   * @param {Object} claim
   * @param {Object|null} [claim.prior]
   * @param {string|null} [claim.prior.signer]
   * @param {string|null} [signerPubkeyHex]
   */
  _logicalRegisterDuplicateMisbehavior (originName, type, claim, signerPubkeyHex = null) {
    const ps = this.settings.peerScore || {};
    const t = String(type || '');
    const current = signerPubkeyHex ? normalizePeerPubkeyHex(signerPubkeyHex) : null;
    const priorSigner = claim && claim.prior && claim.prior.signer
      ? normalizePeerPubkeyHex(claim.prior.signer)
      : null;
    const isHijack = (t === 'CONTRACT_PUBLISH' || t === 'P2P_CONTRACT_PUBLISH') &&
      priorSigner && current && priorSigner !== current;

    if (isHijack) {
      const penalty = Number(ps.logicalRegisterHijackPenalty) || PEER_SCORE_LOGICAL_REGISTER_HIJACK_PENALTY;
      this._applyPeerMisbehavior(originName, `logical-register-hijack:${t}`, {
        penalty,
        disconnect: false
      });
      return;
    }

    if (!originName) return;
    const windowMs = Number(ps.logicalRegisterDuplicateWindowMs) ||
      PEER_SCORE_LOGICAL_REGISTER_DUPLICATE_WINDOW_MS;
    const penalty = Number(ps.logicalRegisterDuplicatePenalty) ||
      PEER_SCORE_LOGICAL_REGISTER_DUPLICATE_PENALTY;
    const now = Date.now();
    let slot = this._logicalDupPenaltyByOrigin.get(originName);
    if (!slot || (now - slot.windowStart) >= windowMs) {
      slot = { windowStart: now, penalized: false };
    }
    if (slot.penalized) {
      this._logicalDupPenaltyByOrigin.set(originName, slot);
      return;
    }
    slot.penalized = true;
    this._logicalDupPenaltyByOrigin.set(originName, slot);
    this._applyPeerMisbehavior(originName, `logical-register-duplicate:${t}`, {
      penalty,
      disconnect: false
    });
  }

  /**
   * Claim logical registration; on duplicate, apply misbehavior and return claim.
   * @param {string} type
   * @param {object|null|undefined} object
   * @param {string|null} [signerPubkeyHex]
   * @param {string|null} [originName]
   * @returns {{ duplicate: boolean, key: (string|null), prior: (object|null) }}
   */
  _claimLogicalRegistrationOrPunish (type, object, signerPubkeyHex = null, originName = null) {
    const claim = this._claimLogicalRegistration(type, object, signerPubkeyHex);
    if (claim.duplicate) {
      this._logicalRegisterDuplicateMisbehavior(originName, type, claim, signerPubkeyHex);
    }
    return claim;
  }

  _gossipRememberPayload (key) {
    const max = (this.settings.gossip && this.settings.gossip.maxPayloadCache) || GOSSIP_MAX_PAYLOAD_CACHE;
    while (this._gossipPayloadOrder.length >= max) {
      const drop = this._gossipPayloadOrder.shift();
      this._gossipPayloadSeen.delete(drop);
    }
    this._gossipPayloadSeen.set(key, true);
    this._gossipPayloadOrder.push(key);
  }

  /**
   * @param {string} originName Connection id (e.g. `host:port`)
   * @returns {boolean}
   */
  _gossipRateLimitAllow (originName) {
    const limit = (this.settings.gossip && this.settings.gossip.maxRelaysPerOriginPerMinute) || GOSSIP_MAX_RELAYS_PER_ORIGIN_PER_MINUTE;
    const now = Date.now();
    let slot = this._gossipRelayByOrigin.get(originName);
    if (!slot || now - slot.windowStart > 60000) {
      slot = { count: 0, windowStart: now };
    }
    if (slot.count >= limit) return false;
    slot.count++;
    this._gossipRelayByOrigin.set(originName, slot);
    return true;
  }

  /**
   * @param {string} originName Connection id (e.g. `host:port`)
   * @returns {boolean}
   */
  _chatRateLimitAllow (originName) {
    const limit = (this.settings.chat && this.settings.chat.maxRelaysPerOriginPerMinute) ||
      CHAT_MAX_RELAYS_PER_ORIGIN_PER_MINUTE;
    const now = Date.now();
    let slot = this._chatRelayByOrigin.get(originName);
    if (!slot || now - slot.windowStart > 60000) {
      slot = { count: 0, windowStart: now };
    }
    if (slot.count >= limit) return false;
    slot.count++;
    this._chatRelayByOrigin.set(originName, slot);
    return true;
  }

  _capPendingSealedDeliveries () {
    const max = Number(this.settings.maxPendingSealedDeliveries);
    const cap = Number.isFinite(max) && max > 0 ? max : PEER_MAX_PENDING_SEALED_DELIVERIES;
    const ids = Object.keys(this.pendingSealedDeliveries);
    if (ids.length <= cap) return;
    ids.sort((a, b) => {
      const ta = (this.pendingSealedDeliveries[a] && this.pendingSealedDeliveries[a].updated) || 0;
      const tb = (this.pendingSealedDeliveries[b] && this.pendingSealedDeliveries[b].updated) || 0;
      return ta - tb;
    });
    const drop = ids.length - cap;
    for (let i = 0; i < drop; i++) {
      delete this.pendingSealedDeliveries[ids[i]];
    }
  }

  _capDocumentRelayRoutes () {
    const max = Number(this.settings.maxDocumentRelayRoutes);
    const cap = Number.isFinite(max) && max > 0 ? max : PEER_MAX_DOCUMENT_RELAY_ROUTES;
    const ids = Object.keys(this._documentRelayRoutes);
    if (ids.length <= cap) return;
    ids.sort((a, b) => {
      const ta = (this._documentRelayRoutes[a] && this._documentRelayRoutes[a].created) || 0;
      const tb = (this._documentRelayRoutes[b] && this._documentRelayRoutes[b].created) || 0;
      return ta - tb;
    });
    const drop = ids.length - cap;
    for (let i = 0; i < drop; i++) {
      delete this._documentRelayRoutes[ids[i]];
    }
  }

  /**
   * Credit cost for inbound wire messages (heavier types consume more of the peer's budget).
   * @param {string|number} wireType
   * @returns {number}
   */
  _wireInboundCreditCost (wireType) {
    const w = this.settings.wireTraffic || {};
    const t = wireType != null ? String(wireType) : '';
    if (t === 'P2P_CHAIN_SYNC_REQUEST' || t === 'ChainSyncRequest' || wireType === P2P_CHAIN_SYNC_REQUEST) {
      return Number(w.chainSyncCreditCost) || 55;
    }
    if (t === 'P2P_FLUSH_CHAIN' || t === 'FlushChain' || wireType === P2P_FLUSH_CHAIN) {
      return Number(w.flushChainCreditCost) || 120;
    }
    if (t === 'BITCOIN_BLOCK' || t === 'BitcoinBlock') {
      return Number(w.bitcoinBlockCreditCost) || 3;
    }
    if (t === 'P2P_FORWARD' || wireType === P2P_FORWARD) {
      return Number(w.forwardCreditCost) || 4;
    }
    if (t === 'P2P_RELAY' || wireType === P2P_RELAY) {
      return Number(w.relayCreditCost) || PEER_RELAY_CREDIT_COST;
    }
    return Number(w.defaultCreditCost) || 1;
  }

  /**
   * Apply rolling-window credits; on overflow, de-rank once per window and reject the message.
   * @param {string} originName connection key (host:port)
   * @param {number} creditCost
   * @returns {boolean} false = drop message
   */
  _wireInboundRateAllowPeer (originName, creditCost) {
    if (!originName) return true;
    const w = this.settings.wireTraffic || {};
    const windowMs = Number(w.windowMs) || 60000;
    const maxCredits = Number(w.maxCreditsPerWindow) || 520;
    const penalty = Number(w.overLimitPenalty) || 22;
    const now = Date.now();
    const cost = Number.isFinite(creditCost) && creditCost > 0 ? creditCost : 1;
    let slot = this._wireInboundByOrigin.get(originName);
    if (!slot || (now - slot.windowStart) >= windowMs) {
      slot = { credits: 0, windowStart: now, penalized: false };
    }
    const next = slot.credits + cost;
    if (next > maxCredits) {
      if (!slot.penalized) {
        slot.penalized = true;
        this._derankPeerForWireTraffic(originName, penalty, 'inbound-rate');
      }
      this._wireInboundByOrigin.set(originName, slot);
      return false;
    }
    slot.credits = next;
    this._wireInboundByOrigin.set(originName, slot);
    return true;
  }

  /**
   * Lower registry {@link Peer#knownPeers} score for a connection (Bitcoin Core misbehavior analogue).
   * @param {string} originName
   * @param {number} penalty
   * @param {string} reason
   */
  _derankPeerForWireTraffic (originName, penalty, reason) {
    const peerId = (this._addressToId && this._addressToId[originName]) || originName;
    const registry = this._state.peers || {};
    const reg = registry[peerId] || registry[originName] || {};
    const cur = Number(reg.score);
    const base = Number.isFinite(cur) ? cur : 0;
    const pen = Number.isFinite(penalty) && penalty > 0 ? penalty : 20;
    const next = Math.max(0, base - pen);
    this._upsertPeerRegistry(peerId, {
      id: peerId,
      address: reg.address || originName,
      score: next,
      lastSeen: new Date().toISOString()
    });
    this.emit('warning', `[FABRIC:PEER] De-ranked peer (${reason}): ${peerId} score ${base}→${next}`);
  }

  /**
   * L1 window + per-peer budget used for {@link Peer#knownPeers} bandwidth fields.
   * @returns {Object}
   * @private
   */
  _peerBandwidthOptions () {
    const bw = (this.settings && this.settings.bandwidth) || {};
    const constraintsMax = this.settings && this.settings.constraints && this.settings.constraints.peers
      ? Number(this.settings.constraints.peers.max)
      : NaN;
    const maxPeers = Number.isFinite(constraintsMax) && constraintsMax > 0
      ? Math.floor(constraintsMax)
      : (Number(bw.maxPeers) > 0 ? Math.floor(Number(bw.maxPeers)) : MAX_PEERS);
    const windowMs = Number(bw.windowMs) > 0 ? Number(bw.windowMs) : BITCOIN_L1_BLOCK_INTERVAL_MS;
    const windowBytes = Number(bw.windowBytes) > 0 ? Number(bw.windowBytes) : BITCOIN_L1_BLOCK_BYTES;
    return {
      windowMs,
      windowBytes,
      maxPeers,
      budgetBytes: perPeerBandwidthBudgetBytes(windowBytes, maxPeers)
    };
  }

  /**
   * Count plaintext AMP bytes on a connection (NOISE payload, after decrypt / before encrypt).
   * @param {string} originName `host:port`
   * @param {string} direction `in` or `out`
   * @param {*} n payload or length
   * @returns {void}
   * @private
   */
  _recordPeerBandwidth (originName, direction, n) {
    if (!originName) return;
    const opts = this._peerBandwidthOptions();
    const prev = this._peerBandwidthByOrigin.get(originName);
    const next = recordPeerBandwidth(prev, direction, n, Date.now(), opts.windowMs);
    this._peerBandwidthByOrigin.set(originName, next);
  }

  /**
   * Snapshot for one connection or registry address.
   * @param {string} address
   * @returns {Object}
   * @private
   */
  _peerBandwidthSnapshotForAddress (address) {
    const opts = this._peerBandwidthOptions();
    const slot = address && this._peerBandwidthByOrigin ? this._peerBandwidthByOrigin.get(address) : null;
    return peerBandwidthSnapshot(slot, Date.now(), opts);
  }

  /**
   * Drop idle bandwidth slots when the map grows past live connections plus a small remainder.
   * @returns {void}
   * @private
   */
  _prunePeerBandwidthMaps () {
    const map = this._peerBandwidthByOrigin;
    if (!map || map.size <= 256) return;
    const live = this.connections && typeof this.connections === 'object' ? this.connections : {};
    for (const key of map.keys()) {
      if (!Object.prototype.hasOwnProperty.call(live, key)) map.delete(key);
      if (map.size <= 256) return;
    }
  }

  /**
   * Node-wide Fabric P2P bandwidth vs the L1 1 MiB / 10 min target.
   * @returns {Object}
   */
  get bandwidthSummary () {
    const opts = this._peerBandwidthOptions();
    const seen = new Set();
    const snaps = [];
    const connections = this.connections && typeof this.connections === 'object' ? this.connections : {};
    for (const address of Object.keys(connections)) {
      seen.add(address);
      snaps.push(this._peerBandwidthSnapshotForAddress(address));
    }
    if (this._peerBandwidthByOrigin) {
      for (const address of this._peerBandwidthByOrigin.keys()) {
        if (seen.has(address)) continue;
        seen.add(address);
        snaps.push(this._peerBandwidthSnapshotForAddress(address));
      }
    }
    return aggregatePeerBandwidth(snaps, {
      windowMs: opts.windowMs,
      windowBytes: opts.windowBytes,
      maxPeers: opts.maxPeers,
      peerBudgetBytes: opts.budgetBytes
    });
  }

  /**
   * Stable id for peering-offer *logical* content (ignores advisory `peeringHop`).
   * @param {object} msg Generic message (`type`, `object`, …)
   * @returns {string} hex sha256
   */
  _peeringOfferPayloadDedupKey (msg) {
    const obj = Message.canonicalPeeringObject(msg && msg.object);
    const body = fabricCanonicalJson({ type: msg && msg.type, object: obj });
    return crypto.createHash('sha256').update(body).digest('hex');
  }

  _peeringRememberPayload (key) {
    const max = (this.settings.peering && this.settings.peering.maxPayloadCache) || PEERING_OFFER_MAX_PAYLOAD_CACHE;
    while (this._peeringPayloadOrder.length >= max) {
      const drop = this._peeringPayloadOrder.shift();
      this._peeringPayloadSeen.delete(drop);
    }
    this._peeringPayloadSeen.set(key, true);
    this._peeringPayloadOrder.push(key);
  }

  /**
   * @param {string} originName Connection id (e.g. `host:port`)
   * @returns {boolean}
   */
  _peeringRateLimitAllow (originName) {
    const limit = (this.settings.peering && this.settings.peering.maxRelaysPerOriginPerMinute) || PEERING_OFFER_MAX_RELAYS_PER_ORIGIN_PER_MINUTE;
    const now = Date.now();
    let slot = this._peeringRelayByOrigin.get(originName);
    if (!slot || now - slot.windowStart > 60000) {
      slot = { count: 0, windowStart: now };
    }
    if (slot.count >= limit) return false;
    slot.count++;
    this._peeringRelayByOrigin.set(originName, slot);
    return true;
  }

  /**
   * Enqueue a fabric candidate from {@link P2P_PEERING_OFFER}; FIFO-capped and deduped by host:port.
   * @param {string} host
   * @param {number} port
   * @param {Object} [meta]
   * @param {string} [meta.pubkey] Optional advertised Fabric pubkey (informational).
   * @param {string} [meta.verifiedPubkey] AMP/session-verified pubkey; self-dial suppress uses this only.
   */
  _enqueuePeeringCandidate (host, port, meta = {}) {
    const normalizedHost = typeof host === 'string' ? host.trim() : '';
    const normalizedPort = Number(port);
    if (!normalizedHost ||
        !Number.isInteger(normalizedPort) ||
        normalizedPort < 1 ||
        normalizedPort > 65535) {
      return;
    }
    const key = canonicalPeerAddress(normalizedHost, normalizedPort);
    if (this._isSelfDialSuppressed(key)) return;
    // Only suppress from a verified AMP/session pubkey — remote `obj.pubkey` is
    // attacker-controlled and must not poison dial targets for ~10 minutes.
    if (meta.verifiedPubkey && this._isOwnFabricPubkey(meta.verifiedPubkey)) {
      this.emit('warning',
        `[FABRIC:PEER] Skipping peering candidate ${key}: verified pubkey is our own`);
      this._suppressSelfDialAddress(key);
      return;
    }
    const max = (this.settings.peering && this.settings.peering.maxCandidates) || PEER_MAX_CANDIDATES_QUEUE;
    if (this._candidateKeys.has(key)) return;
    while (this.candidates.length >= max) {
      const old = this.candidates.shift();
      const o = old && (old.object || old);
      if (o && o.host != null && o.port != null) {
        const evicted = canonicalPeerAddress(o.host, o.port);
        this._candidateKeys.delete(evicted);
        if (this._candidateRetryAt) this._candidateRetryAt.delete(evicted);
      }
    }
    this._candidateKeys.add(key);
    const pubkey = meta.pubkey ? normalizePeerPubkeyHex(meta.pubkey) : '';
    const verifiedPubkey = meta.verifiedPubkey
      ? normalizePeerPubkeyHex(meta.verifiedPubkey)
      : '';
    // Omit empty pubkey — callers historically expect `{ host, port }` when unknown.
    const candidate = { host: normalizedHost, port: normalizedPort };
    if (pubkey) candidate.pubkey = pubkey;
    if (verifiedPubkey) candidate.verifiedPubkey = verifiedPubkey;
    this.candidates.push(candidate);
  }

  /**
   * Local Fabric session pubkey (x-only hex), same normalization as wire signers.
   * @returns {string}
   */
  _localFabricPubkeyHex () {
    try {
      if (this.key && this.key.public && typeof this.key.public.encodeCompressed === 'function') {
        return normalizePeerPubkeyHex(this.key.public.encodeCompressed('hex'));
      }
    } catch (_) { /* fall through */ }
    return normalizePeerPubkeyHex(this.key && (this.key.pubkey || this.id));
  }

  /**
   * @param {*} hex
   * @returns {boolean}
   */
  _isOwnFabricPubkey (hex) {
    const remote = normalizePeerPubkeyHex(hex);
    const local = this._localFabricPubkeyHex();
    return !!(remote && local && remote === local);
  }

  /**
   * @param {*} id
   * @returns {boolean}
   */
  _isOwnFabricActorId (id) {
    const mine = this.identity && this.identity.id != null ? String(this.identity.id) : '';
    return !!(mine && id != null && String(id) === mine);
  }

  /**
   * @param {string} address
   * @param {number} [ttlMs=600000]
   */
  _suppressSelfDialAddress (address, ttlMs = 600000) {
    const addr = String(address || '').trim();
    if (!addr) return;
    const ttl = Number(ttlMs);
    const until = Date.now() + (Number.isFinite(ttl) && ttl > 0 ? ttl : 600000);
    if (!this._selfDialSuppressUntil) this._selfDialSuppressUntil = new Map();
    // Sweep expired entries, then FIFO-cap (remote peers drive insertion).
    const now = Date.now();
    for (const [k, v] of this._selfDialSuppressUntil) {
      if (!(v > now)) this._selfDialSuppressUntil.delete(k);
    }
    this._selfDialSuppressUntil.set(addr, until);
    const max = Number(this.settings && this.settings.selfDialSuppressMax) > 0
      ? Number(this.settings.selfDialSuppressMax)
      : 256;
    while (this._selfDialSuppressUntil.size > max) {
      const oldest = this._selfDialSuppressUntil.keys().next().value;
      this._selfDialSuppressUntil.delete(oldest);
    }
  }

  /**
   * @param {string} address
   * @returns {boolean}
   */
  _isSelfDialSuppressed (address) {
    const addr = String(address || '').trim();
    if (!addr || !this._selfDialSuppressUntil) return false;
    const until = this._selfDialSuppressUntil.get(addr);
    if (until == null) return false;
    if (Date.now() >= until) {
      this._selfDialSuppressUntil.delete(addr);
      return false;
    }
    return true;
  }

  /**
   * Tear down a TCP/NOISE session that presented our own Fabric identity.
   * Emits `peer:self` so apps can drop the address from dial lists.
   * @param {string|null|undefined} connAddress
   * @param {string} [reason]
   * @returns {Peer}
   */
  _abortSelfFabricSession (connAddress, reason = 'own Fabric identity') {
    const addr = connAddress ? String(connAddress) : '';
    this.emit('warning', `[FABRIC:PEER] Closing self-session ${addr || '(unknown)'}: ${reason}`);
    this.emit('peer:self', { address: addr || null, reason: String(reason) });
    if (addr) {
      this._suppressSelfDialAddress(addr);
      if (this._outboundDialTargets) this._outboundDialTargets.delete(addr);
      if (this._candidateKeys) this._candidateKeys.delete(addr);
      if (Array.isArray(this.candidates)) {
        this.candidates = this.candidates.filter((c) => {
          const h = c && (c.address || canonicalPeerAddress(c.host, c.port));
          return h !== addr;
        });
      }
      const sock = this.connections && this.connections[addr];
      if (sock) {
        // Centralized teardown (idempotent per socket); unit stubs have destroy()
        // but no _destroyFabric, so call the Peer method directly.
        this._destroyFabric(sock, addr);
        try {
          if (typeof sock.destroy === 'function' && !sock.destroyed) sock.destroy();
        } catch (_) { /* ignore */ }
      }
    }
    return this;
  }

  get id () {
    return this.key.pubkey;
  }

  /**
   * Shared WASM handshake-bus listener counts (three events per in-flight session).
   * @returns {{ write: number, read: number, split: number }}
   */
  countNoiseHandshakeListeners () {
    if (typeof noise.countHandshakeListeners === 'function') {
      return noise.countHandshakeListeners();
    }
    return { write: 0, read: 0, split: 0 };
  }

  get pubkeyhash () {
    // `this.key` is the Fabric identity key (m/7777'/{7777|7778}'/0'/0/0), not the master.
    return this.key.pubkeyhash;
  }

  /**
   * @deprecated
   */
  get address () {
    return this.settings.interface || this.settings.address;
  }

  get documentation () {
    return {
      name: 'Fabric',
      description: 'Manages connections to the Fabric Network.',
      methods: {
        ack: {
          description: 'Acknowledge a message.',
          parameters: {
            message: {
              // TODO: consider making this a FabricMessageID
              type: 'FabricMessage',
              description: 'The message to acknowledge.'
            }
          },
          returns: {
            type: 'Promise',
            description: 'A Promise which resolves to the completed FabricState.'
          }
        },
        send: {
          description: 'Send a message to a connected peer.',
          parameters: {
            message: {
              type: 'FabricMessage',
              description: 'The message to send to the peer.'
            }
          },
          returns: {
            type: 'Promise',
            description: 'A Promise which resolves to the response (if any).'
          }
        },
        broadcast: {
          description: 'Broadcast a message to all connected nodes.',
          parameters: {
            message: {
              type: 'FabricMessage',
              description: 'The message to send to the node.'
            }
          },
          returns: {
            type: 'Promise',
            description: 'A Promise which resolves to the responses (if any).'
          }
        }
      }
    };
  }

  get interface () {
    return this.settings.interface || this.settings.address;
  }

  get port () {
    const p = this.settings.port;
    return (typeof p === 'number' && !Number.isNaN(p)) ? p : 7777;
  }

  get publicPeers () {
    const peers = [];
    const addressToId = this._addressToId || {};

    // Connections are keyed by IP:port. Map each to peer id (public key) when known.
    for (const address in this.connections) {
      if (!Object.prototype.hasOwnProperty.call(this.connections, address)) continue;
      const socket = this.connections[address];
      const id = addressToId[address] || address;

      peers.push({
        id,
        address,
        status: 'connected',
        lastMessage: socket._lastMessage || null
      });
    }

    // Then, include any known peers that are not currently connected.
    for (const key in this.peers) {
      if (!Object.prototype.hasOwnProperty.call(this.peers, key)) continue;

      // Skip if this peer is already represented as a connected peer.
      if (peers.find((p) => p.id === key || p.address === key)) continue;

      const peer = this.peers[key];
      const id = peer && peer.id ? peer.id : key;
      const address = peer && peer.address ? peer.address : key;

      peers.push({
        id,
        address,
        status: 'disconnected'
      });
    }

    return peers;
  }

  /**
   * Registry plus live connections. Each row includes rolling Fabric P2P
   * bandwidth (`bytesIn` / `bytesOut` / `windowBytes` vs L1 `budgetBytes`).
   * @returns {object[]}
   */
  get knownPeers () {
    const now = new Date().toISOString();
    const byId = {};
    const registry = this._state.peers || {};
    const addressToId = this._addressToId || {};

    // Start from persisted registry (keyed by id)
    for (const key in registry) {
      if (!Object.prototype.hasOwnProperty.call(registry, key)) continue;
      const reg = registry[key];
      const id = reg.id || key;
      byId[id] = {
        id,
        address: reg.address || key,
        status: 'disconnected',
        score: reg.score != null ? reg.score : 0,
        firstSeen: reg.firstSeen,
        lastSeen: reg.lastSeen,
        nickname: reg.nickname,
        alias: reg.alias,
        lastMessage: reg.lastMessage
      };
      Object.assign(byId[id], this._peerBandwidthSnapshotForAddress(byId[id].address));
    }

    // Overlay current connections (map address -> id, then update byId)
    for (const address in this.connections) {
      if (!Object.prototype.hasOwnProperty.call(this.connections, address)) continue;
      const socket = this.connections[address];
      const id = addressToId[address] || address;
      if (!byId[id]) byId[id] = { id, address, status: 'connected', score: 0 };
      byId[id].status = 'connected';
      byId[id].address = address;
      byId[id].lastMessage = socket._lastMessage || byId[id].lastMessage;
      if (socket._alias) byId[id].alias = socket._alias;
      Object.assign(byId[id], this._peerBandwidthSnapshotForAddress(address));
    }

    // Include any this.peers not yet in registry
    for (const key in this.peers) {
      if (!Object.prototype.hasOwnProperty.call(this.peers, key)) continue;
      const peer = this.peers[key];
      const id = (peer && peer.id) || key;
      if (byId[id]) continue;
      byId[id] = {
        id,
        address: key,
        status: 'disconnected',
        score: 0,
        lastSeen: now
      };
      Object.assign(byId[id], this._peerBandwidthSnapshotForAddress(key));
    }

    return Object.values(byId);
  }

  _resolveToAddress (idOrAddress) {
    if (!idOrAddress || typeof idOrAddress !== 'string') return null;
    if (this.connections[idOrAddress]) return idOrAddress;
    const addressToId = this._addressToId || {};
    for (const addr in addressToId) {
      if (addressToId[addr] === idOrAddress && this.connections[addr]) return addr;
    }
    const registry = this._state.peers || {};
    const entry = registry[idOrAddress];
    if (entry && entry.address && this.connections[entry.address]) return entry.address;
    return null;
  }

  beat () {
    const now = (new Date()).toISOString();
    const clock = this._clock | 0;
    this.commit();
    this.emit('beat', {
      created: now,
      clock: clock,
      initial: { type: 'FabricActorState', object: { clock: clock } },
      state: { clock: clock }
    });

    return this;
  }

  /**
   * Write a {@link Buffer} to all connected peers.
   * @param {Buffer} message Message buffer to send.
   * @param {string|null} [origin] Skip this connection id (usually the inbound origin).
   * @returns {number} Count of peers the frame was written to.
   */
  broadcast (message, origin = null) {
    if (this.settings.debug) this.emit('debug', `Broadcasting message (${message && message.length ? message.length : 0} bytes)`);
    let sent = 0;
    for (const id in this.connections) {
      this.emit('debug', `Broadcast [!!!] — evaluating connection: ${id}`);
      if (id === origin) continue;
      this.connections[id]._writeFabric(message);
      sent += 1;
    }
    return sent;
  }

  connectTo (address) {
    this._connect(address);
    return this;
  }

  relayFrom (origin, message, socket = null) {
    for (const id in this.connections) {
      if (id === origin) continue;
      this.connections[id]._writeFabric(message.toBuffer(), socket);
    }
  }

  /**
   * Local node x-only pubkey (AMP {@code author} / {@code P2P_FORWARD.nextPeer} encoding).
   * @returns {Buffer}
   */
  _localXOnlyPeerId () {
    return xOnlyFromKey(this.key);
  }

  /**
   * Resolve a live connection address for an x-only (or compressed) peer pubkey.
   * @param {Buffer|string} peerId
   * @returns {string|null} connection key ({@code host:port}) or null
   */
  _resolveAddressByXOnly (peerId) {
    let want;
    try {
      want = toXOnlyPeerId(peerId);
    } catch (_) {
      return null;
    }
    if (xOnlyEquals(want, this._localXOnlyPeerId())) return null;

    const connections = this.connections || {};
    for (const addr of Object.keys(connections)) {
      const rec = this.peers[addr];
      if (!rec || rec.publicKey == null) continue;
      try {
        if (xOnlyEquals(want, toXOnlyPeerId(rec.publicKey))) return addr;
      } catch (_) {
        // ignore malformed registry keys
      }
    }

    const registry = this._state.peers || {};
    for (const key of Object.keys(registry)) {
      const entry = registry[key];
      if (!entry) continue;
      const pk = entry.publicKey || entry.pubkey;
      if (pk == null) continue;
      try {
        if (!xOnlyEquals(want, toXOnlyPeerId(pk))) continue;
      } catch (_) {
        continue;
      }
      const addr = entry.address || key;
      if (addr && connections[addr]) return addr;
      const resolved = this._resolveToAddress(addr) || this._resolveToAddress(key);
      if (resolved) return resolved;
    }
    return null;
  }

  /**
   * Send {@code payload} along a source-routed onion path of Fabric peer pubkeys.
   * Builds nested {@code P2P_FORWARD} layers and writes the outer frame only to
   * {@code path[0]} (immediate hop). Destination learns the last hop's IP, not
   * the originator's. See {@link module:@fabric/core/functions/fabricOnion}.
   *
   * @param {Array<Buffer|string>} path hop pubkeys; first = next TCP peer, last = deliverer
   * @param {Message|Buffer} payload innermost application Message (should already be signed)
   * @returns {boolean} true if the outer frame was written to the first hop
   */
  sendOnion (path, payload) {
    if (!Array.isArray(path) || !path.length) {
      this.emit('warning', '[FABRIC:PEER] sendOnion: empty path');
      return false;
    }
    let outer;
    try {
      outer = wrapOnionPath({ path, payload, key: this.key });
    } catch (err) {
      this.emit('warning', `[FABRIC:PEER] sendOnion wrap failed: ${err && err.message ? err.message : err}`);
      return false;
    }
    const first = path[0];
    const addr = this._resolveAddressByXOnly(first) || this._resolveToAddress(
      typeof first === 'string' ? first : null
    );
    if (!addr || !this.connections[addr] || !this.connections[addr]._writeFabric) {
      this.emit('warning', '[FABRIC:PEER] sendOnion: first hop not connected');
      this.emit('onion:undeliverable', { path, reason: 'first-hop-missing' });
      return false;
    }
    this.connections[addr]._writeFabric(outer.toBuffer());
    this.emit('onion:sent', { pathLength: path.length, firstHop: addr });
    return true;
  }

  /**
   * Begin a directed BIP-327 MuSig2 session (n-of-n) with connected peers.
   * Co-signers ignore inbound START unless `settings.musig2.autoAccept === true`.
   *
   * @param {object} [opts]
   * @param {Buffer|string} opts.msg message to sign (hashed to 32 bytes unless already 32)
   * @param {Array<Buffer|string>} [opts.pubkeys] compressed participants; default local + dest
   * @param {Buffer|string} [opts.dest] peer pubkey or `host:port` for the first hop
   * @param {string} [opts.purpose]
   * @returns {object|null} public session view
   */
  startMusig2 (opts = {}) {
    const sk = this._musigLocalSecret();
    if (!sk) {
      this.emit('warning', '[FABRIC:PEER] startMusig2: no local secret');
      return null;
    }
    const localPk = individualPk(sk);
    let pubkeys = opts.pubkeys;
    if (!pubkeys || !pubkeys.length) {
      const destPk = this._musigDestPubkey(opts.dest || opts.peerId || opts.address);
      if (!destPk) {
        this.emit('warning', '[FABRIC:PEER] startMusig2: dest pubkey required');
        return null;
      }
      pubkeys = [localPk, destPk];
    }
    let session;
    try {
      session = musig2Session.createLocalSession({
        msg: opts.msg,
        pubkeys,
        sk,
        purpose: opts.purpose || '',
        initiator: true
      });
    } catch (err) {
      this.emit('warning', `[FABRIC:PEER] startMusig2: ${err && err.message ? err.message : err}`);
      return null;
    }
    this._musigPut(session);
    this._musigSend('P2P_MUSIG_START', musig2Session.startFields(session), session);
    this.emit('musig2:start', musig2Session.sessionPublicView(session));
    return musig2Session.sessionPublicView(session);
  }

  /**
   * Public MuSig2 session snapshot (no secret nonce).
   * @param {Buffer|string} sessionId
   * @returns {object|null}
   */
  getMusig2Session (sessionId) {
    return musig2Session.sessionPublicView(this._musigGet(sessionId));
  }

  /**
   * @returns {Buffer|null}
   * @private
   */
  _musigLocalSecret () {
    const k = this.key && this.key.private;
    if (Buffer.isBuffer(k) && k.length === 32) return k;
    if (typeof k === 'string' && /^[0-9a-f]{64}$/i.test(k.trim())) {
      return Buffer.from(k.trim(), 'hex');
    }
    return null;
  }

  /**
   * @param {Buffer|string} dest
   * @returns {Buffer|null}
   * @private
   */
  _musigDestPubkey (dest) {
    if (dest == null || dest === '') return null;
    try {
      const buf = Buffer.isBuffer(dest) ? dest : Buffer.from(String(dest).replace(/^0x/i, ''), 'hex');
      if (buf.length === 33) return buf;
    } catch {
      // host:port or non-hex
    }
    const addr = this._resolveAddressByXOnly(dest) || this._resolveToAddress(String(dest));
    if (!addr) return null;
    const rec = (this.peers && this.peers[addr]) || null;
    const pk = rec && (rec.publicKey || rec.pubkey);
    if (!pk) return null;
    try {
      const buf = Buffer.isBuffer(pk) ? pk : Buffer.from(String(pk).replace(/^0x/i, ''), 'hex');
      if (buf.length === 33) return buf;
    } catch {
      return null;
    }
    return null;
  }

  /**
   * @param {Buffer|string} sessionId
   * @returns {string}
   * @private
   */
  _musigSessionKey (sessionId) {
    if (Buffer.isBuffer(sessionId)) return sessionId.toString('hex');
    return String(sessionId || '').toLowerCase().replace(/^0x/i, '');
  }

  /**
   * Opt-in only. Default `musig2.autoAccept` is false so inbound START cannot
   * turn the identity key into a remote signing oracle.
   * @returns {boolean}
   * @private
   */
  _musigAutoAccept () {
    return !!(this.settings.musig2 && this.settings.musig2.autoAccept === true);
  }

  /**
   * @returns {number}
   * @private
   */
  _musigSessionCap () {
    const raw = Number(this.settings.musig2 && this.settings.musig2.maxSessions);
    if (!Number.isFinite(raw) || raw < 1) return PEER_MAX_MUSIG_SESSIONS;
    return Math.min(Math.floor(raw), PEER_MAX_MUSIG_SESSIONS);
  }

  /**
   * @returns {number}
   * @private
   */
  _musigSessionTtlMs () {
    const raw = Number(this.settings.musig2 && this.settings.musig2.sessionTtlMs);
    if (!Number.isFinite(raw) || raw < 1) return PEER_MUSIG_SESSION_TTL_MS;
    return Math.floor(raw);
  }

  /**
   * @param {object} session
   * @private
   */
  _musigPut (session) {
    const id = this._musigSessionKey(session.sessionId);
    if (this._musigSessions.has(id)) {
      const idx = this._musigSessionOrder.indexOf(id);
      if (idx >= 0) this._musigSessionOrder.splice(idx, 1);
    }
    this._musigSessions.set(id, session);
    this._musigSessionOrder.push(id);
    const cap = this._musigSessionCap();
    while (this._musigSessionOrder.length > cap) {
      const evict = this._musigSessionOrder.shift();
      const old = this._musigSessions.get(evict);
      musig2Session.wipeSession(old);
      this._musigSessions.delete(evict);
    }
  }

  /**
   * @param {Buffer|string} sessionId
   * @returns {object|null}
   * @private
   */
  _musigGet (sessionId) {
    const id = this._musigSessionKey(sessionId);
    const session = this._musigSessions.get(id);
    if (!session) return null;
    const ttl = this._musigSessionTtlMs();
    if (ttl > 0 && Date.now() - (session.createdAt || 0) > ttl) {
      musig2Session.wipeSession(session);
      this._musigSessions.delete(id);
      const idx = this._musigSessionOrder.indexOf(id);
      if (idx >= 0) this._musigSessionOrder.splice(idx, 1);
      return null;
    }
    return session;
  }

  /**
   * @param {string} type
   * @param {object} fields
   * @param {object} session
   * @private
   */
  _musigSend (type, fields, session) {
    let frame;
    try {
      frame = Message.fromFields(type, fields).signWithKey(this.key);
    } catch (err) {
      this.emit('warning', `[FABRIC:PEER] MuSig2 encode ${type}: ${err && err.message ? err.message : err}`);
      return;
    }
    const wire = frame.toBuffer();
    const localX = musig2Session.xOnlyHex(session.pubkeys[session.localIndex]);
    for (const pk of session.pubkeys) {
      if (musig2Session.xOnlyHex(pk) === localX) continue;
      const addr = this._resolveAddressByXOnly(pk);
      if (!addr || !this.connections[addr] || !this.connections[addr]._writeFabric) {
        this.emit('warning', `[FABRIC:PEER] MuSig2: no live connection for ${musig2Session.xOnlyHex(pk)}`);
        continue;
      }
      this.connections[addr]._writeFabric(wire);
    }
  }

  /**
   * @param {object} session
   * @private
   */
  _musigMaybeProgress (session) {
    if (!session || session.signature) return;
    const auto = this._musigAutoAccept();
    if (session.initiator && musig2Session.allPubnoncesPresent(session) && !session.aggnonce) {
      const aggnonce = musig2Session.computeAggNonce(session);
      if (aggnonce) {
        session.aggnonce = aggnonce;
        this._musigSend('P2P_MUSIG_SEND_PROPOSAL', {
          sessionId: session.sessionId,
          aggnonce
        }, session);
      }
    }
    if ((session.initiator || auto) &&
        session.aggnonce &&
        session.secnonce &&
        !session.psigs[session.localIndex]) {
      const sk = this._musigLocalSecret();
      const signed = sk ? musig2Session.createPartial(session, sk) : { ok: false };
      if (signed.ok) {
        this._musigSend('P2P_MUSIG_REPLY_TO_PROPOSAL', {
          sessionId: session.sessionId,
          psig: signed.psig
        }, session);
      }
    }
    if (session.initiator && musig2Session.allPartialsPresent(session) && !session.signature) {
      const agg = musig2Session.aggregatePartials(session);
      if (agg.ok) {
        this._musigSend('P2P_MUSIG_ACCEPT_PROPOSAL', {
          sessionId: session.sessionId,
          signature: agg.signature
        }, session);
        this.emit('musig2:complete', musig2Session.sessionPublicView(session));
      } else {
        this.emit('warning', `[FABRIC:PEER] MuSig2 aggregate failed: ${agg.reason}`);
      }
    }
  }

  /**
   * Directed BIP-327 frames — never mesh-flooded; peel / foreign RELAY ignored.
   * @private
   */
  _handleMusig2Message (message, origin, socket, opts = {}) {
    const delivery = meshDeliveryContext(opts, origin && origin.name);
    if (!delivery.allowTcpOriginSideEffects) {
      this.emit('warning',
        `[FABRIC:PEER] Ignoring ${message.type} delivered via peel/relay-as-is`);
      return this;
    }
    const signerXOnly = opts.signerPubkeyHex || this._verifiedFabricSignerPubkeyHex(message);
    if (!signerXOnly) {
      this.emit('warning', `[FABRIC:PEER] ${message.type} missing verified signer`);
      return this;
    }
    const parsedBody = Message.tryParseMessageBody(message);
    if (!parsedBody.ok) {
      this.emit('warning', `[FABRIC:PEER] ${message.type} parse failed: ${parsedBody.error.message}`);
      return this;
    }
    const body = musig2Session.parseMusigBody(parsedBody.value);
    if (!body) {
      this.emit('warning', `[FABRIC:PEER] ${message.type} invalid MuSig2 body`);
      return this;
    }
    const type = message.type;
    if (type === 'P2P_MUSIG_START') {
      this._handleMusig2Start(body, signerXOnly);
      return this;
    }
    const session = this._musigGet(body.sessionId);
    if (!session) {
      this.emit('warning', `[FABRIC:PEER] ${type} for unknown session`);
      return this;
    }
    if (type === 'P2P_MUSIG_ACCEPT' || type === 'P2P_MUSIG_RECEIVE_COUNTER') {
      const rec = musig2Session.recordPubnonce(session, signerXOnly, body.pubnonce);
      if (!rec.ok) {
        this.emit('warning', `[FABRIC:PEER] ${type} rejected: ${rec.reason}`);
        return this;
      }
      this._musigMaybeProgress(session);
      return this;
    }
    if (type === 'P2P_MUSIG_SEND_PROPOSAL') {
      const initiatorPk = session.pubkeys && session.pubkeys[session.initiatorIndex];
      const initiatorXOnly = initiatorPk ? musig2Session.xOnlyHex(initiatorPk) : '';
      if (!initiatorXOnly || String(signerXOnly).toLowerCase() !== initiatorXOnly) {
        this.emit('warning', `[FABRIC:PEER] SEND_PROPOSAL rejected: not-initiator`);
        return this;
      }
      const set = musig2Session.setAggNonce(session, body.aggnonce);
      if (!set.ok) {
        this.emit('warning', `[FABRIC:PEER] SEND_PROPOSAL rejected: ${set.reason}`);
        return this;
      }
      this._musigMaybeProgress(session);
      return this;
    }
    if (type === 'P2P_MUSIG_REPLY_TO_PROPOSAL') {
      const rec = musig2Session.recordPartial(session, signerXOnly, body.psig);
      if (!rec.ok) {
        this.emit('warning', `[FABRIC:PEER] REPLY rejected: ${rec.reason}`);
        return this;
      }
      this._musigMaybeProgress(session);
      return this;
    }
    if (type === 'P2P_MUSIG_ACCEPT_PROPOSAL') {
      const v = musig2Session.verifyFinalSignature(session, body.signature);
      if (!v.ok) {
        this.emit('warning', `[FABRIC:PEER] ACCEPT_PROPOSAL rejected: ${v.reason}`);
        return this;
      }
      this.emit('musig2:complete', musig2Session.sessionPublicView(session));
      return this;
    }
    return this;
  }

  /**
   * @param {object} body
   * @param {string} signerXOnly
   * @private
   */
  _handleMusig2Start (body, signerXOnly) {
    const existing = this._musigGet(body.sessionId);
    if (existing) {
      const rec = musig2Session.recordPubnonce(existing, signerXOnly, body.pubnonce);
      if (!rec.ok) {
        this.emit('warning', `[FABRIC:PEER] duplicate START rejected: ${rec.reason}`);
      }
      return this;
    }
    if (!this._musigAutoAccept()) {
      this.emit('warning', '[FABRIC:PEER] P2P_MUSIG_START ignored: musig2.autoAccept is off');
      return this;
    }
    const sk = this._musigLocalSecret();
    if (!sk) {
      this.emit('warning', '[FABRIC:PEER] P2P_MUSIG_START: no local secret');
      return this;
    }
    const made = musig2Session.createFromStart(body, { sk, signerXOnly });
    if (!made.ok) {
      this.emit('warning', `[FABRIC:PEER] P2P_MUSIG_START ignored: ${made.reason}`);
      return this;
    }
    const session = made.session;
    this._musigPut(session);
    if (this._musigAutoAccept()) {
      const others = [];
      for (let i = 0; i < session.pubkeys.length; i++) {
        if (i !== session.initiatorIndex) others.push(i);
      }
      const first = others.length ? Math.min.apply(null, others) : session.localIndex;
      const replyType = session.localIndex === first
        ? 'P2P_MUSIG_ACCEPT'
        : 'P2P_MUSIG_RECEIVE_COUNTER';
      this._musigSend(replyType, {
        sessionId: session.sessionId,
        pubnonce: session.ownPubnonce
      }, session);
    }
    this.emit('musig2:start', musig2Session.sessionPublicView(session));
    return this;
  }

  /**
   * Handle inbound {@code P2P_FORWARD}: peel when {@code nextPeer} is local, else
   * forward the bit-identical outer frame to that peer only (no mesh flood).
   * @private
   */
  _handleP2PForward (message, origin, socket) {
    const fields = tryDecodeForward(message);
    if (!fields) {
      this.emit('warning', '[FABRIC:PEER] P2P_FORWARD body undecodable');
      return this;
    }
    if (fields.ttl < 1) {
      if (this.settings.debug) {
        this.emit('debug', '[FABRIC:PEER] Dropped P2P_FORWARD with ttl=0');
      }
      return this;
    }

    const local = this._localXOnlyPeerId();
    if (xOnlyEquals(fields.nextPeer, local)) {
      this.emit('onion:peel', {
        ttl: fields.ttl,
        origin: origin && origin.name,
        innerBytes: fields.inner.length
      });
      if (fields.inner.length > 0) {
        // Peeled inners must not hard-disconnect / derank the TCP last hop:
        // relays forward bit-identical outers, so a malicious originator can
        // launder a bad inner through an honest relay (see SECURITY.md / P2P_FORWARD).
        this._handleFabricMessage(fields.inner, origin, socket, { peeledForward: true });
      }
      return this;
    }

    const addr = this._resolveAddressByXOnly(fields.nextPeer);
    if (!addr || !this.connections[addr] || !this.connections[addr]._writeFabric) {
      this.emit('warning', '[FABRIC:PEER] P2P_FORWARD next hop not connected');
      this.emit('onion:undeliverable', {
        nextPeer: fields.nextPeer.toString('hex'),
        origin: origin && origin.name,
        reason: 'next-hop-missing'
      });
      return this;
    }
    if (origin && origin.name && addr === origin.name) {
      this.emit('warning', '[FABRIC:PEER] P2P_FORWARD refuses bounce to origin');
      return this;
    }

    // Bit-identical forward — do not re-sign; path builder signature stays intact.
    const wire = (message && typeof message.toBuffer === 'function')
      ? message.toBuffer()
      : null;
    if (!wire || !wire.length) {
      this.emit('warning', '[FABRIC:PEER] P2P_FORWARD missing wire buffer');
      return this;
    }
    this.connections[addr]._writeFabric(wire);
    this.emit('onion:forward', {
      nextHop: addr,
      ttl: fields.ttl,
      origin: origin && origin.name
    });
    return this;
  }

  /**
   * Relay an AMP message only to connected peers whose persistent registry score is strictly greater than
   * {@link Peer#settings.flushChainMinTrustedScore} (default 800). Used for `P2P_FLUSH_CHAIN`.
   * @param {string|null} origin - Connection key to skip (inbound sender), or null when originating locally.
   * @param {Message|Buffer} message
   * @param {number} [minScoreExclusive] - Override trust threshold (relay if peer score &gt; this value).
   */
  relayFromTrustedPeers (origin, message, minScoreExclusive = null) {
    const threshold = (minScoreExclusive != null && Number.isFinite(Number(minScoreExclusive)))
      ? Number(minScoreExclusive)
      : (Number(this.settings.flushChainMinTrustedScore) || 800);
    const buf = Buffer.isBuffer(message) ? message : message.toBuffer();
    for (const id in this.connections) {
      if (origin && id === origin) continue;
      const score = this._registryScoreForConnectionAddress(id);
      if (!(score > threshold)) continue;
      this.connections[id]._writeFabric(buf);
    }
  }

  /**
   * Best-effort registry score for a live connection key (`host:port`), using mapped Fabric id when known.
   * @param {string} connAddress
   * @returns {number}
   */
  _registryScoreForConnectionAddress (connAddress) {
    const reg = this._state.peers || {};
    const mappedId = this._addressToId && this._addressToId[connAddress];
    let best = 0;
    for (const key of [mappedId, connAddress]) {
      if (!key) continue;
      const e = reg[key];
      if (!e) continue;
      const s = Number(e.score);
      if (Number.isFinite(s) && s > best) best = s;
    }
    return best;
  }

  /**
   * FLUSH_CHAIN trust score bound to verified sender key.
   *
   * Prevents trusting attacker-controlled `P2P_SESSION_OFFER.actor.id` aliases
   * by refusing `_addressToId`-mapped scores unless that mapped registry entry
   * is explicitly bound to the same verified sender pubkey.
   *
   * @param {string} connAddress
   * @param {string} senderPubkeyHex - verified sender pubkey hex (from NOISE/static or trusted peer record)
   * @returns {number}
   */
  _registryScoreForFlushChainSender (connAddress, senderPubkeyHex) {
    const reg = this._state.peers || {};
    const senderHex = normalizePeerPubkeyHex(senderPubkeyHex);
    const candidates = new Set();
    if (connAddress) candidates.add(connAddress);
    if (senderHex) candidates.add(senderHex);

    const mappedId = this._addressToId && this._addressToId[connAddress];
    if (mappedId && senderHex) {
      const mapped = reg[mappedId];
      if (mapped && typeof mapped === 'object') {
        const mappedPk = normalizePeerPubkeyHex(mapped.publicKey);
        // Only trust mapped id score when mapped record is key-bound.
        if (mappedPk && mappedPk === senderHex) candidates.add(mappedId);
      }
    }

    let best = 0;
    for (const key of candidates) {
      const e = reg[key];
      if (!e) continue;
      const s = Number(e.score);
      if (Number.isFinite(s) && s > best) best = s;
    }

    return best;
  }

  /**
   * Sign and send `P2P_FLUSH_CHAIN` to all connected peers with registry score &gt; threshold.
   * Body JSON: `{ snapshotBlockHash, network?, label? }`.
   *
   * **Receivers** (see `P2P_FLUSH_CHAIN` handler) require **both**:
   * 1. Sender pubkey in {@link Peer#settings.flushChainAuthorizedPubkeys} (non-empty allowlist), and
   * 2. Registry score above {@link Peer#settings.flushChainMinTrustedScore}.
   * Registry score bumps on `P2P_PONG` only when that pong answers an outbound ping on the same
   * connection (`_fabricPingOutstanding`), so unsolicited pongs cannot inflate trust alone.
   *
   * @param {Object} object
   * @returns {number} number of sockets written
   */
  sendFlushChainToTrustedPeers (object) {
    const body = JSON.stringify(object && typeof object === 'object' ? object : {});
    const msg = Message.fromVector(['P2P_FLUSH_CHAIN', body]).signWithKey(this.key);
    const buf = msg.toBuffer();
    const threshold = Number(this.settings.flushChainMinTrustedScore) || 800;
    let n = 0;
    for (const id in this.connections) {
      if (!(this._registryScoreForConnectionAddress(id) > threshold)) continue;
      this.connections[id]._writeFabric(buf);
      n++;
    }
    return n;
  }

  subscribe (_path) {

  }

  _beginFabricHandshake (client) {
    const keyClaim = this._buildSessionKeyExchangeClaim(this.identity.id);
    // Start handshake
    const vector = ['P2P_SESSION_OFFER', JSON.stringify({
      type: 'P2P_SESSION_OFFER',
      actor: {
        id: this.identity.id,
        pubkey: keyClaim.pubkey,
        parentPubkey: keyClaim.parentPubkey,
        parentXpub: keyClaim.parentXpub,
        parentSignature: keyClaim.parentSignature
      },
      object: {
        challenge: crypto.randomBytes(8).toString('hex'),
        maxFrameBytes: this._localMaxFrameBytes()
      }
    })];

    // Create offer message
    const P2P_SESSION_OFFER = Message.fromVector(vector).signWithKey(this.key);
    const message = P2P_SESSION_OFFER.toBuffer();
    if (this.settings.debug) this.emit('debug', `session_offer ${P2P_SESSION_OFFER} ${message.toString('hex')}`);

    // Send handshake
    try {
      client.encrypt.write(message);
    } catch (exception) {
      if (exception && (exception.code === 'EPIPE' || exception.code === 'ECONNRESET')) {
        this.emit('warning', `Suppressing transient write error (${exception.code}) during handshake.`);
      } else {
        this.emit('error', `Cannot write to socket: ${exception}`);
      }
    }

    return this;
  }

  /**
   * Open a Fabric connection to the target address and initiate the Fabric Protocol.
   * @param {String} target Target address.
   */
  _connect (target) {
    if (!target || typeof target !== 'string') {
      this.emit('error', '[FABRIC:PEER:_connect] target must be a non-empty string');
      return;
    }

    // Do not dedup on the raw string: pubkey@host:port must share the host:port slot.
    if (this._isPeerBanned(target)) {
      this.emit('warning', `[FABRIC:PEER:_connect] Refusing dial to banned peer ${target}`);
      return;
    }

    if (this._isSelfDialSuppressed(target)) {
      this.emit('warning', `[FABRIC:PEER:_connect] Refusing dial to self-suppressed ${target}`);
      return;
    }

    const url = new URL(`tcp://${target}`);
    const id = url.username;
    const host = hostnameWithoutIpv6Brackets(url.hostname);
    const port = url.port || P2P_PORT;
    // Dedup on host:port so pubkey@host:port and host:port share one in-flight slot.
    const canonical = canonicalPeerAddress(host, port);

    // pubkey@host:port — refuse when the pin is our own Fabric key (pre-TCP).
    if (id && this._isOwnFabricPubkey(id)) {
      this.emit('warning',
        `[FABRIC:PEER:_connect] Refusing dial to ${target}: pinned pubkey is our own`);
      this._suppressSelfDialAddress(canonical);
      this.emit('peer:self', { address: target, reason: 'pinned pubkey is own Fabric key' });
      return;
    }

    target = canonical;

    // After normalizing port, check suppress and in-flight dials on host:port.
    if (this._isSelfDialSuppressed(target)) {
      this.emit('warning', `[FABRIC:PEER:_connect] Refusing dial to self-suppressed ${target}`);
      return;
    }

    if (this.connections[target] ||
        (this._outboundDialTargets && this._outboundDialTargets.has(target))) {
      this.emit('debug', `[FABRIC:PEER:_connect] Already connected or dialing ${target}; skipping`);
      return;
    }

    this._outboundDialTargets.add(target);
    this.emit('debug', `[FABRIC:PEER:_connect] Attempting to connect to: ${target}`);

    let socket;
    let _derived;
    try {
      _derived = this.identity.key.derive(FABRIC_KEY_DERIVATION_PATH);
      this.emit('debug', `[FABRIC:PEER:_connect] Local derived key (public hex, truncated): ${peerDebugDerivedPublicSummary(_derived)} path=${FABRIC_KEY_DERIVATION_PATH}`);

      // Store the user's public key if provided
      if (id) {
        this.peers[target] = {
          ...this.peers[target],
          publicKey: id
        };
      }

      this._registerActor({ name: target });
      this._registerPeer({ identity: id });
      this._upsertPeerRegistry(target, { address: target });

      // Set up the NOISE socket
      socket = net.createConnection(url.port || P2P_PORT, host);
    } catch (err) {
      if (this._outboundDialTargets) this._outboundDialTargets.delete(target);
      throw err;
    }
    // Don't keep the test runner alive just because we're connecting.
    if (typeof socket.unref === 'function') socket.unref();

    // Bound connection establishment time; otherwise Node's TCP timeout can be long.
    const connectTimeoutMs = (typeof this.settings.connectTimeout === 'number')
      ? this.settings.connectTimeout
      : 5000;
    socket.setTimeout(connectTimeoutMs);
    const onConnectTimeout = () => {
      const msg = `Socket timeout: connect ${host}:${url.port || P2P_PORT} after ${connectTimeoutMs}ms`;
      this.emit('warning', msg);
      socket.destroy(new Error(msg));
    };
    socket.once('timeout', onConnectTimeout);

    socket._destroyFabric = () => {
      this._destroyFabric(socket, target);
    };

    socket.on('error', (error) => {
      this.emit('debug', `--- debug error from _connect() ---`);
      if (this._isTransientSocketError(error)) {
        const code = (error && error.code) || 'ECONNREFUSED';
        this.emit('warning', `Suppressing transient outbound socket error (${code}) from _connect().`);
      } else {
        const msg = `Socket error: ${error}`;
        // Avoid crashing consumers/tests that haven't registered an 'error' listener.
        if (this.listenerCount('error') > 0) this.emit('error', msg);
        else this.emit('warning', msg);
      }
    });

    socket.on('open', (info) => {
      this.emit('debug', `Socket open: ${info}`);
    });

    socket.on('close', (info) => {
      this.emit('debug', `Outbound socket closed: (${target}) ${info}`);
      if (typeof socket._destroyFabric === 'function') socket._destroyFabric();
      // this._scheduleReconnect(target);
    });

    socket.on('end', (info) => {
      this.emit('debug', `Socket end: (${target}) ${info}`);
      // delete this.connections[target];
    });

    // Do not construct NOISE until TCP is up. Shared WASM handshake bus
    // listeners are per session until split/destroy (see functions/noiseProtocolStream).
    socket.once('connect', () => {
      try {
        socket.removeListener('timeout', onConnectTimeout);
        socket.setTimeout(0);
        if (socket.destroyed) return;
        const client = noise(Object.assign(this._noiseTransportOptions(), {
          initiator: true,
          prologue: Buffer.from(PROLOGUE),
          // privateKey: _derived.privkey — enable when NOISE static === Fabric derived key.
          verify: this._verifyNOISE.bind(this)
        }));
        this._attachNoiseStreamErrorHandlers(client, 'NOISE');
        this._bindNoiseTransportToSocket(client, socket);
        const handshakeTimeoutMs = (typeof this.settings.handshakeTimeout === 'number')
          ? this.settings.handshakeTimeout
          : 10000;
        if (handshakeTimeoutMs > 0) {
          socket.setTimeout(handshakeTimeoutMs);
          socket.once('timeout', () => {
            if (socket._fabricNoiseHandshakeOk) return;
            const msg = `Socket timeout: NOISE handshake ${host}:${url.port || P2P_PORT} after ${handshakeTimeoutMs}ms`;
            this.emit('warning', msg);
            socket.destroy(new Error(msg));
          });
        }
        client.encrypt.once('handshake', () => {
          socket._fabricNoiseHandshakeOk = true;
          socket.setTimeout(0);
        });
        client.decrypt.on('data', (data) => {
          this._recordPeerBandwidth(target, 'in', data);
          this._handleFabricMessage(data, { name: target }, client);
        });
        client.encrypt.pipe(socket).pipe(client.decrypt);
        this._registerNOISEClient(target, socket, client);
        this._beginFabricHandshake(client);
        this.emit('connections:open', {
          address: target,
          id: target,
          url: url
        });
      } catch (err) {
        this.emit('warning',
          `[FABRIC:PEER:_connect] outbound setup failed (${target}): ${err && err.message ? err.message : err}`);
        if (typeof socket.destroy === 'function') socket.destroy();
      }
    });
  }

  /**
   * Broadcast a personal nickname as first-class {@link P2P_PEER_ALIAS}
   * (UTF-8 body = nickname text only).
   * @param {string} alias
   * @param {{name: (string|undefined)}|null} [origin] Optional origin to exclude from broadcast
   * @param {*} [_socket] Unused (API compatibility)
   */
  _announceAlias (alias, origin = null, _socket = null) {
    const name = String(alias || '').trim().slice(0, P2P_PEER_ALIAS_MAX_CHARS);
    if (!name) return;
    const packet = Message.fromVector(['P2P_PEER_ALIAS', name]);
    if (this.key) packet.signWithKey(this.key);
    const announcement = packet.toBuffer();
    const exclude = origin && origin.name ? origin.name : null;
    this.broadcast(announcement, exclude);
  }

  _destroyFabric (socket, target) {
    if (socket && socket._fabricDestroyed) return;
    if (socket) socket._fabricDestroyed = true;
    if (socket && socket._keepalive) clearInterval(socket._keepalive);
    this._teardownNoiseClient(socket);

    if (this._outboundDialTargets) this._outboundDialTargets.delete(target);

    delete this.connections[target];
    delete this.peers[target];
    if (this._inboundNoiseStaticPubkeyByAddress) delete this._inboundNoiseStaticPubkeyByAddress[target];
    if (this._addressToId) delete this._addressToId[target];
    this._unregisterSocketActor(target);
    this._prunePeerBandwidthMaps();

    this.emit('connections:close', {
      address: target,
      name: target
    });
  }

  /**
   * Load persistent peer registry from LevelDB.
   * Uses classic-level in Node, browser-level (IndexedDB) in browser.
   * @returns {Promise<void>}
   */
  async _loadPeerRegistry () {
    const location = this.settings.peersDb;
    if (!location) return;

    try {
      this._peersDb = this._peersDb || new Level(location);
      const raw = await this._peersDb.get('peers').catch(() => null);
      let peers = {};
      if (raw != null && raw !== '') {
        const pr = tryParsePersistedJson(utf8FromPersistedRaw(raw));
        if (pr.ok && pr.value !== null && typeof pr.value === 'object' && !Array.isArray(pr.value)) {
          peers = pr.value;
        } else if (!pr.ok) {
          this.emit('debug', `[FABRIC:PEER] Peer registry JSON invalid or oversized: ${pr.error.message}`);
        }
      }
      if (peers && typeof peers === 'object') {
        // Migrate legacy address-keyed entries to id-keyed (id is the fixed public key)
        const migrated = {};
        for (const key of Object.keys(peers)) {
          const entry = peers[key];
          const id = entry && entry.id;
          if (id) {
            migrated[id] = merge({ id, address: key }, entry);
          } else {
            // No id yet (pre-handshake); keep keyed by address until we learn id
            migrated[key] = merge({ address: key }, entry);
          }
        }
        this._state.peers = migrated;
        if (this.settings.debug) this.emit('debug', `[FABRIC:PEER] Loaded peer registry: ${Object.keys(this._state.peers).length} entries`);
      }
    } catch (err) {
      this.emit('debug', `[FABRIC:PEER] No peer registry or load error: ${err && err.message}`);
      if (!this._state.peers) this._state.peers = {};
    }
  }

  /**
   * Persist peer registry to LevelDB (debounced).
   */
  _savePeerRegistry () {
    const location = this.settings.peersDb;
    if (!location) return;
    if (this._state.status === 'STOPPING' || this._state.status === 'STOPPED') return;

    if (this._peerRegistrySaveScheduled) clearTimeout(this._peerRegistrySaveScheduled);

    this._peerRegistrySaveScheduled = setTimeout(() => {
      this._peerRegistrySaveScheduled = null;
      if (this._state.status === 'STOPPING' || this._state.status === 'STOPPED') return;
      this._peersDb = this._peersDb || new Level(location);
      // Avoid noisy errors from writes scheduled while DB is closing/closed.
      if (this._peersDb && this._peersDb.status && this._peersDb.status !== 'open') return;
      const payload = JSON.stringify(this._state.peers || {});
      this._peersDb.put('peers', payload)
        .then(() => { if (this.settings.debug) this.emit('debug', '[FABRIC:PEER] Saved peer registry'); })
        .catch((err) => {
          const message = err && err.message ? err.message : String(err);
          if (message.includes('Database is not open')) return;
          this.emit('error', `Failed to save peer registry: ${message}`);
        });
    }, 500);
  }

  /** FLUSH_CHAIN sender hex: {@link Peer#peers}[addr].publicKey if set, else inbound NOISE static (allowlist must match). */
  _flushChainSenderPubkeyHex (connectionAddress) {
    if (!connectionAddress) return '';
    const rec = this.peers[connectionAddress];
    if (rec && typeof rec === 'object' && rec.publicKey != null && rec.publicKey !== '') {
      const h = normalizePeerPubkeyHex(rec.publicKey);
      if (h) return h;
    }
    const noise = this._inboundNoiseStaticPubkeyByAddress[connectionAddress];
    return noise ? normalizePeerPubkeyHex(noise) : '';
  }

  /**
   * Verify Fabric message signature against the message's own on-wire author field.
   * Returns normalized x-only signer pubkey hex on success.
   * @private
   * @param {Message} message
   * @returns {string}
   */
  _verifiedFabricSignerPubkeyHex (message) {
    if (!message || !message.raw || !message.raw.author) return '';
    const xOnly = normalizePeerPubkeyHex(message.raw.author);
    if (!/^[0-9a-f]{64}$/.test(xOnly)) return '';
    try {
      // Canonical compressed form; verifyWithKey checks x-only author parity-independently.
      const signer = new Key({ public: `02${xOnly}` });
      if (!message.verifyWithKey(signer)) return '';
      return xOnly;
    } catch {
      return '';
    }
  }

  /**
   * Stable message covered by parent-key signature to bind a session child key claim.
   * @private
   */
  _sessionKeyProofMessage (peerId, childPubkeyHex, parentPubkeyHex) {
    return [
      'fabric-session-key-proof-v1',
      String(peerId || ''),
      normalizePeerPubkeyHex(childPubkeyHex),
      normalizePeerPubkeyHex(parentPubkeyHex)
    ].join(':');
  }

  /**
   * Build signed key-exchange claim for early Fabric session messages.
   * Child key signs the Fabric message envelope; parent key signs child binding.
   * @private
   */
  _buildSessionKeyExchangeClaim (peerId = this.identity.id) {
    const childPubkey = this.key.public.encodeCompressed('hex');
    const parentPubkey = this.key.public.encodeCompressed('hex');
    const proofMsg = this._sessionKeyProofMessage(peerId, childPubkey, parentPubkey);
    const parentSignature = this.key.signSchnorr(proofMsg, SIGNING_TAGS.SESSION_KEY).toString('hex');
    return {
      pubkey: childPubkey,
      parentPubkey,
      parentXpub: this.key.xpub || null,
      parentSignature
    };
  }

  /**
   * Validate claimed session key exchange against verified wire signer key.
   * Missing/invalid signatures are protocol violations and are penalized.
   * @private
   */
  _validateSessionKeyExchangeClaim (genericMessage, signerPubkeyHex, originName, opts = {}) {
    const actor = (genericMessage && genericMessage.actor && typeof genericMessage.actor === 'object')
      ? genericMessage.actor
      : {};
    const peerId = actor.id;
    const claimedChild = normalizePeerPubkeyHex(actor.pubkey || actor.publicKey);
    const claimedParent = normalizePeerPubkeyHex(actor.parentPubkey || actor.parentPublicKey);
    const parentSigHex = typeof actor.parentSignature === 'string' ? actor.parentSignature.trim() : '';
    const punishOpts = { peeledForward: opts.peeledForward === true };

    if (!claimedChild || !claimedParent || !parentSigHex) {
      this._punishPeerForSessionKeyViolation(originName, 'missing session key signature material', punishOpts);
      return false;
    }
    if (!/^[0-9a-f]{64}$/.test(claimedChild) || !/^[0-9a-f]{64}$/.test(claimedParent)) {
      this._punishPeerForSessionKeyViolation(originName, 'invalid session key format', punishOpts);
      return false;
    }
    if (!/^[0-9a-f]{128}$/.test(parentSigHex)) {
      this._punishPeerForSessionKeyViolation(originName, 'invalid parent signature format', punishOpts);
      return false;
    }
    if (claimedChild !== normalizePeerPubkeyHex(signerPubkeyHex)) {
      this._punishPeerForSessionKeyViolation(originName, 'claimed child key does not match signer', punishOpts);
      return false;
    }

    const proofMsg = this._sessionKeyProofMessage(peerId, claimedChild, claimedParent);
    let ok = false;
    try {
      const parentKey = new Key({ public: `02${claimedParent}` });
      ok = parentKey.verifySchnorr(proofMsg, Buffer.from(parentSigHex, 'hex'), SIGNING_TAGS.SESSION_KEY);
    } catch {
      ok = false;
    }
    if (!ok) {
      this._punishPeerForSessionKeyViolation(originName, 'invalid parent signature', punishOpts);
      return false;
    }

    return { peerId, childPubkey: claimedChild, parentPubkey: claimedParent, parentXpub: actor.parentXpub || null };
  }

  /**
   * Penalize protocol violations around unsigned/unverifiable session key claims.
   * @private
   * @param {string|null|undefined} originName
   * @param {string} reason
   * @param {Object} [opts]
   * @param {boolean} [opts.peeledForward]
   */
  _punishPeerForSessionKeyViolation (originName, reason, opts = {}) {
    const peeledForward = opts.peeledForward === true;
    const penalty = Number(this.settings.wireTraffic && this.settings.wireTraffic.sessionKeyViolationPenalty) ||
      PEER_SCORE_SESSION_KEY_VIOLATION_PENALTY;
    // Onion peel: do not cut/ban the honest TCP last hop for a laundered bad session frame.
    this._applyPeerMisbehavior(peeledForward ? null : originName, `session-key:${reason}`, {
      penalty,
      disconnect: !peeledForward
    });
  }

  /**
   * Upsert a peer into the persistent registry (state.peers) and schedule save to LevelDB.
   * @param {string} address - Peer address (e.g. host:port).
   * @param {Object} [updates] - Fields to set/merge (id, score, firstSeen, lastSeen, alias, publicKey).
   */
  _upsertPeerRegistry (key, updates = {}) {
    const registry = this._state.peers || {};
    const now = new Date().toISOString();
    const canonicalKey = updates.id || key;
    const existing = registry[canonicalKey] || registry[key];
    const base = existing ? { ...existing } : { id: canonicalKey, address: key.includes(':') ? key : undefined, score: 0, firstSeen: now, lastSeen: now };
    const merged = merge(base, updates);
    if (!merged.lastSeen) merged.lastSeen = now;
    registry[canonicalKey] = merged;
    if (key !== canonicalKey && registry[key]) delete registry[key];
    this._state.peers = registry;
    this._savePeerRegistry();
  }

  /**
   * Attempt to fill available connection slots with new peers.
   * @returns {Peer} Instance of the peer.
   */
  _fillPeerSlots () {
    if (this.connections.length >= this.settings.constraints.peers.max) return;
    const openCount = this.settings.constraints.peers.max - Object.keys(this.connections).length;
    if (!this._candidateRetryAt) this._candidateRetryAt = new Map();
    const configuredRetry = Number(this.settings.peering && this.settings.peering.candidateRetryMs);
    const retryAfter = (Number.isFinite(configuredRetry) && configuredRetry > 0)
      ? configuredRetry
      : PEER_CANDIDATE_RETRY_MS;
    const now = Date.now();
    for (const [addr, until] of this._candidateRetryAt) {
      if (until <= now) this._candidateRetryAt.delete(addr);
    }
    const maxRetry = (this.settings.peering && this.settings.peering.maxCandidates) || PEER_MAX_CANDIDATES_QUEUE;
    while (this._candidateRetryAt.size > maxRetry) {
      const oldest = this._candidateRetryAt.keys().next().value;
      this._candidateRetryAt.delete(oldest);
    }
    const deferred = [];
    for (let i = 0; i < openCount; i++) {
      if (!this.candidates.length) break;
      const candidate = this.candidates.shift();
      this.emit('debug', `Filling peer slot ${i} of ${openCount} (max ${this.settings.constraints.peers.max}) with candidate: ${JSON.stringify(candidate, null, '  ')}`);

      try {
        const host = candidate.object ? candidate.object.host : candidate.host;
        const port = candidate.object ? candidate.object.port : candidate.port;
        const pubkey = candidate.pubkey ||
          (candidate.object && (candidate.object.pubkey || candidate.object.publicKey));
        const addr = canonicalPeerAddress(host, port);
        if (pubkey && this._isOwnFabricPubkey(pubkey)) {
          this.emit('warning',
            `[FABRIC:PEER] Dropping candidate ${addr}: pubkey is our own`);
          // Advertised pubkeys are attacker-controlled; only verified AMP
          // signers may suppress the address (see _enqueuePeeringCandidate).
          if (candidate.verifiedPubkey && this._isOwnFabricPubkey(candidate.verifiedPubkey)) {
            this._suppressSelfDialAddress(addr);
          }
          if (this._candidateKeys) this._candidateKeys.delete(addr);
          if (this._candidateRetryAt) this._candidateRetryAt.delete(addr);
          continue;
        }
        const nextOk = this._candidateRetryAt.get(addr) || 0;
        if (now < nextOk ||
            this.connections[addr] ||
            (this._outboundDialTargets && this._outboundDialTargets.has(addr))) {
          deferred.push(candidate);
          continue;
        }
        this._candidateRetryAt.set(addr, now + retryAfter);
        this._connect(addr);
      } catch (exception) {
        this.emit('error', `Unable to fill open peer slot ${i}: ${exception}`);
      }

      deferred.push(candidate);
    }
    for (const c of deferred) this.candidates.push(c);

    return this;
  }

  /**
   * Handle a Fabric {@link Message} buffer.
   * @param {Buffer} buffer
   * @param {object|null} [origin]
   * @param {object|null} [socket]
   * @param {Object} [options]
   * @param {number} [options.relayDepth]
   * @param {boolean} [options.skipRelayFlood]
   * @param {boolean} [options.peeledForward] true when delivered via {@link Peer#_handleP2PForward} peel
   * @returns {Peer} Instance of the Peer.
   */
  _handleFabricMessage (buffer, origin = null, socket = null, options = null) {
    const opts = (options && typeof options === 'object') ? options : {};
    const originName = (origin && origin.name) ? origin.name : null;
    const ps = this.settings.peerScore || {};
    // Single delivery context for peel / RELAY-unwrap / outermost-flood rules.
    const delivery = meshDeliveryContext(opts, originName);
    const suppressTcpOriginPunish = delivery.suppressTcpOriginPunish;
    const peeledForward = suppressTcpOriginPunish; // soft-punish alias for nested handlers
    const scoreOrigin = delivery.scoreOrigin;

    // Frame-size gate before parse / hash / signature work. Undersize frames are
    // not body-hash mismatches — treating them as such would hard-ban a TCP peer
    // for a partial NOISE chunk. Unparseable frames are dropped the same way.
    let wire = buffer;
    if (!Buffer.isBuffer(wire)) {
      if (wire instanceof Uint8Array) wire = Buffer.from(wire);
      else return this;
    }
    const maxWire = this._localMaxFrameBytes();
    if (wire.length > maxWire) {
      this.emit('warning',
        `[FABRIC:PEER] Dropping oversized frame (${wire.length} > ${maxWire}) from ${originName || 'unknown'}`);
      // Senders clamp to our advertised cap, and unannounced peers to the legacy 4096 bytes,
      // so anything over both is a protocol violation (C fabricd: "oversize body").
      if (wire.length > Math.max(maxWire, LEGACY_MAX_FRAME_BYTES) && delivery.allowTcpOriginSideEffects) {
        this._applyPeerMisbehavior(scoreOrigin, 'oversize-frame', {
          penalty: Number(ps.oversizeFramePenalty) || PEER_SCORE_OVERSIZE_FRAME_PENALTY,
          disconnect: delivery.hardDisconnect
        });
      }
      return this;
    }
    if (wire.length < HEADER_SIZE) {
      this.emit('warning',
        `[FABRIC:PEER] Dropping undersize frame (${wire.length} < ${HEADER_SIZE}) from ${originName || 'unknown'}`);
      return this;
    }

    if (originName && this._isPeerBanned(originName)) {
      this.emit('warning', `[FABRIC:PEER] Dropping message from banned peer ${originName}`);
      const conn = this.connections && this.connections[originName];
      if (conn && typeof conn.destroy === 'function') conn.destroy();
      return this;
    }

    const hash = crypto.createHash('sha256').update(wire).digest('hex');
    let message;
    try {
      message = Message.fromBuffer(wire);
    } catch (err) {
      this.emit('warning',
        `[FABRIC:PEER] Dropping unparseable frame from ${originName || 'unknown'}: ` +
        `${err && err.message ? err.message : err}`);
      return this;
    }
    if (!message) return this;
    if (this.settings.debug) this.emit('debug', `Got Fabric message: ${message}`);

    // Have we seen this exact wire envelope before? (silent — no score change)
    if (this.messages[hash]) {
      return this;
    }

    // Body integrity: `hash` header is double-SHA256(body). Wire `preimage` is a
    // Lightning-style payment secret (all-zero for public frames; non-zero for HTLC /
    // Fabric Circuit hops). Do not require preimage === SHA256(body) — that field is
    // not a body commitment (see docs/MESSAGE_BODY.md).
    // Remember wire hash only after verify so junk frames cannot fill the dedup cache.
    const bodyBuf = message.raw.data || Buffer.alloc(0);
    const checksum = Hash256.doubleDigest(bodyBuf);
    const expectedHash = Buffer.isBuffer(message.raw.hash) ? message.raw.hash.toString('hex') : message.raw.hash;
    if (checksum !== expectedHash) {
      const t = message.type || '?';
      const hint = this.settings.debug
        ? ` wire=${String(expectedHash).slice(0, 16)}… computed=${String(checksum).slice(0, 16)}…`
        : '';
      this.emit('warning',
        `[FABRIC:PEER] Dropping message (body hash mismatch): from=${originName || 'unknown'}` +
        `${peeledForward ? ' (peeled forward)' : ''} type=${t}${hint}`);
      this._applyPeerMisbehavior(scoreOrigin, 'body-hash-mismatch', {
        penalty: Number(ps.bodyHashMismatchPenalty) || PEER_SCORE_BODY_HASH_MISMATCH_PENALTY,
        disconnect: delivery.hardDisconnect
      });
      return this;
    }

    // Verify every inbound message against the signed on-wire author field.
    const signerPubkeyHex = this._verifiedFabricSignerPubkeyHex(message);
    if (!signerPubkeyHex) {
      this.emit('warning',
        `[FABRIC:PEER] Invalid message signature from ${originName || 'unknown'}` +
        `${peeledForward ? ' (peeled forward)' : ''}`);
      this._applyPeerMisbehavior(scoreOrigin, 'invalid-signature', {
        penalty: Number(ps.invalidSignaturePenalty) || PEER_SCORE_INVALID_SIGNATURE_PENALTY,
        disconnect: delivery.hardDisconnect
      });
      return this;
    }

    this._rememberWireHash(hash);

    // Connection peer pin ≠ message author for mesh relays (author may be a prior hop
    // or a multisig group). Authenticity is the AMP signature; Noise authenticates the TCP peer.
    // Session / control messages still require signer continuity with the pinned peer key.
    // Peeled onion inners are authored by the path originator, not the last hop — skip pin.
    const peerKey = origin && (origin.name != null ? origin.name : origin);
    const peerRecord = peerKey && this.peers[peerKey];
    const relayAsIs = peeledForward
      || isRelayAsIsWireType(message.type)
      || isRelayAsIsWireType(message.friendlyType)
      || isRelayAsIsGenericCarrier(message);
    if (!relayAsIs && peerRecord && peerRecord.publicKey) {
      const pinned = normalizePeerPubkeyHex(peerRecord.publicKey);
      if (pinned && pinned !== signerPubkeyHex) {
        this.emit('warning', `[FABRIC:PEER] Signer mismatch from ${peerKey}: expected pinned peer key`);
        this._applyPeerMisbehavior(scoreOrigin || peerKey, 'signer-pin-mismatch', {
          penalty: Number(ps.signerPinMismatchPenalty) || PEER_SCORE_SIGNER_PIN_MISMATCH_PENALTY,
          disconnect: delivery.hardDisconnect
        });
        return this;
      }
    }

    // Outer P2P_FORWARD / foreign P2P_RELAY already paid inbound credits for the
    // TCP hop — do not debit again for peeled / relayed-as-is inners (onion DoS).
    if (originName && delivery.allowTcpOriginSideEffects) {
      const cost = this._wireInboundCreditCost(message.type);
      if (!this._wireInboundRateAllowPeer(originName, cost)) {
        if (this.settings.debug) {
          this.emit('debug', `[FABRIC:PEER] Dropped (wire traffic budget): ${originName} type=${message.type}`);
        }
        return this;
      }
    }

    if (this.settings.debug) this.emit('debug', `Message author: ${message.raw.signature.toString('hex')}`);
    if (this.settings.debug) this.emit('debug', `Message signature: ${message.raw.signature.toString('hex')}`);

    switch (message.type) {
      default:
        this.emit('debug', `Unhandled message type: ${message.type}`);
        break;
      case 'P2P_MUSIG_START':
      case 'P2P_MUSIG_ACCEPT':
      case 'P2P_MUSIG_RECEIVE_COUNTER':
      case 'P2P_MUSIG_SEND_PROPOSAL':
      case 'P2P_MUSIG_REPLY_TO_PROPOSAL':
      case 'P2P_MUSIG_ACCEPT_PROPOSAL':
        this._handleMusig2Message(message, origin, socket, Object.assign({}, opts, {
          signerPubkeyHex
        }));
        break;
      case 'P2P_RELAY':
        if (!origin || origin.name == null) break;
        {
          // Mesh flood envelope: body = raw inner Message bytes (not directed onion).
          // Never re-wrap on forward — bit-identical relayFrom of *this* outer frame so
          // wire-hash dedup bounds diameter. Nested RELAY unwrap is depth-capped.
          // For IP-hiding source routes use P2P_FORWARD / Peer#sendOnion.
          const relayDepth = Number(opts.relayDepth) || 0;
          const maxNest = Number(ps.maxRelayNestDepth);
          const nestCap = Number.isFinite(maxNest) && maxNest >= 0 ? maxNest : PEER_MAX_RELAY_NEST_DEPTH;
          const inner = (message.raw && Buffer.isBuffer(message.raw.data))
            ? message.raw.data
            : Buffer.alloc(0);
          // Outer AMP author ≠ TCP peer pin ⇒ this hop is only forwarding; do not
          // attribute inner pin/integrity/nest failures to them (mesh partition DoS).
          const peerRec = this.peers[origin.name];
          const pinnedOuter = peerRec && peerRec.publicKey
            ? normalizePeerPubkeyHex(peerRec.publicKey)
            : null;
          const relayedAsIs = !!(pinnedOuter && signerPubkeyHex && pinnedOuter !== signerPubkeyHex);
          const softRelayOrigin = suppressTcpOriginPunish || relayedAsIs;
          if (inner.length > 0) {
            if (relayDepth >= nestCap) {
              this._applyPeerMisbehavior(softRelayOrigin ? null : originName, 'relay-nest-exceeded', {
                penalty: Number(ps.relayNestExceededPenalty) || PEER_SCORE_RELAY_NEST_EXCEEDED_PENALTY,
                disconnect: !softRelayOrigin
              });
              break;
            }
            this._handleFabricMessage(inner, origin, socket, {
              relayDepth: relayDepth + 1,
              skipRelayFlood: true,
              peeledForward: suppressTcpOriginPunish,
              relayedAsIs: softRelayOrigin
            });
            // Only the outermost received envelope is mesh-flooded (bit-identical).
            if (!opts.skipRelayFlood) {
              this.relayFrom(origin.name, message, socket);
            }
          }
        }
        break;
      case 'P2P_FORWARD':
        this._handleP2PForward(message, origin, socket);
        break;
      case 'BITCOIN_BLOCK':
      case 'BitcoinBlock': {
        // Chain-tip gossip: relay so sparse meshes learn Bitcoin network tip.
        // Logical tip claim stops re-signed copies of the same tip from re-emitting / re-relaying.
        const rawBb = messageDataToString(message.data);
        const prBb = tryParseWireJsonBody(rawBb);
        if (prBb.ok && prBb.value && typeof prBb.value === 'object' && !Array.isArray(prBb.value)) {
          const claimBb = this._claimLogicalRegistrationOrPunish(
            message.type, prBb.value, signerPubkeyHex, scoreOrigin);
          if (claimBb.duplicate) {
            if (this.settings.debug) {
              this.emit('debug', '[FABRIC:PEER] Ignoring duplicate BitcoinBlock (tip already registered)');
            }
            break;
          }
        }
        this.emit('bitcoinBlock', { message, origin, socket });
        // Peel / RELAY unwrap: outer envelope already floods — never mesh-relay the inner tip.
        if (origin && origin.name && delivery.allowMeshRelay) {
          this.relayFrom(origin.name, message);
        }
        break;
      }
      case 'P2P_CHAIN_SYNC_REQUEST':
      case 'ChainSyncRequest':
        if (!origin || !origin.name) break;
        {
          const raw = messageDataToString(message.data);
          const pr = tryParseWireJsonBody(raw);
          if (!pr.ok || pr.value === null || typeof pr.value !== 'object' || Array.isArray(pr.value)) {
            this.emit('warning', `[FABRIC:PEER] CHAIN_SYNC_REQUEST parse failed: ${pr.ok ? 'invalid body' : pr.error.message}`);
            break;
          }
          this.emit('chainSyncRequest', { message, origin, socket, object: pr.value });
        }
        break;
      case 'P2P_FLUSH_CHAIN':
      case 'FlushChain': {
        if (!origin || !origin.name) break;
        const senderHex = signerPubkeyHex || this._flushChainSenderPubkeyHex(origin.name);
        if (!senderHex) {
          this.emit('warning', `[FABRIC:PEER] FLUSH_CHAIN ignored: no verified peer key for ${origin.name}`);
          break;
        }
        const authList = this.settings.flushChainAuthorizedPubkeys;
        if (!Array.isArray(authList) || authList.length === 0) {
          this.emit('warning', `[FABRIC:PEER] FLUSH_CHAIN ignored: flushChainAuthorizedPubkeys is empty (configure allowed signer pubkeys)`);
          break;
        }
        const allowed = new Set();
        for (const e of authList) {
          const h = normalizePeerPubkeyHex(e);
          if (h) allowed.add(h);
        }
        if (!allowed.has(senderHex)) {
          this.emit('warning', `[FABRIC:PEER] FLUSH_CHAIN ignored: sender pubkey not in flushChainAuthorizedPubkeys`);
          break;
        }
        const threshold = Number(this.settings.flushChainMinTrustedScore) || 800;
        const score = this._registryScoreForFlushChainSender(origin.name, senderHex);
        if (!(score > threshold)) {
          if (this.settings.debug) {
            this.emit('debug', `[FABRIC:PEER] FLUSH_CHAIN ignored: sender score ${score} not > ${threshold}`);
          }
          break;
        }
        const rawFc = messageDataToString(message.data);
        const prFc = tryParseWireJsonBody(rawFc);
        if (!prFc.ok) {
          this.emit('warning', `[FABRIC:PEER] FLUSH_CHAIN JSON parse failed: ${prFc.error.message}`);
          break;
        }
        const object = prFc.value;
        if (object === null || typeof object !== 'object' || Array.isArray(object)) {
          this.emit('warning', '[FABRIC:PEER] FLUSH_CHAIN body must be a JSON object');
          break;
        }
        const snap = object.snapshotBlockHash != null ? String(object.snapshotBlockHash).trim() : '';
        if (!/^[0-9a-fA-F]{64}$/.test(snap)) {
          this.emit('warning', '[FABRIC:PEER] FLUSH_CHAIN missing or invalid snapshotBlockHash (expect 64 hex)');
          break;
        }
        object.snapshotBlockHash = snap.toLowerCase();
        const claimFc = this._claimLogicalRegistrationOrPunish(
          message.type, object, senderHex, scoreOrigin);
        if (claimFc.duplicate) {
          if (this.settings.debug) {
            this.emit('debug', '[FABRIC:PEER] Ignoring duplicate FLUSH_CHAIN (snapshot already registered)');
          }
          break;
        }
        this.emit('flushChain', { message, origin, socket, object });
        this.relayFromTrustedPeers(origin.name, message, threshold);
        break;
      }
      case 'P2P_CHAT_MESSAGE': {
        // Body = raw UTF-8 chat text only (no JSON chat envelope). Author is AMP header /
        // signature. Optional FabricOnionChatSeal JSON keeps onion tips confidential to
        // the path recipient (see functions/onionChatSeal).
        const text = messageDataToString(message.data);
        if (!text || !String(text).trim()) {
          this.emit('warning', '[FABRIC:PEER] P2P_CHAT_MESSAGE empty body');
          break;
        }
        if (String(text).length > P2P_CHAT_MAX_CHARS) {
          this.emit('warning', `[FABRIC:PEER] P2P_CHAT_MESSAGE exceeds ${P2P_CHAT_MAX_CHARS} chars`);
          break;
        }
        // Reject legacy chat JSON envelopes ({ type, actor, object }); opaque UTF-8
        // text is allowed (including app JSON that is not a chat envelope).
        const trimmed = String(text).trim();
        if (trimmed.startsWith('{')) {
          try {
            const parsed = JSON.parse(trimmed);
            if (parsed && typeof parsed === 'object' && !Array.isArray(parsed) &&
                (parsed.type === 'P2P_CHAT_MESSAGE' || (parsed.actor && parsed.object))) {
              this.emit('warning', '[FABRIC:PEER] P2P_CHAT_MESSAGE body must be UTF-8 text, not a JSON chat envelope');
              break;
            }
          } catch (_) { /* not JSON — treat as text */ }
        }
        let deliverText = String(text);
        let onionSealed = false;
        try {
          if (isOnionChatSeal(deliverText)) {
            onionSealed = true;
            const opened = tryOpenOnionChatText(deliverText, { keyOrPrivate: this.key });
            if (!opened.opened || opened.text == null) {
              this.emit('warning', '[FABRIC:PEER] P2P_CHAT_MESSAGE onion seal present but not openable locally');
              break;
            }
            deliverText = opened.text;
          }
        } catch (err) {
          this.emit('warning',
            `[FABRIC:PEER] onion chat seal handling failed: ${err && err.message ? err.message : err}`);
          break;
        }
        this.emit('chat', {
          text: deliverText,
          type: 'P2P_CHAT_MESSAGE',
          ...(onionSealed ? { onionSealed: true } : {})
        }, {
          origin,
          signer: signerPubkeyHex || null,
          wireMessage: message,
          peeledForward: opts.peeledForward === true,
          onionSealed
        });
        // Onion peel / RELAY unwrap: deliver locally only. Mesh relay under the TCP
        // last hop would burn that neighbor's chat budget for an originator's frame.
        if (origin && origin.name && message && delivery.allowMeshRelay) {
          if (this._chatRateLimitAllow(origin.name)) {
            this.relayFrom(origin.name, message);
          } else {
            this.emit('warning',
              `[FABRIC:PEER] Chat relay rate-limited for ${origin.name}`);
          }
        }
        break;
      }
      case 'P2P_PEER_ALIAS': {
        // Body = raw UTF-8 nickname only (no JSON).
        const alias = messageDataToString(message.data);
        if (!alias || !String(alias).trim()) {
          this.emit('warning', '[FABRIC:PEER] P2P_PEER_ALIAS empty body');
          break;
        }
        const name = String(alias).trim().slice(0, P2P_PEER_ALIAS_MAX_CHARS);
        if (String(alias).trim().startsWith('{') || String(alias).trim().startsWith('[')) {
          this.emit('warning', '[FABRIC:PEER] P2P_PEER_ALIAS body must be UTF-8 text, not JSON');
          break;
        }
        // Peel / relay-as-is: observe only — never overlay alias onto the TCP last hop
        // or bind the attacker's registry address to that hop's socket.
        const aliasLocalOnly = !delivery.allowTcpOriginSideEffects;
        const aliasSignerHex = signerPubkeyHex || this._verifiedFabricSignerPubkeyHex(message);
        const claimAlias = this._claimLogicalRegistrationOrPunish('P2P_PEER_ALIAS', {
          alias: name,
          signer: aliasSignerHex || ''
        }, aliasSignerHex, aliasLocalOnly ? null : originName);
        if (claimAlias.duplicate) {
          if (this.settings.debug) {
            this.emit('debug', '[FABRIC:PEER] Ignoring duplicate P2P_PEER_ALIAS (same signer + nickname)');
          }
          break;
        }
        if (!aliasLocalOnly && origin && origin.name && this.connections[origin.name]) {
          this.connections[origin.name]._alias = name;
        }
        const aliasPeerId = aliasSignerHex
          || (!aliasLocalOnly && origin && this._addressToId && this._addressToId[origin.name])
          || (!aliasLocalOnly && origin && origin.name)
          || null;
        if (aliasPeerId) {
          this._upsertPeerRegistry(aliasPeerId, {
            id: aliasPeerId,
            address: (!aliasLocalOnly && origin && origin.name) ? origin.name : undefined,
            alias: name,
            publicKey: aliasSignerHex || undefined
          });
        }
        this.emit('peerAlias', {
          alias: name,
          signer: aliasSignerHex || null,
          origin,
          wireMessage: message,
          peeledForward: aliasLocalOnly
        });
        if (delivery.allowMeshRelay && origin && origin.name && message) {
          this.relayFrom(origin.name, message);
        }
        break;
      }
      case 'P2P_INVENTORY_REQUEST':
      case 'P2P_INVENTORY_RESPONSE':
      case 'P2P_PEER_GOSSIP':
      case 'P2P_PEERING_OFFER':
      case 'P2P_PING':
      case 'P2P_PONG':
      case 'P2P_STATE_ANNOUNCE':
      case 'P2P_PEER_ANNOUNCE':
      case 'P2P_SESSION_OFFER':
      case 'P2P_SESSION_OPEN':
      case 'P2P_DOCUMENT_PUBLISH':
      case 'P2P_FILE_SEND':
      case 'CONTRACT_PUBLISH':
      case 'CONTRACT_MESSAGE':
      case 'SIDECHAIN_STATE_PATCH':
      {
        const prTyped = Message.tryParseMessageBody(message);
        if (!prTyped.ok || prTyped.value === null || typeof prTyped.value !== 'object' || Array.isArray(prTyped.value)) {
          this.emit('warning', `[FABRIC:PEER] ${message.type} parse failed: ${prTyped.ok ? 'invalid body' : prTyped.error.message}`);
          break;
        }
        const wireToInner = {
          P2P_INVENTORY_REQUEST: 'INVENTORY_REQUEST',
          P2P_INVENTORY_RESPONSE: 'INVENTORY_RESPONSE'
        };
        const innerType = wireToInner[message.type] || message.type;
        let parsed = prTyped.value;
        if (prTyped.encoding === 'fields' && Message.LEGACY_BODY_TYPES.includes(message.type)) {
          // Handlers and app events keep the legacy JSON shape for either encoding.
          parsed = Message.decodeLegacyBody(message.type, parsed);
          if (!parsed) {
            this.emit('warning', `[FABRIC:PEER] ${message.type} parse failed: unusable field body`);
            break;
          }
        }
        let genericBody;
        if (message.type === 'CONTRACT_PUBLISH' || message.type === 'CONTRACT_MESSAGE') {
          // Contract frames dispatch by WIRE type (namespace routing). The app
          // payload — including any inner `type` like MissionBroadcast — is kept
          // intact under `object` so handlers see the full body.
          genericBody = { type: message.type, object: parsed };
        } else {
          // AMP wire name wins. Numeric JSON `type: 98` is P2P_PEERING_OFFER only
          // on a peering-offer (or generic) carrier — never on inventory/gossip.
          // Bare `type` is not an envelope (that dropped host/port onto the outer
          // object and JSON.stringified the full body on every offer).
          genericBody = (parsed && typeof parsed === 'object' && (parsed.actor || parsed.object))
            ? Object.assign({}, parsed, { type: innerType })
            : { type: innerType, object: parsed };
        }
        this._handleGenericMessage(genericBody, origin, socket, message, opts);
        break;
      }
      case 'DOCUMENT_PUBLISH':
      case 'DocumentPublish':
        try {
          const rawDp = messageDataToString(message.data);
          const prDp = tryParseWireJsonBody(rawDp);
          if (!prDp.ok) {
            this.emit('warning', `[FABRIC:PEER] DOCUMENT_PUBLISH parse failed: ${prDp.error.message}`);
            break;
          }
          const parsed = prDp.value;
          if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
            this.emit('warning', '[FABRIC:PEER] DOCUMENT_PUBLISH body must be a JSON object');
            break;
          }
          const docId = parsed.id;
          if (!docId) break;
          const claimDp = this._claimLogicalRegistrationOrPunish(
            message.type, parsed, signerPubkeyHex, scoreOrigin);
          if (claimDp.duplicate) {
            if (this.settings.debug) {
              this.emit('debug',
                `[FABRIC:PEER] Ignoring duplicate DOCUMENT_PUBLISH for ${docId} (logical key claimed)`);
            }
            break;
          }
          const purchaseHash = purchaseContentHashHex(docId, parsed);
          const payload = {
            message,
            origin,
            socket,
            documentId: docId,
            purchaseContentHashHex: purchaseHash,
            parsed,
            source: 'canonical'
          };
          this.emit('documentPublish', payload);
          this.emit('DocumentPublish', payload);
        } catch (exception) {
          this.emit('warning', `[FABRIC:PEER] DOCUMENT_PUBLISH parse failed: ${exception.message}`);
        }
        break;
      case 'DOCUMENT_REQUEST':
      case 'DocumentRequest':
        try {
          this._handleDocumentRequestWire(message, origin, socket, opts);
        } catch (exception) {
          this.emit('warning', `[FABRIC:PEER] DOCUMENT_REQUEST failed: ${exception.message}`);
        }
        break;
      case 'P2P_DOCUMENT_BID':
        try {
          this._handleDocumentBidWire(message, origin, socket, opts);
        } catch (exception) {
          this.emit('warning', `[FABRIC:PEER] P2P_DOCUMENT_BID failed: ${exception.message}`);
        }
        break;
      case 'P2P_DOCUMENT_ASK':
        try {
          this._handleDocumentAskWire(message, origin, opts);
        } catch (exception) {
          this.emit('warning', `[FABRIC:PEER] P2P_DOCUMENT_ASK failed: ${exception.message}`);
        }
        break;
      case 'CONTRACT_PROPOSAL':
      case 'ContractProposal': {
        const rawCp = messageDataToString(message.data);
        const prCp = tryParseWireJsonBody(rawCp);
        if (!prCp.ok || prCp.value === null || typeof prCp.value !== 'object' || Array.isArray(prCp.value)) {
          this.emit('warning', `[FABRIC:PEER] CONTRACT_PROPOSAL parse failed: ${prCp.ok ? 'invalid body' : prCp.error.message}`);
          break;
        }
        const payload = prCp.value;
        const verdict = verifyContractProposalPayload(payload);
        if (!verdict || verdict.ok !== true) {
          this.emit('warning', `[FABRIC:PEER] CONTRACT_PROPOSAL rejected: ${(verdict && verdict.error) || 'verification failed'}`);
          break;
        }
        const claimCp = this._claimLogicalRegistrationOrPunish(
          message.type, payload, signerPubkeyHex, scoreOrigin);
        if (claimCp.duplicate) {
          if (this.settings.debug) {
            this.emit('debug',
              '[FABRIC:PEER] Ignoring duplicate CONTRACT_PROPOSAL (merkle root already registered)');
          }
          break;
        }
        this.emit('contract:proposal', {
          contract: payload.contractId != null ? String(payload.contractId) : null,
          payload,
          message,
          origin,
          socket,
          signer: signerPubkeyHex || null
        });
        // Forward bit-identical on direct receive only — peel / RELAY unwrap must not
        // second-flood under the TCP last hop (outer envelope already paid).
        if (origin && origin.name && delivery.allowMeshRelay) {
          this.relayFrom(origin.name, message);
        }
        break;
      }
      case 'GENERIC_MESSAGE':
      case 'GenericMessage':
      case 'P2P_BASE_MESSAGE':
      case 'CHAT_MESSAGE':
      case 'ChatMessage':
        // GENERIC_MESSAGE (15103) is the transitional Hub/browser carrier; P2P_BASE_MESSAGE
        // remains the generic peer payload / legacy decode fallback. Both carry UTF-8 JSON
        // bodies dispatched via _handleGenericMessage (bounded — see functions/wireJson).
        {
          const rawGm = messageDataToString(message.data);
          const prGm = tryParseWireJsonBody(rawGm);
          if (!prGm.ok) {
            this.emit('warning', `[FABRIC:PEER] Generic message parse failed: ${prGm.error.message}`);
            break;
          }
          const bodyGm = prGm.value;
          if (bodyGm === null || typeof bodyGm !== 'object' || Array.isArray(bodyGm)) {
            this.emit('warning', '[FABRIC:PEER] Generic message body must be a JSON object');
            break;
          }
          this._handleGenericMessage(bodyGm, origin, socket, message, Object.assign({}, opts, {
            genericCarrier: true
          }));
        }

        break;
      // Lightning AMP types (0x2000+). Channel ops stay local; announcements may relay.
      case 'LIGHTNING_WARNING':
      case 'LightningWarning':
      case 'LIGHTNING_INIT':
      case 'LightningInit':
      case 'LIGHTNING_ERROR':
      case 'LightningError':
      case 'LIGHTNING_PING':
      case 'LightningPing':
      case 'LIGHTNING_PONG':
      case 'LightningPong':
      case 'LIGHTNING_OPEN_CHANNEL':
      case 'OpenChannel':
      case 'LIGHTNING_ACCEPT_CHANNEL':
      case 'AcceptChannel':
      case 'LIGHTNING_FUNDING_CREATED':
      case 'FundingCreated':
      case 'LIGHTNING_FUNDING_SIGNED':
      case 'FundingSigned':
      case 'LIGHTNING_CHANNEL_READY':
      case 'ChannelReady':
      case 'LIGHTNING_SHUTDOWN':
      case 'Shutdown':
      case 'LIGHTNING_CLOSING_SIGNED':
      case 'ClosingSigned':
      case 'LIGHTNING_UPDATE_ADD_HTLC':
      case 'UpdateAddHTLC':
      case 'LIGHTNING_UPDATE_FULFILL_HTLC':
      case 'UpdateFulfillHTLC':
      case 'LIGHTNING_UPDATE_FAIL_HTLC':
      case 'UpdateFailHTLC':
      case 'LIGHTNING_COMMITMENT_SIGNED':
      case 'CommitmentSigned':
      case 'LIGHTNING_REVOKE_AND_ACK':
      case 'RevokeAndAck':
      case 'LIGHTNING_CHANNEL_ANNOUNCEMENT':
      case 'ChannelAnnouncement':
      case 'LIGHTNING_NODE_ANNOUNCEMENT':
      case 'NodeAnnouncement':
      case 'LIGHTNING_CHANNEL_UPDATE':
      case 'ChannelUpdate':
        {
          const rawLn = messageDataToString(message.data);
          const prLn = tryParseWireJsonBody(rawLn);
          if (prLn.ok) {
            this.emit('lightning', { type: message.type, content: prLn.value, origin });
          } else {
            this.emit('lightning', { type: message.type, raw: message.data, origin });
          }
        }
        break;
    }

    return this;
  }

  /**
   * Originate a locally signed {@code P2P_RELAY} envelope around already-signed inner AMP bytes.
   * Used only when *this* agent starts a flood (e.g. inventory without a prior wire frame).
   * Inbound {@code P2P_RELAY} must never call this — forward the original outer bit-identical.
   */
  _relayWirePayload (originName, wirePayload, socket = null) {
    if (!originName) return false;
    const body = Buffer.isBuffer(wirePayload)
      ? wirePayload
      : Buffer.from(wirePayload || []);
    if (!body.length) return false;
    const relayMessage = Message.fromVector(['P2P_RELAY', body]);
    relayMessage.signWithKey(this.key);
    this.relayFrom(originName, relayMessage, socket);
    return true;
  }

  /**
   * Relay inventory / generic payloads. When {@code wireMessage} is present, forward it
   * bit-identical (no hop re-sign). Otherwise the local agent originates a new signed frame
   * and may wrap it in {@code P2P_RELAY} for mesh delivery.
   */
  _relayGenericPayload (originName, payload, socket = null, wireMessage = null) {
    if (!originName) return false;
    if (wireMessage && typeof wireMessage.toBuffer === 'function') {
      this.relayFrom(originName, wireMessage, socket);
      return true;
    }
    const innerType = (payload && payload.type === 'INVENTORY_REQUEST')
      ? 'P2P_INVENTORY_REQUEST'
      : (payload && payload.type === 'INVENTORY_RESPONSE')
          ? 'P2P_INVENTORY_RESPONSE'
          : 'P2P_BASE_MESSAGE';
    const innerBody = (innerType === 'P2P_BASE_MESSAGE')
      ? JSON.stringify(payload)
      : JSON.stringify((payload && payload.object) ? payload.object : {});
    const innerBuffer = Message
      .fromVector([innerType, innerBody])
      .signWithKey(this.key)
      .toBuffer();
    return this._relayWirePayload(originName, innerBuffer, socket);
  }

  _handleSessionOfferGenericMessage (message, origin, socket, signerPubkeyHex, opts = {}) {
    // Peel / relay-as-is: TCP origin is not the AMP author — never rebind
    // peers/_addressToId or reply SESSION_OPEN on that socket (partition DoS).
    if (opts.peeledForward === true || opts.relayedAsIs === true) {
      this.emit('warning',
        '[FABRIC:PEER] Ignoring P2P_SESSION_OFFER delivered via peel/relay-as-is (no identity rebind)');
      return this;
    }
    const peerId = message.actor.id;
    const connAddress = origin.name;
    if (this.settings.debug) this.emit('debug', `Handling session offer: ${JSON.stringify(message.object)}`);
    if (this.settings.debug) this.emit('debug', `Session offer origin: ${JSON.stringify(origin)}`);
    {
      const sessionClaim = this._validateSessionKeyExchangeClaim(
        message, signerPubkeyHex, connAddress, { peeledForward: opts.peeledForward === true });
      if (!sessionClaim) return this;
    }

    // Self-dial / hairpin: remote presented a session signed with our own Fabric key.
    // (Actor-id alone is not enough — an attacker can claim our id with another key.)
    if (this._isOwnFabricPubkey(signerPubkeyHex)) {
      return this._abortSelfFabricSession(connAddress, 'P2P_SESSION_OFFER from own Fabric identity');
    }

    // If we've already bound this Fabric id to a key, reject key-mismatched offers.
    const existingPeer = (this._state.peers && this._state.peers[peerId]) || null;
    if (existingPeer && existingPeer.publicKey) {
      const known = normalizePeerPubkeyHex(existingPeer.publicKey);
      if (known && known !== signerPubkeyHex) {
        this.emit('warning', `[FABRIC:PEER] Rejecting session offer for ${peerId}: signer key mismatch`);
        return this;
      }
    }

    // Same peer reconnecting from new port? Close old connection and replace with new.
    // Do not tear down our outbound dial to the peer's listen address: concurrent inbound +
    // outbound to the same Fabric id is normal (e.g. ring + star mesh); dropping the stable
    // `host:listenPort` socket breaks address-keyed sends on the satellite.
    const addressToId = this._addressToId || {};
    for (const [addr, mappedId] of Object.entries(addressToId)) {
      if (mappedId !== peerId || addr === connAddress) continue;
      if (this._outboundDialTargets && this._outboundDialTargets.has(addr)) continue;
      const oldSocket = this.connections[addr];
      if (oldSocket) {
        if (oldSocket._keepalive) clearInterval(oldSocket._keepalive);
        delete this.connections[addr];
        delete this.peers[addr];
        delete this._addressToId[addr];
        if (typeof oldSocket.destroy === 'function') oldSocket.destroy();
      }
      break;
    }

    this.peers[connAddress] = new Actor({
      id: peerId,
      name: connAddress,
      address: connAddress,
      connections: [ connAddress ],
      publicKey: signerPubkeyHex
    });

    this._upsertPeerRegistry(connAddress, {
      id: peerId,
      address: connAddress,
      publicKey: signerPubkeyHex,
      lastSeen: new Date().toISOString()
    });
    this._addressToId[connAddress] = peerId;
    this._recordRemoteFrameCap(connAddress, message.object);

    // Emit peer event
    this.emit('peer', this.peers[connAddress]);

    // Send session open event
    const keyClaim = this._buildSessionKeyExchangeClaim(this.identity.id);
    const vector = ['P2P_SESSION_OPEN', JSON.stringify({
      type: 'P2P_SESSION_OPEN',
      actor: {
        id: this.identity.id,
        pubkey: keyClaim.pubkey,
        parentPubkey: keyClaim.parentPubkey,
        parentXpub: keyClaim.parentXpub,
        parentSignature: keyClaim.parentSignature
      },
      object: {
        initiator: message.actor.id,
        counterparty: this.identity.id,
        solution: message.object.challenge,
        maxFrameBytes: this._localMaxFrameBytes()
      }
    })];

    const PACKET_SESSION_START = Message.fromVector(vector).signWithKey(this.key);
    const reply = PACKET_SESSION_START.toBuffer();
    if (this.settings.debug) this.emit('debug', `session_start ${PACKET_SESSION_START} ${reply.toString('hex')}`);
    this.connections[connAddress]._writeFabric(reply, socket);
    if (this.settings.announceDocumentsOnPeerConnect) {
      this._announceLocalDocumentsToPeer(connAddress);
    }
    return this;
  }

  _handleSessionOpenGenericMessage (message, origin, signerPubkeyHex, opts = {}) {
    if (opts.peeledForward === true || opts.relayedAsIs === true) {
      this.emit('warning',
        '[FABRIC:PEER] Ignoring P2P_SESSION_OPEN delivered via peel/relay-as-is (no identity rebind)');
      return this;
    }
    if (this.settings.debug) this.emit('debug', `Handling session open: ${JSON.stringify(message.object)}`);
    const openPeerId = message.object.counterparty;
    {
      const sessionClaim = this._validateSessionKeyExchangeClaim(
        message, signerPubkeyHex, origin && origin.name, { peeledForward: opts.peeledForward === true });
      if (!sessionClaim) return this;
    }
    // Hairpin: OPEN signed with our own key (SESSION_OFFER path should catch first).
    // Note: object.initiator === our id is normal when we dialed and they accepted.
    if (this._isOwnFabricPubkey(signerPubkeyHex)) {
      return this._abortSelfFabricSession(
        origin && origin.name,
        'P2P_SESSION_OPEN from own Fabric identity'
      );
    }
    const existingOpenPeer = (this._state.peers && this._state.peers[openPeerId]) || null;
    if (existingOpenPeer && existingOpenPeer.publicKey) {
      const knownOpen = normalizePeerPubkeyHex(existingOpenPeer.publicKey);
      if (knownOpen && knownOpen !== signerPubkeyHex) {
        this.emit('warning', `[FABRIC:PEER] Rejecting session open for ${openPeerId}: signer key mismatch`);
        return this;
      }
    }
    this.peers[origin.name] = { id: openPeerId, name: origin.name, address: origin, publicKey: signerPubkeyHex };
    this._upsertPeerRegistry(origin.name, {
      id: openPeerId,
      address: origin.name,
      publicKey: signerPubkeyHex,
      lastSeen: new Date().toISOString()
    });
    this._addressToId[origin.name] = openPeerId;
    this._recordRemoteFrameCap(origin.name, message.object);
    // Don't emit peer event here - it's already emitted in P2P_SESSION_OFFER
    return this;
  }

  _handleGenericMessage (message, origin = null, socket = null, wireMessage = null, options = null) {
    const handleOpts = (options && typeof options === 'object') ? options : {};
    const delivery = meshDeliveryContext(handleOpts, origin && origin.name);
    const peeledForward = delivery.suppressTcpOriginPunish;
    // Peel / relay-as-is: never attribute logical-register soft/hijack penalties to the TCP hop.
    const punishOrigin = delivery.scoreOrigin;
    const msg = normalizeFabricDocumentOfferEnvelopeForHandlers(message);
    const namedType = Message.canonicalTypeName(msg && msg.type);
    if (namedType) msg.type = namedType;
    if (this.settings.debug) this.emit('debug', `Generic message:\n\tFrom: ${JSON.stringify(origin)}\n\tType: ${msg.type}\n\tBody:\n\`\`\`\n${JSON.stringify(msg.object, null, '  ')}\n\`\`\``);

    // Strict Protocol V1: first-class mesh / session opcodes must not escalate from
    // P2P_BASE_MESSAGE / GenericMessage JSON carriers (attackers renaming body.type).
    if (handleOpts.genericCarrier === true && isFirstClassOpcodeOnlyType(msg && msg.type)) {
      this.emit('warning',
        `[FABRIC:PEER] Ignoring ${msg.type} via generic carrier; use first-class AMP opcode`);
      return this;
    }

    const signerPubkeyHex = wireMessage
      ? this._verifiedFabricSignerPubkeyHex(wireMessage)
      : normalizePeerPubkeyHex(msg && msg.actor && (msg.actor.publicKey || msg.actor.pubkey));

    // Lookup the appropriate Actor for the message's origin
    const actor = new Actor(origin);

    switch (msg.type) {
      default:
        this.emit('debug', `Unhandled Generic Message: ${msg.type}`);
        break;
      case 'SIDECHAIN_STATE_PATCH': {
        const body = msg.object || msg;
        const parsed = sidechainState.parseSidechainStatePatchMessage(body);
        if (!parsed.ok) {
          this.emit('warning', `[FABRIC:PEER] SIDECHAIN_STATE_PATCH rejected: ${parsed.error}`);
          break;
        }
        const proposal = parsed.proposal;
        const validators = this._distributedFederationValidatorsFromSettings();
        const threshold = this._distributedFederationThresholdFromSettings();
        // Fail closed on the network path (matches CONTRACT_MESSAGE patch allow-lists
        // and gossipNetwork `observe` policy). Unconfigured peers must not emit or
        // mesh-flood attacker-controlled RFC6902 patches from any session peer.
        if (!validators.length) {
          this.emit('warning',
            '[FABRIC:PEER] SIDECHAIN_STATE_PATCH rejected: no federation validators configured');
          break;
        }
        const witness = proposal.federationWitness || null;
        if (!sidechainState.verifySidechainPatchWitness(proposal, witness, validators, threshold)) {
          this.emit('warning', '[FABRIC:PEER] SIDECHAIN_STATE_PATCH federationWitness missing or invalid');
          break;
        }
        // Commitment-level replay: a new AMP envelope can re-carry the same patch.
        const claim = this._claimLogicalRegistrationOrPunish(
          'SIDECHAIN_STATE_PATCH',
          proposal,
          signerPubkeyHex || null,
          punishOrigin
        );
        if (claim.duplicate) break;
        this.emit('sidechain:patch', {
          proposal,
          federationWitness: proposal.federationWitness || null,
          signer: signerPubkeyHex || null,
          origin
        });
        // Observe-only: do not mesh-relay (gossipNetwork SIDECHAIN_STATE_PATCH = observe).
        break;
      }
      case 'FederationSignRequest': {
        const body = (msg.object && typeof msg.object === 'object') ? msg.object : msg;
        const validators = this._distributedFederationValidatorsFromSettings();
        if (!validators.length) {
          this.emit('warning',
            '[FABRIC:PEER] FederationSignRequest ignored: no federation validators configured');
          break;
        }
        const validatorSet = new Set(validators.map((v) => normalizePeerPubkeyHex(v)).filter(Boolean));
        if (!signerPubkeyHex || !Contract.hasAuthority(validatorSet, signerPubkeyHex)) {
          this.emit('warning',
            '[FABRIC:PEER] FederationSignRequest rejected: AMP signer is not a federation validator');
          break;
        }
        const epoch = body.epoch;
        const digest = body.commitmentDigest != null ? String(body.commitmentDigest).trim() : '';
        if (!epoch || typeof epoch !== 'object' || !digest) {
          this.emit('warning',
            '[FABRIC:PEER] FederationSignRequest rejected: epoch and commitmentDigest required');
          break;
        }
        if (epochCommitmentDigestHex(epoch) !== digest) {
          this.emit('warning',
            '[FABRIC:PEER] FederationSignRequest rejected: commitmentDigest mismatch');
          break;
        }
        this.emit('federation:sign-request', {
          request: body,
          signer: signerPubkeyHex || null,
          origin
        });
        // Observe-only: do not mesh-flood unauthenticated federation protocol traffic.
        break;
      }
      case 'FederationSignResponse': {
        const body = (msg.object && typeof msg.object === 'object') ? msg.object : msg;
        const validators = this._distributedFederationValidatorsFromSettings();
        if (!validators.length) {
          this.emit('warning',
            '[FABRIC:PEER] FederationSignResponse ignored: no federation validators configured');
          break;
        }
        const validatorSet = new Set(validators.map((v) => normalizePeerPubkeyHex(v)).filter(Boolean));
        if (!signerPubkeyHex || !Contract.hasAuthority(validatorSet, signerPubkeyHex)) {
          this.emit('warning',
            '[FABRIC:PEER] FederationSignResponse rejected: AMP signer is not a federation validator');
          break;
        }
        const responsePubkey = body.pubkey != null ? normalizePeerPubkeyHex(body.pubkey) : '';
        if (responsePubkey && normalizePeerPubkeyHex(signerPubkeyHex) !== responsePubkey &&
            !Contract.hasAuthority(new Set([responsePubkey]), signerPubkeyHex)) {
          this.emit('warning',
            '[FABRIC:PEER] FederationSignResponse rejected: AMP signer does not match response.pubkey');
          break;
        }
        this.emit('federation:sign-response', {
          response: body,
          signer: signerPubkeyHex || null,
          origin
        });
        // Observe-only: do not mesh-flood (same policy as FederationSignRequest).
        break;
      }
      case 'INVENTORY_REQUEST':
        // Upstream Inventory request (typically for documents). Emit an 'inventory'
        // event so higher-level services (e.g. hub) can respond appropriately.
        // JSON `type` may be legacy `INVENTORY_REQUEST` or Fabric alias `FABRIC_DOCUMENT_OFFER` (see `functions/publishedDocumentEnvelope.js`).
        this.emit('inventory', { message: msg, origin, socket });
        // Peel / foreign RELAY: observe only — do not reply inventory to the TCP last hop
        // or second-flood the request under that hop.
        if (!delivery.allowTcpOriginSideEffects) break;
        if (this.settings.serveLocalDocumentInventory) {
          const served = this._respondInventoryFromLocalDocuments(msg, origin);
          const req = msg.object || {};
          if (delivery.allowMeshRelay && this.settings.relayInventoryRequest &&
              !served && req.offerBtc === true) {
            // Relay path matches L1 `offerBtc` requests; Hub-driven `kind:documents` relays use TTL in app code.
            this._relayGenericPayload(origin && origin.name, msg, socket, wireMessage);
          }
        }
        break;
      case 'INVENTORY_RESPONSE':
        // Document inventory reply (may include per-item L1 HTLC offers).
        // JSON `type` may be legacy `INVENTORY_RESPONSE` or Fabric alias `FABRIC_DOCUMENT_OFFER_RESPONSE`.
        // Prefer AMP signer over untrusted item.sellerPubkey when funding HTLCs.
        // `latencyMs` is the locally measured round trip since our last
        // `requestPeerInventory` to this connection (offer-book telemetry).
        let inventoryLatencyMs = null;
        if (origin && origin.name && this._inventoryRequestedAt &&
            this._inventoryRequestedAt[origin.name] != null) {
          inventoryLatencyMs = Math.max(0, Date.now() - this._inventoryRequestedAt[origin.name]);
          delete this._inventoryRequestedAt[origin.name];
        }
        this.emit('inventoryResponse', {
          message: msg,
          origin,
          socket,
          signerPubkeyHex: signerPubkeyHex || null,
          latencyMs: inventoryLatencyMs,
          hops: Number(handleOpts.relayDepth) || 0
        });
        if (delivery.allowMeshRelay && this.settings.relayInventoryResponse) {
          this._relayGenericPayload(origin && origin.name, msg, socket, wireMessage);
        }
        break;
      case 'DocumentContentKeyReveal': {
        const reveal = (msg && msg.object) ? msg.object : msg;
        // Fail closed before claim / reverse-relay: public paymentHashHex alone must
        // not burn the logical slot or launder junk toward the buyer.
        if (!isWellFormedKeyReveal(reveal)) {
          this.emit('warning',
            '[FABRIC:PEER] DocumentContentKeyReveal rejected: key must be SHA256 preimage of paymentHashHex');
          break;
        }
        // Reverse-relay only well-formed reveals (private DocumentRequest return path).
        if (reveal && reveal.routeId && this._documentRelayRoutes[reveal.routeId]) {
          const route = this._documentRelayRoutes[reveal.routeId];
          const prev = route.prevHopAddress;
          if (prev && this.connections[prev] && this.connections[prev]._writeFabric &&
              !(origin && origin.name === prev)) {
            const fwdBody = {
              type: KEY_REVEAL_TYPE,
              object: Object.assign({}, reveal, { routeId: route.prevRouteId || reveal.routeId })
            };
            const fwdMsg = Message.fromVector(['GenericMessage', JSON.stringify(fwdBody)]);
            fwdMsg.signWithKey(this.key);
            this.connections[prev]._writeFabric(fwdMsg.toBuffer());
            this.emit('documentRelayReturn', {
              routeId: reveal.routeId,
              prevHopAddress: prev,
              documentId: reveal.documentId,
              kind: 'keyReveal',
              origin
            });
            break;
          }
        }
        // Claim only after a successful open so failed opens cannot occupy the slot.
        const logicKey = this._logicalRegistrationKey('DocumentContentKeyReveal', reveal);
        if (logicKey && this._logicalRegisterOnce.has(logicKey)) {
          if (this.settings.debug) {
            this.emit('debug', '[FABRIC:PEER] Ignoring duplicate DocumentContentKeyReveal');
          }
          break;
        }
        const opened = this._handleDocumentContentKeyReveal(reveal, origin);
        if (opened && opened.ok) {
          this._claimLogicalRegistrationOrPunish(
            'DocumentContentKeyReveal', reveal, signerPubkeyHex, punishOrigin);
        }
        break;
      }
      case BLOB_QUOTE_TYPE: {
        const quote = (msg && msg.object) ? msg.object : msg;
        if (!isWellFormedBlobQuote(quote)) {
          this.emit('warning', '[FABRIC:PEER] DocumentBlobQuote rejected: malformed');
          break;
        }
        if (quote.routeId && this._documentRelayRoutes[quote.routeId]) {
          const route = this._documentRelayRoutes[quote.routeId];
          const prev = route.prevHopAddress;
          if (prev && this.connections[prev] && this.connections[prev]._writeFabric &&
              !(origin && origin.name === prev)) {
            // Re-signed by this relay: the buyer's fraud evidence names the relay.
            const fwdMsg = Message.fromVector(['GenericMessage', JSON.stringify({
              type: BLOB_QUOTE_TYPE,
              object: Object.assign({}, quote, { routeId: route.prevRouteId || quote.routeId })
            })]);
            fwdMsg.signWithKey(this.key);
            this.connections[prev]._writeFabric(fwdMsg.toBuffer());
            break;
          }
        }
        this._ingestSealedBlobQuote(quote, origin, wireMessage);
        break;
      }
      case 'P2P_SESSION_OFFER':
        this._handleSessionOfferGenericMessage(msg, origin, socket, signerPubkeyHex, handleOpts);
        break;
      case 'P2P_SESSION_OPEN':
        this._handleSessionOpenGenericMessage(msg, origin, signerPubkeyHex, handleOpts);
        break;
      case 'P2P_CHAT_MESSAGE': {
        // Legacy GenericMessage / P2P_BASE_MESSAGE carrier with JSON body — not accepted.
        // First-class opcode path handles UTF-8 text in _handleFabricMessage.
        this.emit('warning', '[FABRIC:PEER] P2P_CHAT_MESSAGE via GenericMessage/JSON is unsupported; use first-class UTF-8 body');
        break;
      }
      case 'P2P_STATE_ANNOUNCE': {
        const stateObj = msg.object || message.object;
        const claimState = this._claimLogicalRegistrationOrPunish(
          'P2P_STATE_ANNOUNCE', stateObj, signerPubkeyHex, punishOrigin);
        if (claimState.duplicate) {
          if (this.settings.debug) {
            this.emit('debug', '[FABRIC:PEER] Ignoring duplicate P2P_STATE_ANNOUNCE');
          }
          break;
        }
        const state = new Actor(stateObj && stateObj.state);
        this.emit('debug', `state_announce <Generic>${JSON.stringify(stateObj || '')} ${state.toGenericMessage()}`);
        break;
      }
      case 'P2P_PEER_GOSSIP': {
        if (!origin || !origin.name) break;
        const g = this.settings.gossip || {};
        const maxHops = g.maxHops != null ? g.maxHops : GOSSIP_MAX_HOPS;
        const payloadKey = this._gossipPayloadDedupKey(message);
        if (this._gossipPayloadSeen.has(payloadKey)) break;
        const obj = genericOfferObject(message);
        let hop = obj.gossipHop != null ? Number(obj.gossipHop) : maxHops;
        if (!Number.isFinite(hop) || hop < 0) hop = maxHops;
        hop = Math.min(hop, maxHops);
        if (hop <= 0) break;
        // Outermost-only: peel / RELAY unwrap observes locally — no last-hop budget
        // burn and no second inner mesh flood (outer envelope already paid).
        if (!delivery.allowMeshRelay) {
          this.emit('peeringGossip', { message, origin, peeledForward: true });
          this._gossipRememberPayload(payloadKey);
          break;
        }
        if (!this._gossipRateLimitAllow(origin.name)) break;
        this.emit('peeringGossip', { message, origin });
        this._gossipRememberPayload(payloadKey);
        // Forward original frame only — wire-hash dedup stops loops; never hop-re-sign.
        if (wireMessage) this.relayFrom(origin.name, wireMessage);
        break;
      }
      case 'P2P_PEERING_OFFER': {
        if (!origin || !origin.name) break;
        const p = this.settings.peering || {};
        const maxHops = p.maxHops != null ? p.maxHops : PEERING_OFFER_MAX_HOPS;
        const payloadKey = this._peeringOfferPayloadDedupKey(message);
        if (this._peeringPayloadSeen.has(payloadKey)) break;
        const obj = genericOfferObject(message);
        let hop = obj.peeringHop != null ? Number(obj.peeringHop) : maxHops;
        if (!Number.isFinite(hop) || hop < 0) hop = maxHops;
        hop = Math.min(hop, maxHops);
        if (hop <= 0) break;
        // Outermost-only: peel / RELAY unwrap observes locally — no last-hop budget,
        // dial enqueue, or second inner mesh flood.
        if (!delivery.allowMeshRelay) {
          this.emit('peeringOffer', { message, origin, peeledForward: true });
          this._peeringRememberPayload(payloadKey);
          break;
        }
        if (!this._peeringRateLimitAllow(origin.name)) break;
        this.emit('peeringOffer', { message, origin });
        this._peeringRememberPayload(payloadKey);
        const transport = obj.transport || 'fabric';
        if (transport === 'fabric' && obj.host && obj.port) {
          const connCount = Object.keys(this.connections || {}).length;
          const maxPeers = (this.settings.constraints && this.settings.constraints.peers && this.settings.constraints.peers.max) || MAX_PEERS;
          if (connCount < maxPeers) {
            // Prefer explicit offer pubkey, else verified AMP signer, else actor id.
            // Actor id is not a pubkey — keep it after signerPubkeyHex so a Fabric
            // actor identifier cannot eclipse the verified AMP signer.
            const advertised = obj.pubkey
              || (message.actor && (message.actor.pubkey || message.actor.publicKey))
              || signerPubkeyHex
              || (message.actor && message.actor.id)
              || '';
            this._enqueuePeeringCandidate(obj.host, obj.port, {
              pubkey: advertised,
              verifiedPubkey: signerPubkeyHex
            });
          }
        }
        if (wireMessage) this.relayFrom(origin.name, wireMessage);
        break;
      }
      case 'P2P_PING': {
        // Peel / foreign RELAY: do not write PONG to the TCP last hop.
        if (!delivery.allowTcpOriginSideEffects) break;
        const pingNonce = msg.object && msg.object.nonce ? String(msg.object.nonce) : '';
        const P2P_PONG = Message.fromLegacyBody('P2P_PONG', {
          nonce: pingNonce || this._freshKeepaliveNonce()
        }).signWithKey(this.key);
        if (this.connections[origin.name] && this.connections[origin.name]._writeFabric) {
          this.connections[origin.name]._writeFabric(P2P_PONG.toBuffer());
        }
        break;
      }
      case 'P2P_PONG': {
        // Peel / foreign RELAY: ignore score credit under the last hop.
        if (!delivery.allowTcpOriginSideEffects) break;
        const conn = origin && origin.name ? this.connections[origin.name] : null;
        const outstanding = conn && (conn._fabricPingOutstanding | 0);
        if (!outstanding) {
          if (this.settings.debug) {
            this.emit('debug', `[FABRIC:PEER] Ignoring P2P_PONG from ${origin && origin.name}: no outbound ping pending`);
          }
          break;
        }
        conn._fabricPingOutstanding = 0;

        const instance = this.state.actors[actor.id] ? this.state.actors[actor.id] : {};
        const newScore = (instance.score || 0) + 1;

        this.actors[actor.id].adopt([
          { op: 'replace', path: '/score', value: newScore }
        ]);

        this._state.content.actors[actor.id] = this.actors[actor.id].state;
        this.commit();

        const registry = this._state.peers || {};
        const pongPeerId = (this._addressToId && this._addressToId[origin.name]) || origin.name;
        const regEntry = registry[pongPeerId] || registry[origin.name];
        this._upsertPeerRegistry(pongPeerId, { id: pongPeerId, address: origin.name, score: (regEntry && regEntry.score != null ? regEntry.score : 0) + 1, lastSeen: new Date().toISOString() });

        if (this.settings.debug) this.emit('debug', `Received pong: ${JSON.stringify(message, null, '  ')}`);
        this.emit('state', this.state);

        break;
      }
      case 'P2P_PEER_ALIAS':
        // Legacy GenericMessage/JSON carrier — not accepted. First-class UTF-8 path above.
        this.emit('warning', '[FABRIC:PEER] P2P_PEER_ALIAS via GenericMessage/JSON is unsupported; use first-class UTF-8 body');
        break;
      case 'P2P_PEER_ANNOUNCE': {
        const announceObj = msg.object || message.object;
        const claimAnn = this._claimLogicalRegistrationOrPunish(
          'P2P_PEER_ANNOUNCE', announceObj, signerPubkeyHex, punishOrigin);
        if (claimAnn.duplicate) {
          if (this.settings.debug) {
            this.emit('debug', '[FABRIC:PEER] Ignoring duplicate P2P_PEER_ANNOUNCE');
          }
          break;
        }
        this.emit('debug', `peer_announce <Generic>${JSON.stringify(announceObj || '')}`);
        this.emit('peerAnnounce', {
          message: msg,
          origin,
          peeledForward: !punishOrigin
        });
        // Peel / relay-as-is: observe only — do not enqueue dial targets under last hop.
        if (!punishOrigin) break;
        const host = announceObj && announceObj.host;
        const port = announceObj && announceObj.port;
        if (host != null && port != null) {
          this._enqueuePeeringCandidate(host, port, {
            pubkey: announceObj.pubkey || signerPubkeyHex,
            verifiedPubkey: signerPubkeyHex
          });
        }
        break;
      }
      case 'P2P_DOCUMENT_PUBLISH': {
        const priceObj = msg.object || message.object;
        const claimPrice = this._claimLogicalRegistrationOrPunish(
          'P2P_DOCUMENT_PUBLISH', priceObj, signerPubkeyHex, punishOrigin);
        if (claimPrice.duplicate) {
          if (this.settings.debug) {
            this.emit('debug', '[FABRIC:PEER] Ignoring duplicate P2P_DOCUMENT_PUBLISH pricing frame');
          }
          break;
        }
        this.emit('documentPublish', {
          message,
          origin,
          socket,
          documentId: priceObj && priceObj.hash,
          rateSats: priceObj && priceObj.rate,
          contentHash: priceObj && priceObj.contentHash,
          source: 'pricing'
        });
        break;
      }
      case 'P2P_FILE_SEND': {
        // Reverse private-relay path: forward toward buyer before local ingest.
        // Typed wire is wrapped as `{ type, object }` before Generic dispatch — use
        // msg.object (not message.data, which only exists on raw Message).
        try {
          let fileObj = null;
          if (msg && msg.object && typeof msg.object === 'object' && !Array.isArray(msg.object)) {
            fileObj = msg.object;
          } else if (message && message.data != null) {
            const rawFile = messageDataToString(message.data);
            const prFile = tryParseWireJsonBody(rawFile);
            if (prFile.ok && prFile.value && typeof prFile.value === 'object') fileObj = prFile.value;
          } else if (wireMessage && wireMessage.data != null) {
            const rawFile = messageDataToString(wireMessage.data);
            const prFile = tryParseWireJsonBody(rawFile);
            if (prFile.ok && prFile.value && typeof prFile.value === 'object') fileObj = prFile.value;
          }
          if (fileObj && this._maybeReverseRelayFileSend(fileObj, origin)) {
            break;
          }
        } catch (_) { /* fall through to ingest */ }
        const ingest = this._ingestP2pFileSend(msg || message, origin, wireMessage || (message && message.signature ? message : null));
        this.emit('file', Object.assign({ message, origin }, ingest));
        if (ingest && ingest.status === 'complete' && ingest.buffer) {
          this.emit('documentReceived', {
            documentId: ingest.documentId,
            buffer: ingest.buffer,
            merkleRootHex: ingest.merkleRootHex,
            verified: !!ingest.verified,
            unindexed: !!ingest.unindexed,
            origin
          });
        } else if (ingest && ingest.status === 'awaiting_key') {
          this.emit('documentAwaitingKey', {
            documentId: ingest.documentId,
            merkleRootHex: ingest.merkleRootHex,
            origin
          });
        } else if (ingest && ingest.status === 'reject') {
          this.emit('documentBlobRejected', {
            documentId: ingest.documentId,
            error: ingest.error,
            blobIndex: ingest.blobIndex,
            origin
          });
        }
        break;
      }
      case 'CONTRACT_PUBLISH': {
        this.emit('debug', `Handling peer contract publish: ${JSON.stringify(msg.object)}`);
        if (!msg.object || typeof msg.object !== 'object') break;
        const publishedId = (new Actor(msg.object)).id;
        // Authz before logical claim: a front-run signed by a non-party must not
        // burn the content-addressed registration slot for the real publisher.
        if (!this._contractPublishSignerAuthorized(msg.object, signerPubkeyHex)) {
          this.emit('warning',
            `[FABRIC:PEER] CONTRACT_PUBLISH rejected for ${publishedId}: ` +
            'wire signer is not listed in parties/validators/owners/members/authorities');
          break;
        }
        const claimPub = this._claimLogicalRegistrationOrPunish(
          'CONTRACT_PUBLISH', msg.object, signerPubkeyHex, punishOrigin);
        if (claimPub.duplicate) {
          if (this.settings.debug) {
            this.emit('debug',
              `[FABRIC:PEER] Ignoring duplicate CONTRACT_PUBLISH for ${publishedId} (no allow-list / emit / relay)`);
          }
          break;
        }
        if (this.settings.registerInboundContracts !== false) {
          if (!this._registerContract(msg.object, signerPubkeyHex)) break;
        }
        this.emit('contract:publish', {
          contract: publishedId,
          object: msg.object,
          origin,
          signer: signerPubkeyHex || null
        });
        // Peel / RELAY unwrap: deliver locally only (outer envelope already floods).
        if (delivery.allowMeshRelay && origin && origin.name && wireMessage) {
          this.relayFrom(origin.name, wireMessage);
        }
        break;
      }
      case 'CONTRACT_MESSAGE': {
        if (this.settings.debug) this.emit('debug', `Handling contract message: ${JSON.stringify(msg.object)}`);
        const contractId = msg.object && msg.object.contract ? String(msg.object.contract) : null;
        if (!contractId) {
          this.emit('warning', '[FABRIC:PEER] CONTRACT_MESSAGE missing `contract` namespace id; dropped');
          break;
        }
        const registered = !!(this._state.content.contracts && this._state.content.contracts[contractId]);
        // State ops only apply to locally registered contract namespaces —
        // unknown ids must not crash the peer (message may still be app-consumed).
        if (registered && Array.isArray(msg.object.ops) && msg.object.ops.length) {
          if (!this._signerMayPatchContract(contractId, signerPubkeyHex)) {
            this.emit('warning',
              `[FABRIC:PEER] CONTRACT_MESSAGE ops rejected for ${contractId}: signer not in contract allow-list` +
              `${peeledForward ? ' (peeled forward)' : ''}`);
            const opsPs = this.settings.peerScore || {};
            // Onion peel: do not cut the honest last-hop TCP link for an unauthorized inner.
            this._applyPeerMisbehavior(punishOrigin, 'contract-ops-forbidden', {
              penalty: Number(opsPs.contractOpsForbiddenPenalty) || PEER_SCORE_CONTRACT_OPS_FORBIDDEN_PENALTY,
              disconnect: delivery.hardDisconnect
            });
            // Do not emit or relay — forbidden ops must not be laundered through the mesh.
            break;
          }
          try {
            manager.applyPatch(this._state.content.contracts[contractId], msg.object.ops);
            this.commit();
          } catch (exception) {
            this.emit('warning', `[FABRIC:PEER] CONTRACT_MESSAGE patch failed for ${contractId}: ${exception.message}`);
            break;
          }
        }
        this.emit('contract:message', {
          contract: contractId,
          registered,
          object: msg.object,
          origin,
          signer: signerPubkeyHex || null,
          // Bit-identical AMP frame for journal / audit attach (apps ignore if unused).
          wireMessage: wireMessage || null,
          messageId: wireMessage && wireMessage.id ? wireMessage.id : null,
          genesis: this._contractGenesis[contractId] || null,
          // Lazy: skip toBuffer() unless a listener reads messageHex.
          get messageHex () {
            if (this._cachedMessageHex !== undefined) return this._cachedMessageHex;
            this._cachedMessageHex = wireMessage && typeof wireMessage.toBuffer === 'function'
              ? wireMessage.toBuffer().toString('hex')
              : null;
            return this._cachedMessageHex;
          }
        });
        // Same outermost-only flood rule as CONTRACT_PUBLISH / chat / gossip.
        if (delivery.allowMeshRelay && origin && origin.name && wireMessage) {
          this.relayFrom(origin.name, wireMessage);
        }
        break;
      }
    }
  }

  /**
   * True when a TCP/NOISE error is a routine connect/reset (not an application fault).
   * Node sometimes omits `error.code` and only puts `ECONNREFUSED` in the message.
   * @param {*} error
   * @returns {boolean}
   */
  _isTransientSocketError (error) {
    const code = error && error.code;
    if (code === 'EPIPE' || code === 'ECONNRESET' || code === 'ECONNREFUSED' ||
        code === 'EHOSTUNREACH' || code === 'ENETUNREACH' || code === 'ETIMEDOUT') {
      return true;
    }
    const text = String((error && error.message) || error || '');
    return /ECONNREFUSED|ECONNRESET|EPIPE|ETIMEDOUT|EHOSTUNREACH|ENETUNREACH/.test(text);
  }

  /**
   * NOISE transport limits from settings (absolute handshake deadline + pre-handshake byte budget).
   * @returns {{ handshakeTimeout: number, handshakeMaxBytes: number }}
   */
  _noiseTransportOptions () {
    const timeout = (typeof this.settings.handshakeTimeout === 'number')
      ? this.settings.handshakeTimeout
      : ((typeof this.settings.connectTimeout === 'number') ? this.settings.connectTimeout : 10000);
    const budget = Number(this.settings.handshakeMaxBytes);
    return {
      handshakeTimeout: timeout > 0 ? timeout : 0,
      handshakeMaxBytes: Number.isInteger(budget) && budget > 0 ? budget : NOISE_HANDSHAKE_MAX_BYTES
    };
  }

  /**
   * Tie a NOISE pair to its TCP socket: a destroyed decrypt side (limit broken, handshake
   * timeout, decrypt failure) destroys the socket. The remote frame cap starts at the
   * legacy 4096 bytes until its session message advertises `maxFrameBytes`.
   * @param {Object} noiseStream noise-protocol-stream duplex pair
   * @param {Object} socket
   * @returns {void}
   */
  _bindNoiseTransportToSocket (noiseStream, socket) {
    if (!noiseStream || !noiseStream.decrypt || !socket) return;
    noiseStream._fabricRemoteMaxFrameBytes = LEGACY_MAX_FRAME_BYTES;
    noiseStream.decrypt.once('close', () => {
      if (!socket.destroyed && typeof socket.destroy === 'function') socket.destroy();
    });
  }

  /**
   * Local AMP frame cap (header + `maxMessageSize` body) — what this node accepts and advertises.
   * @returns {number}
   */
  _localMaxFrameBytes () {
    const maxBody = Number(this.settings.maxMessageSize);
    const bodyCap = Number.isFinite(maxBody) && maxBody > 0 ? Math.min(maxBody, MAX_MESSAGE_SIZE) : MAX_MESSAGE_SIZE;
    return HEADER_SIZE + bodyCap;
  }

  /**
   * Record the frame cap a remote advertised in `P2P_SESSION_OFFER` / `P2P_SESSION_OPEN`
   * (`object.maxFrameBytes`). Absent or invalid = legacy 4096-byte peer.
   * @param {string} connAddress
   * @param {Object} sessionObject Session message `object`
   * @returns {number} Cap now used for frames sent to that connection
   */
  _recordRemoteFrameCap (connAddress, sessionObject) {
    const advertised = Number(sessionObject && sessionObject.maxFrameBytes);
    const cap = (Number.isInteger(advertised) && advertised > HEADER_SIZE)
      ? Math.min(advertised, HEADER_SIZE + MAX_MESSAGE_SIZE)
      : LEGACY_MAX_FRAME_BYTES;
    const socket = connAddress && this.connections ? this.connections[connAddress] : null;
    if (!socket) return cap;
    socket._fabricRemoteMaxFrameBytes = cap;
    const noiseClient = socket._noiseClient || socket._noiseHandler;
    if (noiseClient) noiseClient._fabricRemoteMaxFrameBytes = cap;
    return cap;
  }

  /**
   * Bind encrypt/decrypt 'error' before piping. noise-protocol-stream calls
   * stream.destroy(err) on handshake failure; without listeners Node raises
   * uncaught Exceptions (e.g. `noise_stream_new`, `malloc`).
   * @param {Object} noiseStream noise-protocol-stream duplex pair
   * @param {stream.Duplex} noiseStream.encrypt
   * @param {stream.Duplex} noiseStream.decrypt
   * @param {string} [label='NOISE']
   */
  _attachNoiseStreamErrorHandlers (noiseStream, label = 'NOISE') {
    if (!noiseStream || !noiseStream.encrypt || !noiseStream.decrypt) return;
    if (noiseStream._fabricNoiseErrorHandlers) {
      this._detachNoiseStreamErrorHandlers(noiseStream);
    }
    const onSide = (side) => (error) => {
      if (this._isTransientSocketError(error)) {
        const code = (error && error.code) || 'ECONNRESET';
        this.emit('warning', `Suppressing transient ${label} ${side} error (${code}).`);
        return;
      }
      const text = String((error && error.message) || error || '');
      const msg = `${label} ${side} error: ${error}`;
      // Native teardown after a bad self-handshake / OOM, or a remote that broke a
      // transport limit (socket is destroyed by _bindNoiseTransportToSocket) — keep process alive.
      if (/noise_stream_new|\bmalloc\b|noise_message_too_large|noise_handshake_(budget|timeout)/i.test(text)) {
        this.emit('warning', msg);
        return;
      }
      if (this.listenerCount('error') > 0) this.emit('error', msg);
      else this.emit('warning', msg);
    };
    const onEncrypt = onSide('encrypt');
    const onDecrypt = onSide('decrypt');
    noiseStream.encrypt.on('error', onEncrypt);
    noiseStream.decrypt.on('error', onDecrypt);
    noiseStream._fabricNoiseErrorHandlers = { onEncrypt, onDecrypt };
  }

  /**
   * Remove encrypt/decrypt 'error' listeners attached by {@link Peer#_attachNoiseStreamErrorHandlers}.
   * @param {Object} noiseStream
   * @returns {void}
   */
  _detachNoiseStreamErrorHandlers (noiseStream) {
    const handlers = noiseStream && noiseStream._fabricNoiseErrorHandlers;
    if (!handlers) return;
    try {
      if (noiseStream.encrypt && typeof noiseStream.encrypt.removeListener === 'function') {
        noiseStream.encrypt.removeListener('error', handlers.onEncrypt);
      }
    } catch (_) { /* ignore */ }
    try {
      if (noiseStream.decrypt && typeof noiseStream.decrypt.removeListener === 'function') {
        noiseStream.decrypt.removeListener('error', handlers.onDecrypt);
      }
    } catch (_) { /* ignore */ }
    noiseStream._fabricNoiseErrorHandlers = null;
  }

  /**
   * Unpipe and destroy a NOISE pair so shared handshake emitters do not leak listeners.
   * @param {object|null} socket
   * @returns {void}
   */
  _teardownNoiseClient (socket) {
    if (!socket) return;
    const noiseClient = socket._noiseClient || socket._noiseHandler;
    if (!noiseClient) return;
    this._detachNoiseStreamErrorHandlers(noiseClient);
    try {
      if (noiseClient.encrypt && typeof noiseClient.encrypt.unpipe === 'function') {
        noiseClient.encrypt.unpipe(socket);
      }
    } catch (_) { /* ignore */ }
    try {
      if (typeof socket.unpipe === 'function' && noiseClient.decrypt) {
        socket.unpipe(noiseClient.decrypt);
      }
    } catch (_) { /* ignore */ }
    try {
      if (noiseClient.encrypt && typeof noiseClient.encrypt.destroy === 'function') {
        noiseClient.encrypt.destroy();
      }
    } catch (_) { /* ignore */ }
    try {
      if (noiseClient.decrypt && typeof noiseClient.decrypt.destroy === 'function') {
        noiseClient.decrypt.destroy();
      }
    } catch (_) { /* ignore */ }
    socket._noiseClient = null;
    socket._noiseHandler = null;
  }

  _NOISESocketHandler (socket) {
    const target = `${socket.remoteAddress}:${socket.remotePort}`;
    const url = `tcp://${target}`;

    if (this._isPeerBanned(target)) {
      this.emit('warning', `[FABRIC:PEER] Refusing inbound from banned address ${target}`);
      if (typeof socket.destroy === 'function') socket.destroy();
      return;
    }

    socket._destroyFabric = () => {
      this._destroyFabric(socket, target);
    };
    socket.once('close', () => {
      if (typeof socket._destroyFabric === 'function') socket._destroyFabric();
    });

    const handshakeTimeoutMs = (typeof this.settings.handshakeTimeout === 'number')
      ? this.settings.handshakeTimeout
      : ((typeof this.settings.connectTimeout === 'number') ? this.settings.connectTimeout : 10000);
    if (handshakeTimeoutMs > 0 && typeof socket.setTimeout === 'function') {
      socket.setTimeout(handshakeTimeoutMs);
      socket.once('timeout', () => {
        if (socket._fabricNoiseHandshakeOk) return;
        this.emit('warning',
          `[FABRIC:PEER] Inbound NOISE handshake timeout (${target}) after ${handshakeTimeoutMs}ms`);
        if (typeof socket.destroy === 'function') socket.destroy();
      });
    }

    // Store a unique actor for this inbound connection
    this._registerActor({ name: target });

    const _derived = this.identity.key.derive(FABRIC_KEY_DERIVATION_PATH);
    if (this.settings.debug) {
      this.emit('debug', 'NOISE inbound: session key derived for handshake (private key not logged)');
    }

    // Create NOISE handler
    const handler = noise(Object.assign(this._noiseTransportOptions(), {
      prologue: Buffer.from(PROLOGUE),
      // privateKey: _derived.private.toString('hex'),
      verify: this._verifyNOISE.bind(this)
    }));
    this._bindNoiseTransportToSocket(handler, socket);

    // Handle low-level socket errors for inbound connections
    socket.on('error', (error) => {
      if (this.settings.debug) this.emit('debug', `--- debug error from _NOISESocketHandler() ---`);
      if (this._isTransientSocketError(error)) {
        const code = (error && error.code) || 'ECONNRESET';
        this.emit('warning', `Suppressing transient inbound socket error (${code}) from _NOISESocketHandler().`);
      } else {
        const msg = `Inbound socket error (${target}): ${error}`;
        if (this.listenerCount('error') > 0) this.emit('error', msg);
        else this.emit('warning', msg);
      }
    });

    // Set up NOISE event handlers
    handler.encrypt.on('handshake', (_lk, localPk, remotePk) => {
      socket._fabricNoiseHandshakeOk = true;
      if (typeof socket.setTimeout === 'function') socket.setTimeout(0);
      if (this.settings.debug) {
        // Transport diagnostics only — never log private key material from the handshake.
        this.emit('debug', `Peer transport handshake using local public key: ${localPk.toString('hex')}`);
        this.emit('debug', `Peer transport handshake with remote public key: ${remotePk.toString('hex')}`);
      }
      if (remotePk != null) {
        const pkHex = normalizePeerPubkeyHex(Buffer.isBuffer(remotePk) ? Buffer.from(remotePk) : remotePk);
        if (pkHex) {
          this._inboundNoiseStaticPubkeyByAddress[target] = pkHex;
          if (this._isPeerBanned(target, pkHex)) {
            this.emit('warning', `[FABRIC:PEER] Closing inbound: banned Noise static ${pkHex.slice(0, 16)}…`);
            this._destroyFabric(socket, target);
            if (typeof socket.destroy === 'function') socket.destroy();
          }
        }
      }
    });
    handler.encrypt.on('end', (data) => {
      if (this.settings.debug) this.emit('debug', `Peer encrypt end: ${data}`);
      this._destroyFabric(socket, target);
    });

    this._attachNoiseStreamErrorHandlers(handler, 'NOISE');
    socket._noiseHandler = handler;

    handler.decrypt.on('close', (data) => {
      if (this.settings.debug) this.emit('debug', `Peer decrypt close: ${data}`);
    });

    handler.decrypt.on('end', (data) => {
      if (this.settings.debug) {
        this.emit('debug', `Peer decrypt end: (${target}) ${data}`);
        this.emit('debug', `Connections: ${Object.keys(this.connections)}`);
      }
      socket._destroyFabric();
    });

    handler.decrypt.on('data', (data) => {
      this._recordPeerBandwidth(target, 'in', data);
      this._handleFabricMessage(data, { name: target });
    });

    socket._fabricPeerAddress = target;
    socket._writeFabric = (msg) => {
      const written = this._writeFabric(msg, handler);
      if (written) this._recordPeerBandwidth(target, 'out', msg);
      return written;
    };

    // Store socket in collection
    this.connections[target] = socket;
    this._startFabricPingKeepalive(socket, handler.encrypt);

    // Begin NOISE stream
    handler.encrypt.pipe(socket).pipe(handler.decrypt);

    this.emit('connections:open', {
      id: target,
      url: url
    });
  }

  /**
   * Build hub-compatible document metadata for {@link purchaseContentHashHex}.
   * @param {String} documentId
   * @param {String} content UTF-8 body
   * @returns {Object} Parsed document record (whitelisted fields)
   */
  _buildDocumentParsedForPublish (documentId, content) {
    const docs = this._state.content.documents;
    const stored = docs && docs[documentId] === content ? this.getDocumentBuffer(documentId) : null;
    const buf = stored || Buffer.from(content === null || content === undefined ? '' : String(content), 'utf8');
    return {
      id: documentId,
      name: (documentId && String(documentId).split('/').pop()) || 'document',
      mime: 'text/plain',
      revision: 1,
      contentBase64: buf.toString('base64'),
      size: buf.length,
      sha256: crypto.createHash('sha256').update(buf).digest('hex')
    };
  }

  /**
   * Items for Hub-style `kind: 'documents'` inventory (Fabric UI / `@fabric/hub` merge expects `object.kind`).
   * Documents a catalog row marks unpublished (private, bought, or unlisted) are left out.
   * @param {Object} [req] request object subset
   * @returns {object[]}
   */
  _collectDocumentCatalogInventoryItems (_req) {
    const docs = this._state.content.documents;
    if (!docs || typeof docs !== 'object') return [];
    const collections = this._state.content.collections && typeof this._state.content.collections.documents === 'object'
      ? this._state.content.collections.documents
      : {};
    const rates = this._state.content.documentRates || {};
    /** @type {object[]} */
    const items = [];
    for (const docId of Object.keys(docs)) {
      const body = docs[docId];
      const parsed = this._buildDocumentParsedForPublish(docId, body);
      const row = collections[docId];
      const purchaseFromCollection = row && Number(row.purchasePriceSats) > 0 ? Math.round(Number(row.purchasePriceSats)) : null;
      const rateSats = Object.prototype.hasOwnProperty.call(rates, docId) ? rates[docId] : 0;
      const purchasePriceSats = purchaseFromCollection != null ? purchaseFromCollection : (Number(rateSats) > 0 ? Math.round(Number(rateSats)) : undefined);
      if (row && !row.published) continue;
      items.push({
        id: parsed.id,
        sha256: parsed.sha256 || parsed.id,
        name: parsed.name,
        mime: parsed.mime || 'application/octet-stream',
        size: parsed.size,
        created: parsed.created || new Date().toISOString(),
        published: true,
        ...(purchasePriceSats != null && purchasePriceSats > 0 ? { purchasePriceSats } : {}),
        ...(row && row.bitcoinHeight != null && Number.isFinite(Number(row.bitcoinHeight))
          ? { bitcoinHeight: Math.round(Number(row.bitcoinHeight)) }
          : {}),
        ...(row && row.bitcoinBlockHash ? { bitcoinBlockHash: String(row.bitcoinBlockHash) } : {}),
        ...(row && row.bitcoinTxid ? { bitcoinTxid: String(row.bitcoinTxid) } : {})
      });
    }
    return items;
  }

  /**
   * Write {@link INVENTORY_RESPONSE} (`P2P_INVENTORY_RESPONSE`) compatible with `@fabric/hub` Bridge merging
   * (body includes `kind: 'documents'` so the browser can merge `object.items`).
   * Items are split across as many responses as needed so each frame fits the
   * requester's frame cap; every page carries `inventoryId`, `page` (1-based), and `pages`.
   * @param {string} originName connection key {@link Peer#connections}
   * @param {object[]} items
   * @param {Object} [opts]
   * @param {boolean} [opts.allowEmpty]
   * @returns {boolean} true when at least one page was written
   */
  _sendLocalInventoryDocumentsWireResponse (originName, items, opts = {}) {
    const allowEmpty = !!(opts && opts.allowEmpty);
    if (!originName || !Array.isArray(items)) return false;
    if (!allowEmpty && items.length === 0) return false;
    const conn = this.connections[originName];
    if (!conn || !conn._writeFabric) return false;
    const remoteCap = Number.isInteger(conn._fabricRemoteMaxFrameBytes)
      ? conn._fabricRemoteMaxFrameBytes
      : HEADER_SIZE + MAX_MESSAGE_SIZE;
    // 256 bytes leaves room for the page envelope (kind, created, inventoryId, page, pages).
    const pageBytes = Math.max(512, Math.min(INVENTORY_RESPONSE_PAGE_BYTES, remoteCap - HEADER_SIZE - 256));
    const { pages, skipped } = paginateInventoryItems(items, { pageBytes });
    for (const item of skipped) {
      this.emit('warning',
        `[FABRIC:PEER] Inventory item ${String(item.id || item.documentId || '?').slice(0, MAX_DOCUMENT_ID_LENGTH)} ` +
        `does not fit one ${remoteCap}-byte frame; omitted`);
    }
    if (!pages.length) {
      if (!allowEmpty || items.length) return false;
      pages.push([]);
    }
    const inventoryId = crypto.randomBytes(8).toString('hex');
    const created = Date.now();
    let written = 0;
    for (let i = 0; i < pages.length; i++) {
      const obj = {
        kind: 'documents',
        items: pages[i],
        created,
        inventoryId,
        page: i + 1,
        pages: pages.length
      };
      let buf;
      try {
        buf = Message.fromVector(['P2P_INVENTORY_RESPONSE', JSON.stringify(obj)]).signWithKey(this.key).toBuffer();
      } catch (err) {
        this.emit('warning', `[FABRIC:PEER] Inventory page ${i + 1}/${pages.length} not sent: ${err && err.message ? err.message : err}`);
        continue;
      }
      if (conn._writeFabric(buf) !== false) written++;
    }
    return written > 0;
  }

  /**
   * Reply to `INVENTORY_REQUEST` with `INVENTORY_RESPONSE` built from local documents and rates.
   * @param {{type: string, object: (Object|undefined)}} message Generic body from {@link Peer#_handleGenericMessage}
   * @param {{ name: string }} origin
   * @returns {boolean} true if an `INVENTORY_RESPONSE` was written to the requester
   */
  _respondInventoryFromLocalDocuments (message, origin) {
    if (!origin || !origin.name) return false;
    const req = message.object || {};
    const docs = this._state.content.documents;
    if (!docs || typeof docs !== 'object') return false;

    if (req.offerBtc === true) {
      const rates = this._state.content.documentRates || {};
      const maxSats = req.maxSats;
      const chunkBytes = Math.max(1, Number(this.settings.inventoryBlobChunkBytes) || Document.CHUNK_BYTES);
      // Chunk-index selectors (handler-side filter on existing item fields).
      const wantBlob = /^[0-9a-f]{64}$/i.test(String(req.blobHashHex || '')) ? String(req.blobHashHex).toLowerCase() : null;
      const wantRoot = /^[0-9a-f]{64}$/i.test(String(req.merkleRootHex || '')) ? String(req.merkleRootHex).toLowerCase() : null;
      /** @type {object[]} */
      const items = [];
      for (const docId of Object.keys(docs)) {
        const body = docs[docId];
        const parsed = this._buildDocumentParsedForPublish(docId, body);
        const rateSats = Object.prototype.hasOwnProperty.call(rates, docId) ? rates[docId] : 0;
        if (maxSats != null && Number.isFinite(maxSats) && rateSats > maxSats) continue;
        const sealedMeta = this._getDocumentSealedMeta(docId);
        const bodyBuf = this.getDocumentBuffer(docId) || Buffer.alloc(0);
        const advertiseBuf = sealedMeta ? sealedMeta.ciphertext : bodyBuf;
        const resolved = resolveDocumentContentHashHex({
          documentId: docId,
          parsed,
          sealedMeta: sealedMeta || undefined,
          sealed: !!sealedMeta
        });
        const contentHash = resolved.contentHashHex;
        const item = {
          id: docId,
          rateSats,
          contentHash,
          contentHashHex: contentHash,
          binding: resolved.binding,
          network: 'bitcoin',
          size: sealedMeta ? sealedMeta.ciphertext.length : bodyBuf.length
        };
        // Always advertise a DocumentBlobIndex (one blob when small; many when large).
        let advertised;
        try {
          advertised = sealedMeta
            ? advertiseSealedDocument({
              ciphertext: sealedMeta.ciphertext,
              paymentHashHex: sealedMeta.paymentHashHex,
              encryption: sealedMeta.encryption,
              plaintextSha256: sealedMeta.plaintextSha256
            }, {
              documentId: docId,
              chunkBytes,
              rateSats
            })
            : Document.advertise(advertiseBuf, {
              documentId: docId,
              chunkBytes,
              rateSats,
              includePaymentHashes: true
            });
        } catch (e) {
          this.emit('warning', `[FABRIC:PEER] inventory skipped ${docId}: ${e.message}`);
          continue;
        }
        if (sealedMeta) {
          item.sealed = true;
          item.encryption = sealedMeta.encryption;
        }
        item.merkleRootHex = advertised.merkleRootHex;
        item.documentBlobIndex = advertised.index;
        item.contentSha256 = advertised.contentSha256;
        item.chunkBytes = advertised.chunkBytes;
        item.blobTotal = advertised.blobs.length;
        // Keep inventory AMP-sized: inline leaf list only when the index fits.
        if (advertised.index.leavesInline !== false) {
          item.blobs = advertised.itemBlobs;
        } else {
          item.blobs = [];
          item.leavesInline = false;
        }
        // Selector filters: by tree root, or by one blob hash (reply with that blob only).
        if (wantRoot && String(item.merkleRootHex || '').toLowerCase() !== wantRoot) continue;
        if (wantBlob) {
          const hit = (advertised.blobs || []).find((b) => String(b.blobHashHex || '').toLowerCase() === wantBlob);
          if (!hit) continue;
          item.blobs = (advertised.itemBlobs || []).filter((b) => String(b.blobHashHex || '').toLowerCase() === wantBlob);
          item.leavesInline = true;
        }
        if (this.settings.attachInventoryHtlc && rateSats > 0) {
          try {
            if (sealedMeta) {
              // One HTLC bound to SHA256(content key) — claim reveals K.
              const htlc = this._attachHtlcOfferToItem(item, req, sealedMeta.paymentHashHex, rateSats);
              if (htlc) item.htlc = htlc;
            } else if (Array.isArray(item.blobs) && item.blobs.length) {
              for (const b of item.blobs) {
                const payHash = b.contentHash || contentHash;
                const amt = Number(b.rateSats != null ? b.rateSats : rateSats) || rateSats;
                const htlc = this._attachHtlcOfferToItem(
                  { id: `${docId}#${b.index}` },
                  req,
                  payHash,
                  amt
                );
                if (htlc) b.htlc = htlc;
              }
              if (item.blobs.length === 1 && item.blobs[0].htlc) {
                item.htlc = item.blobs[0].htlc;
              }
            } else {
              const htlc = this._attachHtlcOfferToItem(item, req, contentHash, rateSats);
              if (htlc) item.htlc = htlc;
            }
          } catch (e) {
            this.emit('warning', `[FABRIC:PEER] inventory HTLC attach failed for ${docId}: ${e.message}`);
          }
        }
        items.push(item);
      }
      for (const item of this._sealedBlobInventoryItems(req)) items.push(item);
      if (!items.length) return false;
      return this._sendLocalInventoryDocumentsWireResponse(origin.name, items);
    }

    const reqKind = String(req.kind || '').trim().toLowerCase();
    if (reqKind !== 'documents') return false;
    const items = this._collectDocumentCatalogInventoryItems({});
    return this._sendLocalInventoryDocumentsWireResponse(origin.name, items, { allowEmpty: true });
  }

  /**
   * @param {string} documentId
   * @returns {object|null}
   */
  /**
   * Register a per-blob sealed {@link Document} (one key per blob) for sale.
   * Inventory advertises hash-only leaves with per-blob payment hashes; buyers
   * settle one HTLC per blob plan and receive one key reveal per blob.
   * @param {Document} doc Sealed document that holds its blob keys.
   * @param {Object} [opts]
   * @param {number} [opts.rateSats=0] Per-blob ask: 0 (free) or at least
   * `HTLC_MINIMUM_SATS`, since each blob settles with its own HTLC.
   * @param {number} [opts.creditRateSats] Per-blob price on the credit rail:
   * the key is revealed first and the buyer pays afterwards with a channel
   * transfer, so any positive price works (no HTLC minimum). Convergent
   * documents only — random-key documents never reveal before payment.
   * Each credit request goes through `settings.sealedBlobCredit`.
   * @param {number} [opts.creditLimitSats] Most a buyer may owe this seller
   * at once (passed to `settings.sealedBlobCredit` as `limitSats`).
   * @param {string} [opts.documentId] Catalog id (default: the Document's).
   * A convergent document is always published under its tree root, so every
   * seller's offers line up; a different id is kept only as a local `label`.
   * @returns {{ ok: boolean, documentId: (string|undefined), label: (string|null|undefined), error: (string|undefined) }}
   */
  publishSealedDocument (doc, opts = {}) {
    if (!doc || typeof doc.record !== 'function' || !doc.sealed) {
      return { ok: false, error: 'sealed Document required' };
    }
    const rateSats = Math.max(0, Math.floor(Number(opts.rateSats) || 0));
    if (rateSats > 0 && rateSats < HTLC_MINIMUM_SATS) {
      return { ok: false, error: `rateSats ${rateSats} is below the ${HTLC_MINIMUM_SATS}-sat HTLC minimum (use 0 for free, or larger blobs)` };
    }
    const creditRateSats = Math.max(0, Math.floor(Number(opts.creditRateSats) || 0));
    if (creditRateSats > 0 && !doc.convergent) {
      return { ok: false, error: 'creditRateSats needs a convergent document (private documents are paid before the key is revealed)' };
    }
    const creditLimitSats = opts.creditLimitSats != null ? Math.max(0, Math.floor(Number(opts.creditLimitSats) || 0)) : null;
    const named = String(opts.documentId || doc.documentId || doc.merkleRootHex || '').trim();
    const documentId = doc.convergent ? String(doc.merkleRootHex || '') : named;
    const label = named && named !== documentId ? named : null;
    if (!documentId) return { ok: false, error: 'documentId required' };
    if (!isWireDocumentId(documentId)) return { ok: false, error: 'documentId too long for the wire' };
    const record = Object.assign(doc.record(), { documentId });
    // Ciphertext + keys only (no plaintext), held outside `_state`.
    const held = Document.fromRecord(record);
    for (const b of doc.blobs) {
      const bytes = doc.bytesFor(b.index);
      const key = doc.keyFor(b.index);
      if (!bytes || !key) return { ok: false, error: `blob ${b.index} missing ciphertext or key` };
      if (!held.acceptBytes(b.index, bytes) || !held.setKey(b.index, key)) {
        return { ok: false, error: `blob ${b.index} does not match the document root` };
      }
    }
    this._forgetSealedBlobDocument(documentId);
    this._sealedBlobSecrets.set(documentId, { doc: held });
    for (const b of held.blobs) {
      if (b.paymentHashHex) this._sealedBlobByPaymentHash.set(b.paymentHashHex, { documentId, blobIndex: b.index });
    }
    if (!this._state.content.documentSealedBlobs) this._state.content.documentSealedBlobs = {};
    if (!this._state.content.documentRates) this._state.content.documentRates = {};
    this._state.content.documentSealedBlobs[documentId] = label ? { record, label } : { record };
    this._state.content.documentRates[documentId] = rateSats;
    if (!this._state.content.documentCreditRates) this._state.content.documentCreditRates = {};
    if (creditRateSats > 0) this._state.content.documentCreditRates[documentId] = { rateSats: creditRateSats, limitSats: creditLimitSats };
    else delete this._state.content.documentCreditRates[documentId];
    this.commit();
    this.emit('documentSealedBlobsPublished', { documentId, label, merkleRootHex: doc.merkleRootHex, blobTotal: doc.blobTotal });
    return { ok: true, documentId, label };
  }

  /**
   * Credit-rail terms for a published sealed document.
   * @param {string} documentId
   * @returns {{ rateSats: number, limitSats: (number|null) }|null}
   * @private
   */
  _sealedBlobCreditTerms (documentId) {
    const row = (this._state.content.documentCreditRates || {})[documentId];
    if (!row || !(Number(row.rateSats) > 0)) return null;
    return { rateSats: Math.floor(Number(row.rateSats)), limitSats: row.limitSats != null ? Number(row.limitSats) : null };
  }

  /**
   * Seller: reveal a convergent blob key on credit (pay after verify). The
   * request must name the blob's payment hash, set `credit: true`, and carry
   * a `creditRef` the buyer will name in its channel transfer. The host's
   * `settings.sealedBlobCredit({ buyer, buyerPubkey, documentId, blobIndex,
   * priceSats, ref, limitSats })` decides (typically
   * `ChannelBook#extendCredit`); it must return `true` or `{ ok: true }`.
   * @param {string} documentId
   * @param {number} blobIndex
   * @param {string} paymentHashHex
   * @param {Object} parsed DocumentRequest body
   * @param {string|null} peerAddress the buyer's connection
   * @returns {boolean}
   * @private
   */
  _extendSealedBlobCredit (documentId, blobIndex, paymentHashHex, parsed, peerAddress) {
    const terms = this._sealedBlobCreditTerms(documentId);
    const hook = this.settings.sealedBlobCredit;
    if (!terms || typeof hook !== 'function' || !peerAddress) return false;
    if (!requestMatchesPaymentHash(parsed, paymentHashHex)) return false;
    const ref = String(parsed.creditRef || '').trim();
    if (!ref || ref.length > 256) return false;
    const row = this.peers && this.peers[peerAddress];
    const request = {
      buyer: peerAddress,
      buyerPubkey: (row && row.publicKey) || null,
      documentId,
      blobIndex,
      priceSats: terms.rateSats,
      ref,
      limitSats: terms.limitSats
    };
    let out;
    try {
      out = hook(request);
    } catch (e) {
      out = { ok: false, error: e && e.message ? e.message : String(e) };
    }
    const ok = out === true || !!(out && out.ok === true);
    this.emit('documentBlobCredit', Object.assign({ ok, error: ok ? null : String((out && out.error) || 'credit refused') }, request));
    return ok;
  }

  /**
   * Seller side: the HTLC preimage for `paymentHashHex` — `K_i` for a static
   * blob hash (`SHA256(K_i)`), or the per-buyer secret `s` of a live
   * {@link Peer#quoteSealedBlob} quote. Channel hosts hand this to
   * `ChannelBook` as `preimageFor` so a committed HTLC for a blob we sell is
   * fulfilled (seller-fulfils; the buyer learns the preimage from the
   * `ChannelHtlcFulfill`).
   *
   * Pass the HTLC being fulfilled: one paying less than the blob's price
   * (`documentRates`, or the quote's `priceSats`) gets `null`. Without `htlc`
   * no amount check is possible; settlement code must always pass it. With
   * `sealedBlobPaymentMode: 'perBuyer'` static hashes are never fulfilled
   * (that would publish `K_i`).
   * @param {string} paymentHashHex
   * @param {Object} [htlc] `{ amountSats, expireAfter?, expireHeight? }`
   * @returns {{ documentId: string, blobIndex: number, preimageHex: string, keyHex: string, perBuyer: boolean, priceSats: number }|null}
   * `keyHex` is the preimage (kept for callers written against static hashes).
   */
  sealedBlobPreimageForPaymentHash (paymentHashHex, htlc = null) {
    const ph = String(paymentHashHex || '').toLowerCase();
    if (!/^[0-9a-f]{64}$/.test(ph)) return null;
    const paid = htlc && typeof htlc === 'object' ? Number(htlc.amountSats) : null;
    if (htlc && !(paid >= 0)) return null;
    const quote = this._sealedBlobQuotes.get(ph);
    if (quote) {
      if (quote.expiresAt && Date.now() > quote.expiresAt) {
        this._sealedBlobQuotes.delete(ph);
        return null;
      }
      if (paid != null && paid < quote.priceSats) return null;
      return { documentId: quote.documentId, blobIndex: quote.blobIndex, preimageHex: quote.secretHex, keyHex: quote.secretHex, perBuyer: true, priceSats: quote.priceSats };
    }
    if (this.settings.sealedBlobPaymentMode === 'perBuyer') return null;
    const hit = this._sealedBlobByPaymentHash.get(ph);
    if (!hit) return null;
    const doc = this._getSealedBlobDocument(hit.documentId);
    const keyHex = doc && doc.keyFor(hit.blobIndex);
    if (!keyHex || doc.paymentHashFor(hit.blobIndex) !== ph) return null;
    const priceSats = this._sealedBlobPriceSats(hit.documentId);
    if (paid != null && paid < priceSats) return null;
    return { documentId: hit.documentId, blobIndex: hit.blobIndex, preimageHex: keyHex, keyHex, perBuyer: false, priceSats };
  }

  /**
   * Per-blob ask for a published sealed document.
   * @param {string} documentId
   * @returns {number}
   * @private
   */
  _sealedBlobPriceSats (documentId) {
    const rates = this._state.content.documentRates || {};
    const rate = Object.prototype.hasOwnProperty.call(rates, documentId) ? Number(rates[documentId]) : 0;
    return Number.isFinite(rate) && rate > 0 ? Math.floor(rate) : 0;
  }

  /**
   * Seller: issue a per-buyer quote for one blob (see
   * `functions/documentSealedExchange.js` `createBlobQuote`). The buyer funds
   * an HTLC to `quote.paymentHashHex`; fulfilling it reveals `s`, which
   * unwraps `K_i` only for the holder of `quote.wrappedKeyHex`. Quotes live
   * in a bounded private map until `expiresAt`.
   * @param {Object} opts
   * @param {string} opts.documentId
   * @param {number} opts.blobIndex
   * @param {number} [opts.ttlMs] default `sealedBlobQuoteTtlMs` (1 h)
   * @returns {{ ok: boolean, quote: (Object|undefined), error: (string|undefined) }}
   */
  quoteSealedBlob (opts = {}) {
    const documentId = String(opts.documentId || '').trim();
    const blobIndex = Math.round(Number(opts.blobIndex));
    const doc = documentId ? this._getSealedBlobDocument(documentId) : null;
    if (!doc) return { ok: false, error: 'unknown sealed document' };
    const leaf = Number.isInteger(blobIndex) ? doc.blob(blobIndex) : null;
    const keyHex = leaf ? doc.keyFor(blobIndex) : null;
    if (!leaf || !keyHex) return { ok: false, error: 'unknown blob index' };
    const ttlSetting = Number(opts.ttlMs || this.settings.sealedBlobQuoteTtlMs);
    const ttl = Number.isFinite(ttlSetting) && ttlSetting > 0 ? ttlSetting : 60 * 60 * 1000;
    const priceSats = this._sealedBlobPriceSats(documentId);
    const expiresAt = Date.now() + ttl;
    const { quote, secretHex } = createBlobQuote({
      documentId,
      merkleRootHex: doc.merkleRootHex,
      blobIndex,
      blobHashHex: leaf.blobHashHex,
      keyHex,
      amountSats: priceSats,
      expiresAt
    });
    const now = Date.now();
    for (const [h, q] of this._sealedBlobQuotes) {
      if (q.expiresAt && now > q.expiresAt) this._sealedBlobQuotes.delete(h);
    }
    const capSetting = Number(this.settings.maxSealedBlobQuotes);
    const cap = Number.isFinite(capSetting) && capSetting > 0 ? capSetting : 4096;
    while (this._sealedBlobQuotes.size >= cap) {
      this._sealedBlobQuotes.delete(this._sealedBlobQuotes.keys().next().value);
    }
    this._sealedBlobQuotes.set(quote.paymentHashHex, {
      documentId,
      blobIndex,
      secretHex,
      priceSats,
      expiresAt,
      keyHashHex: quote.keyHashHex
    });
    return { ok: true, quote };
  }

  /**
   * Seller: drop the private keys / ciphertext and live quotes of a document.
   * @param {string} documentId
   * @private
   */
  _forgetSealedBlobDocument (documentId) {
    const held = this._sealedBlobSecrets.get(documentId);
    if (held && held.doc) {
      for (const b of held.doc.blobs) {
        const hit = b.paymentHashHex && this._sealedBlobByPaymentHash.get(b.paymentHashHex);
        if (hit && hit.documentId === documentId) this._sealedBlobByPaymentHash.delete(b.paymentHashHex);
      }
    }
    for (const [h, q] of this._sealedBlobQuotes) {
      if (q.documentId === documentId) this._sealedBlobQuotes.delete(h);
    }
    this._sealedBlobSecrets.delete(documentId);
  }

  /**
   * Seller copy of a published per-blob sealed document: ciphertext and keys,
   * never plaintext. Cached (no per-request decrypt). Rows written into
   * `_state` by older versions (`keys` / `ciphertextsBase64`) move to the
   * private map on first use.
   * @param {string} documentId
   * @returns {Document|null}
   */
  _getSealedBlobDocument (documentId) {
    const held = this._sealedBlobSecrets.get(documentId);
    if (held && held.doc) return held.doc;
    const reg = this._state.content.documentSealedBlobs || {};
    const row = reg[documentId];
    if (!row || !row.record || !row.keys || !row.ciphertextsBase64) return null;
    const doc = Document.fromRecord(row.record);
    for (const b of doc.blobs) {
      const ct = row.ciphertextsBase64[b.index];
      if (ct) doc.acceptBytes(b.index, Buffer.from(String(ct), 'base64'));
      if (row.keys[b.index]) doc.setKey(b.index, row.keys[b.index]);
      if (b.paymentHashHex) this._sealedBlobByPaymentHash.set(b.paymentHashHex, { documentId, blobIndex: b.index });
    }
    this._sealedBlobSecrets.set(documentId, { doc });
    reg[documentId] = { record: row.record };
    return doc;
  }

  /**
   * Inventory items for per-blob sealed documents (hash-only), honoring the
   * same `maxSats` / `blobHashHex` / `merkleRootHex` selectors as plaintext docs.
   * @param {Object} req parsed inventory request
   * @returns {object[]}
   * @private
   */
  _sealedBlobInventoryItems (req = {}) {
    const reg = this._state.content.documentSealedBlobs || {};
    const rates = this._state.content.documentRates || {};
    const maxSats = req.maxSats;
    const wantBlob = /^[0-9a-f]{64}$/i.test(String(req.blobHashHex || '')) ? String(req.blobHashHex).toLowerCase() : null;
    const wantRoot = /^[0-9a-f]{64}$/i.test(String(req.merkleRootHex || '')) ? String(req.merkleRootHex).toLowerCase() : null;
    const items = [];
    for (const docId of Object.keys(reg)) {
      const doc = Document.fromRecord(reg[docId].record);
      const rateSats = Object.prototype.hasOwnProperty.call(rates, docId) ? rates[docId] : 0;
      const credit = this._sealedBlobCreditTerms(docId);
      const cheapest = credit ? Math.min(rateSats || Infinity, credit.rateSats) : rateSats;
      if (maxSats != null && Number.isFinite(maxSats) && cheapest > maxSats) continue;
      if (wantRoot && String(doc.merkleRootHex || '').toLowerCase() !== wantRoot) continue;
      let indexes;
      if (wantBlob) {
        indexes = doc.blobs.filter((b) => b.blobHashHex === wantBlob).map((b) => b.index);
        if (!indexes.length) continue;
      }
      // A subset carries an inclusion proof per blob.
      const item = doc.inventoryItem({ documentId: docId, rateSats, indexes, creditRateSats: credit && credit.rateSats });
      if (this.settings.attachInventoryHtlc && rateSats > 0) {
        try {
          for (const b of item.blobs) {
            const htlc = this._attachHtlcOfferToItem({ id: `${docId}#${b.index}` }, req, b.contentHashHex, rateSats);
            if (htlc) b.htlc = htlc;
          }
        } catch (e) {
          this.emit('warning', `[FABRIC:PEER] inventory HTLC attach failed for ${docId}: ${e.message}`);
        }
      }
      items.push(item);
    }
    return items;
  }

  _getDocumentSealedMeta (documentId) {
    const sealed = this._state.content.documentSealed || {};
    const row = sealed[documentId];
    if (!row || !row.ciphertextBase64) return null;
    return {
      ciphertext: Buffer.from(String(row.ciphertextBase64), 'base64'),
      paymentHashHex: row.paymentHashHex,
      encryption: row.encryption,
      plaintextSha256: row.plaintextSha256,
      keyHex: (this._state.content.documentContentKeys || {})[documentId] || row.keyHex || null
    };
  }

  /**
   * Store received document bytes under `documents[documentId]` without
   * losing binary content: valid UTF-8 stays a string (as before); anything
   * else is stored base64 with `documentEncodings[documentId] = 'base64'`.
   * Read bytes back with {@link Peer#getDocumentBuffer}.
   * @param {string} documentId
   * @param {Buffer} buffer
   * @param {Object} [opts]
   * @param {boolean} [opts.overwrite=true]
   * @private
   */
  _storeReceivedDocument (documentId, buffer, opts = {}) {
    if (!this._state.content.documents) this._state.content.documents = {};
    if (!this._state.content.documentEncodings) this._state.content.documentEncodings = {};
    const docs = this._state.content.documents;
    if (opts.overwrite === false && Object.prototype.hasOwnProperty.call(docs, documentId)) return;
    const bytes = Buffer.isBuffer(buffer) ? buffer : Buffer.from(buffer || '');
    const text = bytes.toString('utf8');
    if (Buffer.from(text, 'utf8').equals(bytes)) {
      docs[documentId] = text;
      delete this._state.content.documentEncodings[documentId];
    } else {
      docs[documentId] = bytes.toString('base64');
      this._state.content.documentEncodings[documentId] = 'base64';
    }
  }

  /**
   * Bytes of a locally held document (decodes base64-stored binary documents).
   * @param {string} documentId
   * @returns {Buffer|null}
   */
  getDocumentBuffer (documentId) {
    const docs = this._state.content.documents;
    if (!docs || !Object.prototype.hasOwnProperty.call(docs, documentId)) return null;
    const body = docs[documentId];
    if (Buffer.isBuffer(body)) return Buffer.from(body);
    const encodings = this._state.content.documentEncodings || {};
    if (encodings[documentId] === 'base64') return Buffer.from(String(body), 'base64');
    return Buffer.from(String(body == null ? '' : body), 'utf8');
  }

  /**
   * Send a locally stored document as indexed, wire-sized `P2P_FILE_SEND` blobs.
   * Priced sealed docs send **ciphertext** (safe without the content key).
   * @param {string} documentId
   * @param {string} peerAddress connection key in {@link Peer#connections}
   * @param {Object} [opts]
   * @param {number} [opts.blobIndex]
   * @param {boolean} [opts.revealKey]
   * @param {string} [opts.settlementId]
   * @param {string} [opts.routeId]
   * @returns {boolean} true if at least one frame was written
   */
  _sendP2pFileSendToPeer (documentId, peerAddress, opts = {}) {
    if (!isWireDocumentId(documentId)) return false;
    const sealedBlobDoc = this._getSealedBlobDocument(documentId);
    if (sealedBlobDoc) return this._sendSealedBlobsToPeer(sealedBlobDoc, documentId, peerAddress, opts);
    const docs = this._state.content.documents;
    if (!docs || !Object.prototype.hasOwnProperty.call(docs, documentId)) return false;
    const conn = peerAddress && this.connections[peerAddress];
    if (!conn || !conn._writeFabric) return false;
    const chunkBytes = Math.max(1, Number(this.settings.inventoryBlobChunkBytes) || Document.CHUNK_BYTES);
    const sealedMeta = this._getDocumentSealedMeta(documentId);
    const bodyBuf = sealedMeta ? sealedMeta.ciphertext : this.getDocumentBuffer(documentId);
    let split;
    try {
      split = Document.split(bodyBuf, chunkBytes, documentId);
    } catch (err) {
      this.emit('warning', `[FABRIC:PEER] Cannot send document ${documentId}: ${err && err.message ? err.message : err}`);
      return false;
    }
    const merkleRootHex = sealedMeta
      ? Document.rootHexFromBlobHashes(split.blobs.map((b) => b.blobHashHex), { paymentHashHex: sealedMeta.paymentHashHex })
      : split.merkleRootHex;
    const only = opts.blobIndex != null ? Math.round(Number(opts.blobIndex)) : null;
    let wrote = 0;
    for (const b of split.blobs) {
      if (only != null && b.index !== only) continue;
      const fileObj = {
        name: documentId,
        body: b.bytes.toString('base64'),
        blobIndex: b.index,
        blobTotal: b.total,
        blobHashHex: b.blobHashHex,
        merkleRootHex,
        contentSha256: split.contentSha256,
        chunkBytes: split.chunkBytes
      };
      if (opts.routeId) fileObj.routeId = String(opts.routeId);
      if (sealedMeta) {
        fileObj.sealed = true;
        fileObj.paymentHashHex = sealedMeta.paymentHashHex;
        fileObj.iv = sealedMeta.encryption && sealedMeta.encryption.iv;
        fileObj.scheme = sealedMeta.encryption && sealedMeta.encryption.scheme;
      }
      const reply = Message.fromVector(['P2P_FILE_SEND', JSON.stringify(fileObj)]);
      reply.signWithKey(this.key);
      // `false` = refused (closed stream, or over a legacy peer's frame cap).
      if (conn._writeFabric(reply.toBuffer()) !== false) wrote += 1;
    }
    if (wrote > 0 && opts.revealKey && sealedMeta && sealedMeta.keyHex) {
      this._sendDocumentContentKeyReveal(documentId, peerAddress, {
        settlementId: opts.settlementId || null,
        routeId: opts.routeId || null
      });
    }
    return wrote > 0;
  }

  /**
   * Reveal the AES content key to a peer (only after payment-hash match).
   * @param {string} documentId
   * @param {string} peerAddress
   * @param {Object} [opts]
   * @param {string} [opts.settlementId]
   * @returns {boolean}
   */
  _sendDocumentContentKeyReveal (documentId, peerAddress, opts = {}) {
    if (opts.blobIndex != null) {
      const doc = this._getSealedBlobDocument(documentId);
      if (doc) return this._sendSealedBlobKeyReveal(doc, documentId, peerAddress, Number(opts.blobIndex), opts);
    }
    const sealedMeta = this._getDocumentSealedMeta(documentId);
    if (!sealedMeta || !sealedMeta.keyHex) return false;
    const conn = peerAddress && this.connections[peerAddress];
    if (!conn || !conn._writeFabric) return false;
    let body;
    try {
      body = buildKeyRevealMessage({
        documentId,
        keyHex: sealedMeta.keyHex,
        paymentHashHex: sealedMeta.paymentHashHex,
        iv: sealedMeta.encryption && sealedMeta.encryption.iv,
        scheme: sealedMeta.encryption && sealedMeta.encryption.scheme,
        plaintextSha256: sealedMeta.plaintextSha256,
        settlementId: opts.settlementId
      });
    } catch (err) {
      this.emit('warning', `[FABRIC:PEER] key reveal build failed: ${err.message}`);
      return false;
    }
    if (opts.routeId) body.object.routeId = String(opts.routeId);
    const msg = Message.fromVector(['GenericMessage', JSON.stringify(body)]);
    msg.signWithKey(this.key);
    if (conn._writeFabric(msg.toBuffer()) === false) return false;
    this.emit('documentContentKeyRevealed', {
      documentId,
      peerAddress,
      paymentHashHex: sealedMeta.paymentHashHex
    });
    return true;
  }

  /**
   * Send per-blob sealed ciphertext frames (and, when authorized, one key
   * reveal per blob) from a {@link Document}.
   * @param {Document} doc
   * @param {string} documentId
   * @param {string} peerAddress
   * @param {Object} [opts]
   * @param {number} [opts.blobIndex] One blob only.
   * @param {boolean} [opts.revealKey]
   * @param {string} [opts.settlementId]
   * @param {string} [opts.routeId]
   * @returns {boolean}
   * @private
   */
  _sendSealedBlobsToPeer (doc, documentId, peerAddress, opts = {}) {
    const conn = peerAddress && this.connections[peerAddress];
    if (!conn || !conn._writeFabric) return false;
    const indexes = opts.blobIndex != null ? [Number(opts.blobIndex)] : undefined;
    const frames = doc.fileSendObjects({ documentId, indexes });
    const sent = [];
    for (const fileObj of frames) {
      if (opts.routeId) fileObj.routeId = String(opts.routeId);
      const reply = Message.fromVector(['P2P_FILE_SEND', JSON.stringify(fileObj)]);
      reply.signWithKey(this.key);
      if (conn._writeFabric(reply.toBuffer()) !== false) sent.push(fileObj.blobIndex);
    }
    if (opts.revealKey) {
      for (const blobIndex of sent) this._sendSealedBlobKeyReveal(doc, documentId, peerAddress, blobIndex, opts);
    }
    return sent.length > 0;
  }

  /**
   * One existing `DocumentContentKeyReveal` for one blob (`K_i`).
   * @param {Document} doc
   * @param {string} documentId
   * @param {string} peerAddress
   * @param {number} blobIndex
   * @param {Object} [opts]
   * @returns {boolean}
   * @private
   */
  _sendSealedBlobKeyReveal (doc, documentId, peerAddress, blobIndex, opts = {}) {
    const conn = peerAddress && this.connections[peerAddress];
    if (!conn || !conn._writeFabric) return false;
    let body;
    try {
      body = doc.keyRevealFor(blobIndex, { documentId, settlementId: opts.settlementId });
    } catch (err) {
      this.emit('warning', `[FABRIC:PEER] blob key reveal build failed: ${err.message}`);
      return false;
    }
    if (opts.routeId) body.object.routeId = String(opts.routeId);
    const msg = Message.fromVector(['GenericMessage', JSON.stringify(body)]);
    msg.signWithKey(this.key);
    if (conn._writeFabric(msg.toBuffer()) === false) return false;
    this.emit('documentContentKeyRevealed', {
      documentId,
      peerAddress,
      blobIndex: Number(blobIndex),
      paymentHashHex: body.object.paymentHashHex
    });
    return true;
  }

  /**
   * Store one per-blob sealed ciphertext frame until its key reveal arrives.
   *
   * Reassembly is keyed by **document id + Merkle root**; the first frame no
   * longer dictates the shape. Every frame must carry a 64-hex root and a
   * sane `blobTotal`; frames whose root / total / origin disagree with the
   * row already being assembled (or with what `blobTransfers.expectTransfer`
   * registered for the purchase: blob hash, payment hash, and advertised IV per
   * blob index, and no index that was not bought) are rejected. Held frames
   * that violate pins registered after they arrived are replaced by one that
   * satisfies them. Otherwise an index already held never takes different
   * ciphertext; the same ciphertext with another payment hash or IV is kept as
   * a bounded alternate until the key reveal shows which one opens, and only
   * the seller the index was bought from may displace another origin's
   * alternate once the list is full. Both the number of rows and
   * the parts per row are capped. The exact signed wire frame (`frameHex`) is
   * kept per part so a `wrong-bytes` fraud proof can cite it.
   * @param {Object} obj raw `P2P_FILE_SEND` body (`perBlob: true`)
   * @param {Object} origin
   * @param {string|null} [frameHex] raw AMP frame bytes (hex) the body arrived in
   * @returns {Object}
   * @private
   */
  _ingestSealedBlobFrame (obj, origin, frameHex = null) {
    const frame = DocumentBlobTransferBook.parseFrame(obj);
    if (!frame.ok || frame.unindexed) {
      return { status: 'reject', error: (frame && frame.error) || 'bad per-blob frame' };
    }
    if (!Document.verifyBlob(frame.bytes, frame.blobHashHex)) {
      return { status: 'reject', error: 'blob hash mismatch', documentId: frame.documentId, blobIndex: frame.blobIndex };
    }
    const root = String(frame.merkleRootHex || '').toLowerCase();
    if (!/^[0-9a-f]{64}$/.test(root)) {
      return { status: 'reject', error: 'per-blob frame missing merkleRootHex', documentId: frame.documentId, blobIndex: frame.blobIndex };
    }
    const maxParts = Math.max(1, Number(this.settings.maxSealedBlobParts) || PEER_MAX_SEALED_BLOB_PARTS);
    if (!(frame.blobTotal >= 1) || frame.blobTotal > maxParts || frame.blobIndex >= frame.blobTotal) {
      return { status: 'reject', error: `per-blob frame blobTotal/blobIndex out of range (max ${maxParts})`, documentId: frame.documentId, blobIndex: frame.blobIndex };
    }
    const paymentHashHex = /^[0-9a-f]{64}$/i.test(String(obj.paymentHashHex || ''))
      ? String(obj.paymentHashHex).toLowerCase()
      : null;
    if (!paymentHashHex || !obj.iv) {
      return { status: 'reject', error: 'per-blob frame missing paymentHashHex or iv', documentId: frame.documentId };
    }
    const originName = origin && typeof origin === 'object' ? (origin.name || origin.address || origin.id || null) : (origin || null);
    // Every frame proves its leaf (blob hash, payment hash, IV) and the blob
    // count against the root, so unpaid ciphertext is checked before funding.
    const verified = Document.verifyInclusion({
      merkleRootHex: root,
      blobTotal: frame.blobTotal,
      blobIndex: frame.blobIndex,
      blobHashHex: frame.blobHashHex,
      paymentHashHex,
      iv: obj.iv,
      proof: obj.proof
    });
    if (!verified) {
      return { status: 'reject', error: 'per-blob frame is not committed by its document root (inclusion proof)', documentId: frame.documentId, blobIndex: frame.blobIndex, merkleRootHex: root };
    }
    // Purchase expectations win over whatever the wire claims.
    const expected = this.blobTransfers && typeof this.blobTransfers.expectedFor === 'function' ? this.blobTransfers.expectedFor(frame.documentId) : [];
    let pin = null;
    if (expected.length) {
      const match = expected.find((e) => (!e.merkleRootHex || e.merkleRootHex === root) && (!e.total || e.total === frame.blobTotal));
      if (!match) {
        return { status: 'reject', error: 'per-blob frame does not match the expected transfer (root / total)', documentId: frame.documentId, blobIndex: frame.blobIndex, merkleRootHex: root };
      }
      const wantHash = match.expectedHashes ? match.expectedHashes[frame.blobIndex] : null;
      if (!wantHash && match.expectedHashes && match.expectedHashes.some(Boolean)) {
        return { status: 'reject', error: 'per-blob frame is for a blob index we did not buy', documentId: frame.documentId, blobIndex: frame.blobIndex, merkleRootHex: root };
      }
      if (wantHash && wantHash !== frame.blobHashHex) {
        return { status: 'reject', error: 'per-blob frame blob hash is not the one we asked for at that index', documentId: frame.documentId, blobIndex: frame.blobIndex, merkleRootHex: root };
      }
      const wantPayment = match.expectedPaymentHashes ? match.expectedPaymentHashes[frame.blobIndex] : null;
      if (wantPayment && wantPayment !== paymentHashHex) {
        return { status: 'reject', error: 'per-blob frame payment hash is not the one we paid for at that index', documentId: frame.documentId, blobIndex: frame.blobIndex, merkleRootHex: root };
      }
      const wantIv = match.expectedIvs ? match.expectedIvs[frame.blobIndex] : null;
      if (wantIv && !Document.sameIv(wantIv, obj.iv)) {
        return { status: 'reject', error: 'per-blob frame iv is not the one advertised at that index', documentId: frame.documentId, blobIndex: frame.blobIndex, merkleRootHex: root };
      }
      this.blobTransfers.touch(frame.documentId, match.merkleRootHex);
      pin = {
        hash: wantHash || null,
        payment: wantPayment || null,
        iv: wantIv || null,
        origin: match.expectedOrigins ? match.expectedOrigins[frame.blobIndex] || null : null
      };
    }
    const rowKey = `${frame.documentId}|${root}`;
    let row = this.pendingSealedBlobs[rowKey];
    if (row && row.total !== frame.blobTotal && !row.opened.size) {
      // Planted before the purchase: the proven total wins.
      this._dropSealedRow(rowKey);
      row = null;
    }
    if (row && pin && !row.pinned) {
      row.pinned = true;
      this._resizeSealedRow(row);
    }
    if (row) {
      if (row.total !== frame.blobTotal) {
        return { status: 'reject', error: 'per-blob frame blobTotal disagrees with the tree being assembled', documentId: frame.documentId, blobIndex: frame.blobIndex, merkleRootHex: root };
      }
      // No row-level origin lock: a per-blob plan buys blob i from one seller
      // and blob j from another under the same root. The row key binds the
      // root, held parts cannot be overwritten, and the final Merkle check
      // covers the whole tree; each part records its own origin instead.
      // Sellers of one tree share ciphertext and K_i, so an honest resend
      // carries the same payment hash and IV. Different ciphertext never
      // replaces a held part. The same ciphertext with another payment hash or
      // IV is kept as a bounded alternate (the first frame might be a peer's
      // poison, not the paid delivery); the key reveal opens whichever decrypts.
      let held = row.parts.get(frame.blobIndex);
      if (held && pin && !row.opened.has(frame.blobIndex)) {
        // Frames held from before the purchase pins existed may violate them
        // (any peer can send self-hashed junk under an advertised root); a
        // frame that satisfies the pins replaces them instead of bouncing off.
        const fits = (c) => (!pin.payment || c.paymentHashHex === pin.payment) && (!pin.iv || Document.sameIv(c.iv, pin.iv));
        const keep = pin.hash && held.blobHashHex !== pin.hash
          ? []
          : [held, ...(held.alternates || [])].filter(fits);
        if (!keep.length) {
          row.parts.delete(frame.blobIndex);
          held = null;
        } else if (keep.length !== 1 + (held.alternates || []).length) {
          const [first, ...rest] = keep;
          const next = {
            ciphertext: held.ciphertext,
            blobHashHex: held.blobHashHex,
            paymentHashHex: first.paymentHashHex,
            iv: first.iv,
            scheme: first.scheme,
            convergence: first.convergence || null,
            verified: !!first.verified,
            origin: first.origin,
            frame: first.frame
          };
          if (rest.length) next.alternates = rest;
          row.parts.set(frame.blobIndex, next);
          held = next;
        }
        this._resizeSealedRow(row);
      }
      if (held) {
        if (held.blobHashHex !== frame.blobHashHex) {
          return { status: 'reject', error: 'per-blob frame would overwrite a held blob with a different hash', documentId: frame.documentId, blobIndex: frame.blobIndex, merkleRootHex: root };
        }
        const candidates = [held, ...(held.alternates || [])];
        const known = candidates.some((c) => c.paymentHashHex === paymentHashHex && Document.sameIv(c.iv, obj.iv));
        if (!known && verified && held.verified) {
          // Two proofs for one index under one root cannot differ.
          return { status: 'reject', error: 'per-blob frame conflicts with a proven held blob', documentId: frame.documentId, blobIndex: frame.blobIndex, merkleRootHex: root };
        }
        if (!known) {
          const conflict = { status: 'reject', error: 'per-blob frame conflicts with a held blob (payment hash or iv)', documentId: frame.documentId, blobIndex: frame.blobIndex, merkleRootHex: root };
          if (row.opened.has(frame.blobIndex)) return conflict;
          held.alternates = held.alternates || [];
          if (held.alternates.length >= PEER_MAX_SEALED_BLOB_ALTERNATES) {
            // Only the seller this index was bought from may displace another
            // origin's alternate (covers offers that did not advertise an IV).
            const preferred = pin && pin.origin && originName && String(originName) === pin.origin;
            const victim = preferred ? held.alternates.findIndex((a) => a.origin !== pin.origin) : -1;
            if (victim < 0) return conflict;
            held.alternates.splice(victim, 1);
          }
          const altFrame = frameHex ? (Buffer.isBuffer(frameHex) ? Buffer.from(frameHex) : Buffer.from(String(frameHex), 'hex')) : null;
          const reserved = this._reserveSealedBytes(row, rowKey, originName, altFrame ? altFrame.length : 0);
          if (!reserved.ok) return Object.assign(reserved, { documentId: frame.documentId, blobIndex: frame.blobIndex, merkleRootHex: root });
          held.alternates.push({
            paymentHashHex,
            iv: String(obj.iv),
            scheme: obj.scheme || null,
            convergence: Peer._frameConvergence(obj),
            origin: originName ? String(originName) : null,
            frame: altFrame
          });
          row.updated = Date.now();
          const room = this._settleSealedRow(row, rowKey);
          if (!room.ok) return Object.assign(room, { documentId: frame.documentId, blobIndex: frame.blobIndex, merkleRootHex: root });
        }
        return {
          status: 'awaiting_key',
          sealed: true,
          perBlob: true,
          awaitingKey: true,
          duplicate: known,
          alternate: !known,
          documentId: frame.documentId,
          blobIndex: frame.blobIndex,
          received: row.parts.size,
          total: row.total,
          merkleRootHex: row.merkleRootHex,
          origin
        };
      }
    } else {
      if (!pin) this._limitUnpinnedSealedRows(originName, rowKey);
      row = {
        documentId: frame.documentId,
        total: frame.blobTotal,
        merkleRootHex: root,
        parts: new Map(),
        opened: new Map(),
        origin: origin || null,
        originName: originName ? String(originName) : null,
        pinned: !!pin,
        bytes: 0,
        originBytes: new Map(),
        created: Date.now(),
        updated: Date.now()
      };
      this.pendingSealedBlobs[rowKey] = row;
    }
    row.updated = Date.now();
    let frame64 = null;
    if (frameHex) frame64 = Buffer.isBuffer(frameHex) ? Buffer.from(frameHex) : Buffer.from(String(frameHex), 'hex');
    const reserved = this._reserveSealedBytes(row, rowKey, originName, frame.bytes.length + (frame64 ? frame64.length : 0));
    if (!reserved.ok) {
      if (!row.parts.size && !row.opened.size) this._dropSealedRow(rowKey);
      return Object.assign(reserved, { documentId: frame.documentId, blobIndex: frame.blobIndex, merkleRootHex: root });
    }
    row.parts.set(frame.blobIndex, {
      ciphertext: frame.bytes,
      blobHashHex: frame.blobHashHex,
      paymentHashHex,
      iv: String(obj.iv),
      scheme: obj.scheme || null,
      convergence: Peer._frameConvergence(obj),
      verified,
      origin: originName ? String(originName) : null,
      frame: frame64
    });
    const room = this._settleSealedRow(row, rowKey);
    if (!room.ok) return Object.assign(room, { documentId: frame.documentId, blobIndex: frame.blobIndex, merkleRootHex: root });
    this.emit('documentCiphertextReceived', {
      documentId: frame.documentId,
      blobIndex: frame.blobIndex,
      blobTotal: frame.blobTotal,
      buffer: frame.bytes,
      merkleRootHex: row.merkleRootHex,
      paymentHashHex,
      perBlob: true,
      verified: true,
      committed: verified,
      origin
    });
    return {
      status: 'awaiting_key',
      sealed: true,
      perBlob: true,
      awaitingKey: true,
      committed: verified,
      documentId: frame.documentId,
      blobIndex: frame.blobIndex,
      received: row.parts.size,
      total: row.total,
      merkleRootHex: row.merkleRootHex,
      origin
    };
  }

  /**
   * Find the sealed per-blob row for a document. Rows are keyed by
   * `documentId|merkleRootHex`; callers that know the root or the payment
   * hash of one part can disambiguate when two roots are in flight.
   * @param {string} documentId
   * @param {string} [merkleRootHex]
   * @param {string} [paymentHashHex] payment hash of the part at `blobIndex`
   * @param {number} [blobIndex]
   * @returns {Object|null}
   * @private
   */
  _sealedBlobRow (documentId, merkleRootHex = null, paymentHashHex = null, blobIndex = null) {
    const id = String(documentId || '').trim();
    if (!id) return null;
    const root = merkleRootHex ? String(merkleRootHex).toLowerCase() : null;
    if (root) return this.pendingSealedBlobs[`${id}|${root}`] || null;
    const ph = paymentHashHex ? String(paymentHashHex).toLowerCase() : null;
    const candidates = Object.values(this.pendingSealedBlobs).filter((r) => r && r.documentId === id);
    if (!candidates.length) return null;
    if (ph != null && Number.isFinite(Number(blobIndex))) {
      const hit = candidates.find((r) => {
        const p = r.parts.get(Number(blobIndex));
        return p && (p.paymentHashHex === ph || (p.alternates || []).some((a) => a.paymentHashHex === ph));
      });
      if (hit) return hit;
    }
    return candidates.length === 1 ? candidates[0] : null;
  }

  /** @private bytes held by one pending sealed row (ciphertext + retained frames) */
  static _sealedRowBytes (row) {
    let total = 0;
    for (const p of row.parts.values()) {
      total += (p.ciphertext ? p.ciphertext.length : 0) + (p.frame ? p.frame.length : 0);
      for (const a of p.alternates || []) total += a.frame ? a.frame.length : 0;
    }
    for (const o of row.opened.values()) total += o ? o.length : 0;
    return total;
  }

  /** @private global byte budget for `pendingSealedBlobs` */
  _pendingSealedBudget () {
    const budgetSetting = Number(this.settings.maxPendingSealedBytes);
    return Number.isFinite(budgetSetting) && budgetSetting > 0 ? budgetSetting : PEER_MAX_PENDING_SEALED_BYTES;
  }

  /**
   * Re-measure one row and move the running totals (`_pendingSealedBytes`,
   * and per part origin for unpinned rows) by the difference. Cost is one
   * row, not the whole map.
   * @param {Object} row
   * @private
   */
  _resizeSealedRow (row) {
    const bytes = Peer._sealedRowBytes(row);
    const byOrigin = new Map();
    if (!row.pinned) {
      const add = (name, n) => { if (n) byOrigin.set(name || '', (byOrigin.get(name || '') || 0) + n); };
      for (const [i, p] of row.parts) {
        add(p.origin, (p.ciphertext ? p.ciphertext.length : 0) + (p.frame ? p.frame.length : 0));
        for (const a of p.alternates || []) add(a.origin, a.frame ? a.frame.length : 0);
        const o = row.opened.get(i);
        if (o) add(p.origin, o.length);
      }
    }
    this._pendingSealedBytes += bytes - (row.bytes || 0);
    const shift = (name, n) => {
      const next = (this._pendingSealedOriginBytes.get(name) || 0) + n;
      if (next > 0) this._pendingSealedOriginBytes.set(name, next);
      else this._pendingSealedOriginBytes.delete(name);
    };
    for (const [name, n] of row.originBytes || []) shift(name, -n);
    for (const [name, n] of byOrigin) shift(name, n);
    row.bytes = bytes;
    row.originBytes = byOrigin;
  }

  /**
   * Remove a pending sealed row and release its bytes.
   * @param {string} key
   * @private
   */
  _dropSealedRow (key) {
    const row = this.pendingSealedBlobs[key];
    if (!row) return;
    this._pendingSealedBytes -= row.bytes || 0;
    for (const [name, n] of row.originBytes || []) {
      const next = (this._pendingSealedOriginBytes.get(name) || 0) - n;
      if (next > 0) this._pendingSealedOriginBytes.set(name, next);
      else this._pendingSealedOriginBytes.delete(name);
    }
    delete this.pendingSealedBlobs[key];
  }

  /**
   * Unpinned row keys started by `originName`, oldest first.
   * @param {string|null} originName
   * @param {string} [skip]
   * @returns {string[]}
   * @private
   */
  _unpinnedSealedRowsFrom (originName, skip = null) {
    const name = originName ? String(originName) : null;
    return Object.keys(this.pendingSealedBlobs)
      .filter((k) => {
        const r = this.pendingSealedBlobs[k];
        return k !== skip && r && !r.pinned && (r.originName || null) === name;
      })
      .sort((a, b) => (this.pendingSealedBlobs[a].updated || 0) - (this.pendingSealedBlobs[b].updated || 0));
  }

  /**
   * Per-origin row quota for unsolicited trees (`maxPendingSealedRowsPerOrigin`,
   * default `DocumentBlobTransferBook.MAX_PENDING_PER_ORIGIN`): a peer over it loses its
   * own oldest unsolicited row, never someone else's.
   * @param {string|null} originName
   * @param {string} rowKey row about to be created
   * @private
   */
  _limitUnpinnedSealedRows (originName, rowKey) {
    const setting = Number(this.settings.maxPendingSealedRowsPerOrigin);
    const limit = Number.isFinite(setting) && setting > 0 ? setting : DocumentBlobTransferBook.MAX_PENDING_PER_ORIGIN;
    const own = this._unpinnedSealedRowsFrom(originName, rowKey);
    for (let i = 0; i <= own.length - limit; i++) this._dropSealedRow(own[i]);
  }

  /**
   * Before holding `incoming` more bytes from `originName` in `row`: unsolicited
   * bytes count against a per-origin quota (`maxPendingSealedBytesPerOrigin`,
   * default a quarter of the default budget, at most the budget). Over it, the
   * origin's own older unsolicited rows go first; then the frame is refused.
   * @param {Object} row
   * @param {string} rowKey
   * @param {string|null} originName
   * @param {number} incoming
   * @returns {{ ok: boolean, status: (string|undefined), error: (string|undefined) }}
   * @private
   */
  _reserveSealedBytes (row, rowKey, originName, incoming) {
    const budget = this._pendingSealedBudget();
    if (incoming > budget) return { ok: false, status: 'reject', error: 'pending sealed-blob memory budget exceeded' };
    if (row.pinned) return { ok: true };
    const setting = Number(this.settings.maxPendingSealedBytesPerOrigin);
    const limit = Number.isFinite(setting) && setting > 0
      ? setting
      : Math.min(budget, Math.floor(PEER_MAX_PENDING_SEALED_BYTES / 4));
    const name = originName ? String(originName) : '';
    const used = () => this._pendingSealedOriginBytes.get(name) || 0;
    if (used() + incoming > limit) {
      for (const key of this._unpinnedSealedRowsFrom(originName, rowKey)) {
        if (used() + incoming <= limit) break;
        this._dropSealedRow(key);
      }
    }
    if (used() + incoming > limit) {
      return { ok: false, status: 'reject', error: 'pending sealed-blob memory budget exceeded for this peer' };
    }
    return { ok: true };
  }

  /**
   * After a row changed: update the running totals and enforce the global caps.
   * @param {Object} row
   * @param {string} rowKey
   * @returns {{ ok: boolean, status: (string|undefined), error: (string|undefined) }}
   * @private
   */
  _settleSealedRow (row, rowKey) {
    this._resizeSealedRow(row);
    this._capPendingSealedBlobs();
    if (!this.pendingSealedBlobs[rowKey]) {
      return { ok: false, status: 'reject', error: 'pending sealed-blob memory budget exceeded' };
    }
    return { ok: true };
  }

  /**
   * True while a purchase expectation still backs a pinned row.
   * @param {Object} row
   * @returns {boolean}
   * @private
   */
  _sealedRowExpected (row) {
    if (!this.blobTransfers || typeof this.blobTransfers.expectedFor !== 'function') return false;
    return this.blobTransfers.expectedFor(row.documentId)
      .some((e) => !e.merkleRootHex || e.merkleRootHex === row.merkleRootHex);
  }

  /**
   * Bound per-blob sealed trees held in memory. Unsolicited rows expire
   * `pendingSealedTtlMs` after their first frame; a pinned row (a purchase
   * expectation matched it) lives as long as that expectation. Then rows are
   * evicted — unpinned before pinned, oldest-updated first — until both the
   * row cap (`maxPendingSealedDeliveries`) and the byte budget
   * (`maxPendingSealedBytes`, tracked as a running total) hold.
   * @private
   */
  _capPendingSealedBlobs () {
    const max = Number(this.settings.maxPendingSealedDeliveries);
    const cap = Number.isFinite(max) && max > 0 ? max : PEER_MAX_PENDING_SEALED_DELIVERIES;
    const budget = this._pendingSealedBudget();
    const ttlSetting = Number(this.settings.pendingSealedTtlMs);
    const ttl = Number.isFinite(ttlSetting) && ttlSetting > 0 ? ttlSetting : PEER_PENDING_SEALED_TTL_MS;
    const now = Date.now();
    for (const [key, row] of Object.entries(this.pendingSealedBlobs)) {
      if (!row) {
        delete this.pendingSealedBlobs[key];
        continue;
      }
      if (now - (row.created || row.updated || 0) <= ttl) continue;
      if (row.pinned && this._sealedRowExpected(row)) continue;
      this._dropSealedRow(key);
    }
    let count = Object.keys(this.pendingSealedBlobs).length;
    if (count <= cap && this._pendingSealedBytes <= budget) return;
    const rank = (r) => (r.pinned ? 1 : 0);
    const keys = Object.keys(this.pendingSealedBlobs).sort((a, b) => {
      const x = this.pendingSealedBlobs[a];
      const y = this.pendingSealedBlobs[b];
      return (rank(x) - rank(y)) || ((x.updated || 0) - (y.updated || 0));
    });
    for (const key of keys) {
      if (count <= cap && this._pendingSealedBytes <= budget) break;
      this._dropSealedRow(key);
      count--;
    }
  }

  /** @private `convergence` claimed by a frame: 'public' | 'scoped' | null */
  static _frameConvergence (obj) {
    const c = obj && obj.convergence;
    return c === 'public' || c === 'scoped' ? c : null;
  }

  /**
   * Whether an opened key is the one the plaintext derives. Unauthenticated
   * frame fields only choose whether to check, so this reports rather than
   * refuses: GCM under the paid key and the Merkle root already bind the bytes.
   * @param {Object} candidate held part (scheme, iv, convergence)
   * @param {Buffer} plaintext
   * @param {string|null} keyHex
   * @returns {boolean|null} null when it cannot be checked
   * @private
   */
  _convergentDerivation (candidate, plaintext, keyHex) {
    if (!candidate || candidate.scheme !== CONVERGENT_SCHEME || !keyHex) return null;
    const scoped = candidate.convergence === 'scoped';
    const secret = this.settings.convergenceSecret;
    if (scoped && (secret == null || secret === '')) return null;
    return isConvergentKey(plaintext, keyHex, { iv: candidate.iv, secret: scoped ? secret : null });
  }

  /**
   * Keep an opened convergent chunk (ciphertext + key) so another document
   * sharing it opens without buying it again. Oldest go first past
   * `maxHeldChunkBytes` (0 keeps none).
   * @param {Object} chunk `{ blobHashHex, paymentHashHex, keyHex, iv, scheme, convergence, ciphertext }`
   * @private
   */
  _rememberHeldChunk (chunk) {
    const setting = Number(this.settings.maxHeldChunkBytes);
    const budget = Number.isFinite(setting) && setting >= 0 ? setting : PEER_MAX_HELD_CHUNK_BYTES;
    const size = chunk.ciphertext ? chunk.ciphertext.length : 0;
    if (!budget || !size || size > budget) return;
    const key = `${chunk.blobHashHex}|${chunk.paymentHashHex}`;
    const prior = this._heldChunks.get(key);
    if (prior) {
      this._heldChunks.delete(key);
      this._heldChunkBytes -= prior.ciphertext.length;
    }
    while (this._heldChunks.size && this._heldChunkBytes + size > budget) {
      const [oldest, value] = this._heldChunks.entries().next().value;
      this._heldChunks.delete(oldest);
      this._heldChunkBytes -= value.ciphertext.length;
    }
    this._heldChunks.set(key, {
      keyHex: chunk.keyHex,
      iv: String(chunk.iv),
      scheme: chunk.scheme || null,
      convergence: chunk.convergence || null,
      ciphertext: chunk.ciphertext
    });
    this._heldChunkBytes += size;
  }

  /**
   * A chunk this Peer can open without buying it: one opened before (any
   * document), or one of a sealed document it sells. Chunk identity is the
   * blob hash plus the payment hash (`SHA256(K_i)`), so a match is the same
   * ciphertext under the same key.
   * @param {string} blobHashHex
   * @param {string} paymentHashHex
   * @returns {{ keyHex: string, iv: string, scheme: (string|null), convergence: (string|null), ciphertext: Buffer }|null}
   */
  /**
   * Keep the leaf record of a convergent tree just received in full, so it
   * can be seeded. Random-key trees are not kept: their chunks are not held.
   * @private
   * @returns {boolean} kept
   */
  _rememberSeedRecord (documentId, row, leaves, plain, size) {
    const parts = leaves.map((l) => row.parts.get(l.index));
    if (!parts.length || !parts.every((p) => p && p.scheme === CONVERGENT_SCHEME)) return false;
    const record = {
      type: 'Document',
      documentId,
      merkleRootHex: row.merkleRootHex,
      blobTotal: row.total,
      chunkBytes: Math.max(...parts.map((p) => p.ciphertext.length)),
      sealed: true,
      convergence: parts.some((p) => p.convergence === 'scoped') ? 'scoped' : 'public',
      size,
      blobs: parts.map((p, i) => ({
        index: i,
        total: row.total,
        blobHashHex: p.blobHashHex,
        paymentHashHex: p.paymentHashHex,
        size: p.ciphertext.length,
        plaintextSize: plain[i].length,
        iv: p.iv,
        scheme: p.scheme
      }))
    };
    this._seedRecords.delete(documentId);
    this._seedRecords.set(documentId, record);
    while (this._seedRecords.size > 256) this._seedRecords.delete(this._seedRecords.keys().next().value);
    return true;
  }

  /**
   * @param {string} documentId
   * @returns {boolean} a convergent tree received here that {@link Peer#seedDocument} may sell
   */
  seedableDocument (documentId) {
    return this._seedRecords.has(String(documentId || '').trim());
  }

  /**
   * Seed after download: sell a convergent tree this Peer received, as the
   * same tree (same root, chunks, and keys), rebuilt from the held chunks —
   * nothing is resealed. Fails when a chunk was evicted from the held store
   * (`maxHeldChunkBytes`); reseal the plaintext then, which gives the same
   * tree for public convergence. Seller terms as {@link Peer#publishSealedDocument}.
   * @param {string} documentId
   * @param {Object} [opts] `{ rateSats, creditRateSats, creditLimitSats, convergenceSecret }`
   * @returns {{ ok: boolean, documentId: (string|undefined), error: (string|undefined) }}
   */
  seedDocument (documentId, opts = {}) {
    const id = String(documentId || '').trim();
    const record = this._seedRecords.get(id);
    if (!record) return { ok: false, error: 'no convergent document received under that id' };
    const doc = Document.fromRecord(record);
    if (opts.convergenceSecret != null) doc.setConvergenceSecret(opts.convergenceSecret);
    for (const b of record.blobs) {
      const held = this.heldChunk(b.blobHashHex, b.paymentHashHex);
      if (!held) return { ok: false, error: `blob ${b.index} is no longer held (raise maxHeldChunkBytes, or reseal the plaintext)` };
      if (!doc.acceptBytes(b.index, held.ciphertext) || !doc.setKey(b.index, held.keyHex)) {
        return { ok: false, error: `held blob ${b.index} does not match the tree` };
      }
    }
    const out = this.publishSealedDocument(doc, Object.assign({}, opts, { documentId: id }));
    if (out.ok) this.emit('documentSeeded', { documentId: out.documentId, merkleRootHex: doc.merkleRootHex, blobTotal: doc.blobTotal });
    return out;
  }

  heldChunk (blobHashHex, paymentHashHex) {
    const bh = String(blobHashHex || '').toLowerCase();
    const ph = String(paymentHashHex || '').toLowerCase();
    if (!/^[0-9a-f]{64}$/.test(bh) || !/^[0-9a-f]{64}$/.test(ph)) return null;
    const key = `${bh}|${ph}`;
    const own = this._heldChunks.get(key);
    if (own) {
      this._heldChunks.delete(key);
      this._heldChunks.set(key, own);
      return Object.assign({}, own);
    }
    const hit = this._sealedBlobByPaymentHash.get(ph);
    const doc = hit ? this._getSealedBlobDocument(hit.documentId) : null;
    const leaf = doc ? doc.blob(hit.blobIndex) : null;
    if (!leaf || leaf.blobHashHex !== bh) return null;
    const keyHex = doc.keyFor(hit.blobIndex);
    const ciphertext = doc.bytesFor(hit.blobIndex);
    if (!keyHex || !ciphertext) return null;
    return { keyHex, iv: leaf.iv, scheme: leaf.scheme || null, convergence: doc.convergence || null, ciphertext };
  }

  /**
   * Fill one blob of a sealed tree from a held chunk (see {@link Peer#heldChunk})
   * and open it, as a paid key reveal would. The offer's leaf names the chunk;
   * the IV must match, an inclusion proof is checked when given, and the whole tree is
   * still checked against its root once every blob is open.
   * @param {Object} opts
   * @param {string} opts.documentId
   * @param {string} opts.merkleRootHex
   * @param {number} opts.blobTotal
   * @param {number} opts.blobIndex
   * @param {string} opts.blobHashHex
   * @param {string} opts.paymentHashHex
   * @param {string} [opts.iv] advertised IV
   * @param {string[]} [opts.proof] inclusion proof
   * @returns {Object} same shape as the key-reveal handler
   */
  adoptHeldChunk (opts = {}) {
    const documentId = String(opts.documentId || '').trim();
    const root = String(opts.merkleRootHex || '').toLowerCase();
    const blobIndex = Number(opts.blobIndex);
    const blobTotal = Number(opts.blobTotal);
    const blobHashHex = String(opts.blobHashHex || '').toLowerCase();
    const paymentHashHex = String(opts.paymentHashHex || '').toLowerCase();
    const fail = (error) => ({ ok: false, error, documentId, blobIndex });
    if (!documentId || !isWireDocumentId(documentId)) return fail('documentId required');
    if (!/^[0-9a-f]{64}$/.test(root)) return fail('merkleRootHex required');
    const maxParts = Math.max(1, Number(this.settings.maxSealedBlobParts) || PEER_MAX_SEALED_BLOB_PARTS);
    if (!Number.isInteger(blobTotal) || blobTotal < 1 || blobTotal > maxParts || !Number.isInteger(blobIndex) || blobIndex < 0 || blobIndex >= blobTotal) {
      return fail('blobTotal/blobIndex out of range');
    }
    const held = this.heldChunk(blobHashHex, paymentHashHex);
    if (!held) return fail('chunk not held');
    if (opts.iv && !Document.sameIv(opts.iv, held.iv)) return fail('held chunk iv differs from the offer');
    let verified = false;
    if (Array.isArray(opts.proof)) {
      verified = Document.verifyInclusion({ merkleRootHex: root, blobTotal, blobIndex, blobHashHex, paymentHashHex, iv: held.iv, proof: opts.proof });
      if (!verified) return fail('held chunk is not committed by the document root (inclusion proof)');
    }
    const rowKey = `${documentId}|${root}`;
    let row = this.pendingSealedBlobs[rowKey];
    if (row && row.total !== blobTotal) return fail('blobTotal disagrees with the tree being assembled');
    if (row && row.opened.has(blobIndex)) {
      const part = row.parts.get(blobIndex);
      if (part && part.blobHashHex === blobHashHex) return { ok: true, already: true, documentId, blobIndex, opened: row.opened.size, total: row.total };
      return fail('a different blob is already open at that index');
    }
    if (!row) {
      row = {
        documentId,
        total: blobTotal,
        merkleRootHex: root,
        parts: new Map(),
        opened: new Map(),
        origin: null,
        originName: null,
        pinned: true,
        bytes: 0,
        originBytes: new Map(),
        created: Date.now(),
        updated: Date.now()
      };
      this.pendingSealedBlobs[rowKey] = row;
    } else if (!row.pinned) {
      row.pinned = true;
      this._resizeSealedRow(row);
    }
    const reserved = this._reserveSealedBytes(row, rowKey, null, held.ciphertext.length);
    if (!reserved.ok) {
      if (!row.parts.size && !row.opened.size) this._dropSealedRow(rowKey);
      return fail(reserved.error);
    }
    row.parts.set(blobIndex, {
      ciphertext: held.ciphertext,
      blobHashHex,
      paymentHashHex,
      iv: held.iv,
      scheme: held.scheme,
      convergence: held.convergence,
      verified,
      origin: null,
      frame: null
    });
    row.updated = Date.now();
    const room = this._settleSealedRow(row, rowKey);
    if (!room.ok) return fail(room.error);
    return this._handleSealedBlobKeyReveal({
      documentId,
      blobIndex,
      keyHex: held.keyHex,
      paymentHashHex,
      merkleRootHex: root,
      iv: held.iv,
      held: true
    }, null);
  }

  /**
   * Which held sealed blob a payment hash belongs to. Lets the buyer map a
   * channel `ChannelHtlcFulfill` preimage back onto the blob it unlocks.
   * @param {string} paymentHashHex
   * @returns {{ documentId: string, merkleRootHex: string, blobIndex: number, blobHashHex: string, frameHex: (string|null) }|null}
   */
  sealedBlobKeyForPaymentHash (paymentHashHex) {
    const ph = String(paymentHashHex || '').toLowerCase();
    if (!/^[0-9a-f]{64}$/.test(ph)) return null;
    for (const row of Object.values(this.pendingSealedBlobs)) {
      if (!row || !row.parts) continue;
      for (const [index, part] of row.parts) {
        const hit = [part, ...(part.alternates || [])].find((c) => c.paymentHashHex === ph);
        if (hit) {
          return { documentId: row.documentId, merkleRootHex: row.merkleRootHex, blobIndex: index, blobHashHex: part.blobHashHex, frameHex: hit.frame ? hit.frame.toString('hex') : null };
        }
      }
    }
    return null;
  }

  /**
   * Open a held sealed blob with an HTLC preimage learned out of band
   * (seller-fulfils channel rail). For a static payment hash the preimage
   * **is** `K_i`; for a per-buyer `DocumentBlobQuote` it is `s`, which
   * unwraps `K_i` from the quote (a quote that does not unwrap to the
   * committed key hash emits `documentBlobQuoteFraud` with the signed quote
   * frame). Same verification as a wire `DocumentContentKeyReveal`:
   * SHA256(K_i) must equal the part's payment hash and GCM must authenticate.
   * @param {Object} opts
   * @param {string} [opts.documentId]
   * @param {string} opts.keyHex 32-byte preimage (hex)
   * @param {number} [opts.blobIndex] resolved from `paymentHashHex` when omitted
   * @param {string} [opts.paymentHashHex] SHA256(key); defaults to the hash of `keyHex`
   * @param {string} [opts.merkleRootHex] disambiguates when two roots are pending
   * @returns {Object} same shape as the key-reveal handler
   */
  openSealedBlobWithKey (opts = {}) {
    let keyHex = String(opts.keyHex || '').toLowerCase();
    if (!/^[0-9a-f]{64}$/.test(keyHex)) return { ok: false, error: 'keyHex must be 32 bytes hex' };
    let paymentHashHex = opts.paymentHashHex
      ? String(opts.paymentHashHex).toLowerCase()
      : crypto.createHash('sha256').update(Buffer.from(keyHex, 'hex')).digest('hex');
    let blobIndex = opts.blobIndex;
    let merkleRootHex = opts.merkleRootHex || null;
    let documentId = opts.documentId;
    const preimageHex = keyHex;
    const quoted = this._receivedBlobQuotes.get(paymentHashHex);
    if (quoted) {
      const q = quoted.quote;
      const row = this._sealedBlobRow(q.documentId, q.merkleRootHex);
      const part = row ? row.parts.get(Number(q.blobIndex)) : null;
      const out = checkBlobQuote({ quote: q, preimageHex: keyHex, keyHashHex: part && part.verified ? part.paymentHashHex : null });
      if (!out.ok) {
        if (out.fraud) {
          this.emit('documentBlobQuoteFraud', {
            quote: Object.assign({}, q),
            preimageHex: keyHex,
            quoteFrameHex: quoted.frame ? quoted.frame.toString('hex') : null,
            origin: quoted.origin,
            error: out.error
          });
        }
        return { ok: false, error: out.error, fraud: !!out.fraud, documentId: q.documentId, blobIndex: Number(q.blobIndex) };
      }
      keyHex = out.keyHex;
      paymentHashHex = String(q.keyHashHex).toLowerCase();
      if (!Number.isFinite(Number(blobIndex))) blobIndex = Number(q.blobIndex);
      if (!merkleRootHex) merkleRootHex = q.merkleRootHex || null;
      if (!documentId) documentId = q.documentId;
    }
    if (!Number.isFinite(Number(blobIndex))) {
      const located = this.sealedBlobKeyForPaymentHash(paymentHashHex);
      if (!located) return { ok: false, error: 'no held blob for that payment hash', documentId: opts.documentId || null };
      blobIndex = located.blobIndex;
      if (!merkleRootHex) merkleRootHex = located.merkleRootHex;
      if (!documentId) documentId = located.documentId;
    }
    const result = this._handleSealedBlobKeyReveal({
      documentId,
      blobIndex: Number(blobIndex),
      keyHex,
      paymentHashHex,
      merkleRootHex,
      preimageHex
    }, opts.origin || null);
    if (quoted && result && result.ok) this._receivedBlobQuotes.delete(quoted.quote.paymentHashHex.toLowerCase());
    return result;
  }

  /**
   * Open one blob of a per-blob sealed tree with its revealed key; emits the
   * whole document once every blob is open and the Tree root checks out.
   * @param {Object} reveal `DocumentContentKeyReveal` object with `blobIndex`
   * @param {Object} [origin]
   * @returns {Object}
   * @private
   */
  _handleSealedBlobKeyReveal (reveal, origin = null) {
    const documentId = String((reveal && reveal.documentId) || '').trim();
    const blobIndex = Number(reveal.blobIndex);
    const row = documentId ? this._sealedBlobRow(documentId, reveal.merkleRootHex, reveal.paymentHashHex, blobIndex) : null;
    const part = row ? row.parts.get(blobIndex) : null;
    if (!row || !part) {
      return { ok: false, error: 'no pending sealed blob', documentId, blobIndex };
    }
    if (reveal.blobHashHex && String(reveal.blobHashHex).toLowerCase() !== part.blobHashHex) {
      return { ok: false, error: 'reveal blobHashHex mismatch', documentId, blobIndex };
    }
    const revealHash = String(reveal.paymentHashHex || '').toLowerCase();
    const candidates = [part, ...(part.alternates || [])].filter((c) => c.paymentHashHex === revealHash);
    let opened = null;
    let chosen = null;
    for (const candidate of candidates) {
      const attempt = openSealedDelivery({
        keyHex: reveal.keyHex,
        paymentHashHex: revealHash,
        iv: reveal.iv || candidate.iv,
        // Not the frame's own claim: it is unauthenticated and would let a
        // peer veto the paid open. GCM under the paid key plus the Merkle
        // root already bind the plaintext.
        plaintextSha256: reveal.plaintextSha256 || null
      }, part.ciphertext);
      if (attempt.ok) {
        opened = attempt;
        chosen = candidate;
        break;
      }
      if (!opened) opened = attempt;
    }
    if (!chosen) {
      const error = (opened && opened.error) || (candidates.length ? 'open failed' : 'reveal paymentHashHex does not match blob');
      this.emit('documentBlobRejected', { documentId, blobIndex, error, origin });
      return { ok: false, error, documentId, blobIndex };
    }
    // Keep the frame that actually opened (a `wrong-bytes` proof cites it).
    const base = Object.assign({}, part);
    delete base.alternates;
    row.parts.set(blobIndex, chosen === part ? base : Object.assign(base, {
      paymentHashHex: chosen.paymentHashHex,
      iv: chosen.iv,
      scheme: chosen.scheme,
      origin: chosen.origin,
      frame: chosen.frame
    }));
    row.opened.set(blobIndex, opened.plaintext);
    row.updated = Date.now();
    this._resizeSealedRow(row);
    const keyHex = reveal.keyHex ? String(reveal.keyHex).toLowerCase() : null;
    const derived = this._convergentDerivation(chosen, opened.plaintext, keyHex);
    if (chosen.scheme === CONVERGENT_SCHEME && keyHex) {
      this._rememberHeldChunk({
        blobHashHex: part.blobHashHex,
        paymentHashHex: chosen.paymentHashHex,
        keyHex,
        iv: chosen.iv,
        scheme: chosen.scheme,
        convergence: chosen.convergence || null,
        ciphertext: part.ciphertext
      });
    }
    this.emit('documentBlobOpened', {
      documentId,
      blobIndex,
      blobTotal: row.total,
      buffer: opened.plaintext,
      opened: row.opened.size,
      // For a static hash K_i is the payment preimage (paymentHash =
      // SHA256(K_i)); for a per-buyer quote it is `s` (`preimageHex`).
      keyHex,
      preimageHex: reveal.preimageHex ? String(reveal.preimageHex).toLowerCase() : keyHex,
      paymentHashHex: chosen.paymentHashHex || null,
      blobHashHex: part.blobHashHex,
      // true / false when the key could be checked against the content
      // (convergent scheme, and the scope secret when scoped); null otherwise.
      derived,
      held: reveal.held === true,
      origin: origin || row.origin
    });
    if (row.opened.size < row.total) {
      return { ok: true, documentId, blobIndex, opened: row.opened.size, total: row.total, complete: false };
    }
    const leaves = [];
    const plain = [];
    for (let i = 0; i < row.total; i++) {
      const p = row.parts.get(i);
      const o = row.opened.get(i);
      if (!p || !o) return { ok: true, documentId, blobIndex, complete: false };
      leaves.push({ index: i, blobHashHex: p.blobHashHex, paymentHashHex: p.paymentHashHex, iv: p.iv });
      plain.push(o);
    }
    if (row.merkleRootHex) {
      const check = Document.verifyOfferLeaves({
        merkleRootHex: row.merkleRootHex,
        blobTotal: row.total,
        blobs: leaves
      });
      if (!check.ok) {
        this.emit('documentBlobRejected', { documentId, error: 'merkle root mismatch', origin });
        return { ok: false, error: 'merkle root mismatch', documentId };
      }
    }
    this._dropSealedRow(`${documentId}|${row.merkleRootHex}`);
    const buffer = Buffer.concat(plain);
    this._storeReceivedDocument(documentId, buffer);
    const seedable = this._rememberSeedRecord(documentId, row, leaves, plain, buffer.length);
    const ev = {
      documentId,
      buffer,
      merkleRootHex: row.merkleRootHex,
      verified: true,
      sealed: true,
      perBlob: true,
      opened: true,
      seedable,
      origin: origin || row.origin
    };
    this.emit('documentReceived', ev);
    this.emit('documentOpened', ev);
    return { ok: true, documentId, blobIndex, complete: true, buffer };
  }

  /**
   * Verify / accumulate an inbound `P2P_FILE_SEND` against the DocumentBlobIndex rules.
   * Sealed frames store ciphertext until {@link KEY_REVEAL_TYPE}.
   * @param {Message|Object} message
   * @param {Object} origin
   * @param {string} [origin.name]
   * @param {Message} [wireMessage] raw signed AMP frame (kept per sealed blob for fraud proofs)
   * @returns {Object}
   */
  _ingestP2pFileSend (message, origin, wireMessage = null) {
    // Typed wire → Generic dispatch uses `{ type, object }`; raw Message has `.data`.
    let obj = null;
    if (message && message.object && typeof message.object === 'object' && !Array.isArray(message.object)) {
      obj = message.object;
    } else if (message && message.data != null) {
      const raw = messageDataToString(message.data);
      const pr = tryParseWireJsonBody(raw);
      if (pr.ok && pr.value && typeof pr.value === 'object') obj = pr.value;
    } else if (message && typeof message === 'object' && (message.name || message.body)) {
      obj = message;
    }
    if (!obj) {
      return { status: 'reject', error: 'invalid P2P_FILE_SEND JSON' };
    }
    if (obj.sealed && obj.perBlob === true) {
      let frameHex = null;
      try {
        const src = wireMessage || message;
        // Proof material only; `FraudProof` re-verifies the author signature itself.
        if (src && typeof src.toBuffer === 'function') frameHex = src.toBuffer().toString('hex');
      } catch (_) { /* synthetic frame — no proof material */ }
      return this._ingestSealedBlobFrame(obj, origin, frameHex);
    }
    const frame = DocumentBlobTransferBook.parseFrame(obj);
    const originName = origin && typeof origin === 'object' ? (origin.name || origin.address || origin.id || null) : (origin || null);
    const result = this.blobTransfers.ingest(frame, { origin: originName });
    if (result.status === 'complete' && result.buffer && result.documentId) {
      const sealed = !!(obj.sealed || (frame && !frame.unindexed && obj.paymentHashHex && obj.iv));
      if (sealed) {
        // No frame-supplied plaintextSha256: it is unauthenticated (a peer
        // could veto the paid open); the key reveal may carry one.
        this.pendingSealedDeliveries[result.documentId] = {
          ciphertext: result.buffer,
          merkleRootHex: result.merkleRootHex,
          paymentHashHex: obj.paymentHashHex || null,
          iv: obj.iv || null,
          scheme: obj.scheme || null,
          origin: origin || null,
          updated: Date.now()
        };
        this._capPendingSealedDeliveries();
        this.emit('documentCiphertextReceived', {
          documentId: result.documentId,
          buffer: result.buffer,
          merkleRootHex: result.merkleRootHex,
          paymentHashHex: obj.paymentHashHex || null,
          verified: true,
          origin
        });
        return Object.assign({ origin, sealed: true, awaitingKey: true }, result, {
          // Do not treat ciphertext as the final document.
          status: 'awaiting_key',
          buffer: null
        });
      }
      this._storeReceivedDocument(result.documentId, result.buffer, { overwrite: false });
    }
    return Object.assign({ origin }, result);
  }

  /**
   * Apply a content-key reveal to a pending sealed delivery.
   * @param {Object} reveal
   * @param {Object} [origin]
   * @param {string} [origin.name]
   * @returns {Object}
   */
  _handleDocumentContentKeyReveal (reveal, origin = null) {
    const documentId = String((reveal && reveal.documentId) || '').trim();
    if (reveal && reveal.blobIndex != null && documentId && this._sealedBlobRow(documentId, reveal.merkleRootHex, reveal.paymentHashHex, Number(reveal.blobIndex))) {
      return this._handleSealedBlobKeyReveal(reveal, origin);
    }
    const pending = documentId ? this.pendingSealedDeliveries[documentId] : null;
    if (!pending) {
      return { ok: false, error: 'no pending sealed delivery', documentId };
    }
    const opened = openSealedDelivery({
      keyHex: reveal.keyHex,
      paymentHashHex: reveal.paymentHashHex || pending.paymentHashHex,
      iv: reveal.iv || pending.iv,
      plaintextSha256: reveal.plaintextSha256 || null
    }, pending.ciphertext);
    if (!opened.ok) {
      this.emit('documentBlobRejected', {
        documentId,
        error: opened.error || 'open failed',
        origin
      });
      return { ok: false, error: opened.error, documentId };
    }
    delete this.pendingSealedDeliveries[documentId];
    this._storeReceivedDocument(documentId, opened.plaintext);
    const ev = {
      documentId,
      buffer: opened.plaintext,
      merkleRootHex: pending.merkleRootHex,
      verified: true,
      sealed: true,
      opened: true,
      origin: origin || pending.origin
    };
    this.emit('documentReceived', ev);
    this.emit('documentOpened', ev);
    return { ok: true, documentId, buffer: opened.plaintext };
  }

  /**
   * Open a pending sealed delivery using an HTLC claim preimage (on-chain witness).
   * @param {string} documentId
   * @param {string} preimageHex
   * @returns {{ok: boolean, error: (string|undefined), buffer: (Buffer|undefined)}}
   */
  openSealedDeliveryWithPreimage (documentId, preimageHex) {
    const id = String(documentId || '').trim();
    const pending = id ? this.pendingSealedDeliveries[id] : null;
    if (!pending) return { ok: false, error: 'no pending sealed delivery', documentId: id };
    const opened = openWithClaimPreimage({
      ciphertext: pending.ciphertext,
      preimageHex,
      paymentHashHex: pending.paymentHashHex,
      iv: pending.iv
    });
    if (!opened.ok) {
      this.emit('documentBlobRejected', {
        documentId: id,
        error: opened.error || 'open with preimage failed'
      });
      return { ok: false, error: opened.error, documentId: id };
    }
    delete this.pendingSealedDeliveries[id];
    this._storeReceivedDocument(id, opened.plaintext);
    const ev = {
      documentId: id,
      buffer: opened.plaintext,
      merkleRootHex: pending.merkleRootHex,
      verified: true,
      sealed: true,
      opened: true,
      fromClaim: true,
      origin: pending.origin
    };
    this.emit('documentReceived', ev);
    this.emit('documentOpened', ev);
    return { ok: true, documentId: id, buffer: opened.plaintext };
  }

  /**
   * Public helper: push document bytes to a peer (same wire path as {@link Peer#_handleDocumentRequestWire} fulfillment).
   * @param {string} documentId
   * @param {string} peerAddress
   * @param {Object} [opts]
   * @param {number} [opts.blobIndex]
   * @param {boolean} [opts.revealKey]
   * @returns {boolean}
   */
  sendDocumentFileToPeer (documentId, peerAddress, opts = {}) {
    const resolved = this._resolveToAddress(peerAddress) || peerAddress;
    return this._sendP2pFileSendToPeer(documentId, resolved, opts);
  }

  /**
   * Ask a connected peer for their document catalog (`kind: 'documents'`) or L1 offers (`offerBtc`).
   * @param {string} peerAddress connection key, Fabric id, or host:port
   * @param {Object} [opts]
   * @param {boolean} [opts.offerBtc=false]
   * @param {string} [opts.kind='documents']
   * @param {number} [opts.maxSats]
   * @param {string} [opts.blobHashHex] chunk selector: only this blob
   * @param {string} [opts.merkleRootHex] tree selector: only this document tree
   * @returns {boolean}
   */
  requestPeerInventory (peerAddress, opts = {}) {
    const resolved = this._resolveToAddress(peerAddress) || peerAddress;
    const conn = resolved && this.connections[resolved];
    if (!conn || !conn._writeFabric) return false;
    const object = {};
    if (opts.offerBtc === true) {
      object.offerBtc = true;
      if (opts.maxSats != null && Number.isFinite(Number(opts.maxSats))) {
        object.maxSats = Number(opts.maxSats);
      }
      if (opts.buyerRefundPublicKey) {
        object.buyerRefundPublicKey = String(opts.buyerRefundPublicKey);
      }
      if (opts.blobHashHex && /^[0-9a-f]{64}$/i.test(String(opts.blobHashHex))) {
        object.blobHashHex = String(opts.blobHashHex).toLowerCase();
      }
      if (opts.merkleRootHex && /^[0-9a-f]{64}$/i.test(String(opts.merkleRootHex))) {
        object.merkleRootHex = String(opts.merkleRootHex).toLowerCase();
      }
    } else {
      object.kind = String(opts.kind || 'documents');
      object.created = Date.now();
    }
    const m = Message.fromVector(['P2P_INVENTORY_REQUEST', JSON.stringify(object)]);
    m.signWithKey(this.key);
    // Local telemetry: time the round trip for the offer book (never gossiped).
    if (!this._inventoryRequestedAt) this._inventoryRequestedAt = {};
    this._inventoryRequestedAt[resolved] = Date.now();
    conn._writeFabric(m.toBuffer());
    return true;
  }

  /**
   * Send a signed `DocumentRequest` to one peer (or broadcast when peerAddress is omitted).
   * @param {string} documentId
   * @param {string} [peerAddress]
   * @param {object} [opts]
   * @param {number} [opts.maxSats]
   * @param {number} [opts.relayHop]
   * @param {number} [opts.blobIndex]
   * @param {number} [opts.blobTotal]
   * @param {string} [opts.contentHashHex]
   * @param {boolean} [opts.credit] Ask for the blob key on credit (pay after
   * verify with a channel transfer naming `creditRef`).
   * @param {string} [opts.creditRef]
   * @returns {boolean}
   */
  requestDocument (documentId, peerAddress = null, opts = {}) {
    if (!documentId) return false;
    if (!isWireDocumentId(documentId)) {
      this.emit('warning', `[FABRIC:PEER] requestDocument: document id longer than ${MAX_DOCUMENT_ID_LENGTH} characters`);
      return false;
    }

    const body = { document: documentId };
    if (opts.maxSats != null && Number.isFinite(Number(opts.maxSats))) {
      body.maxSats = Math.round(Number(opts.maxSats));
      body.relayHop = opts.relayHop != null
        ? Math.round(Number(opts.relayHop))
        : Math.round(Number(this.settings.documentRelayMaxHops) || 4);
      body.routeId = crypto.randomBytes(8).toString('hex');
    }
    if (opts.blobIndex != null) body.blobIndex = Number(opts.blobIndex);
    if (opts.blobTotal != null) body.blobTotal = Number(opts.blobTotal);
    if (opts.quote === true) body.quote = true;
    if (opts.credit === true && opts.creditRef) {
      body.credit = true;
      body.creditRef = String(opts.creditRef).slice(0, 256);
    }
    {
      const hash = contentHashHexFromObject(opts) || contentHashHexFromObject({ contentHashHex: opts.contentHashHex });
      if (hash) body.contentHashHex = hash;
    }

    const msg = Message.fromVector(['DocumentRequest', JSON.stringify(body)]);
    msg.signWithKey(this.key);
    const buf = msg.toBuffer();
    if (peerAddress) {
      const resolved = this._resolveToAddress(peerAddress) || peerAddress;
      const conn = resolved && this.connections[resolved];
      if (!conn || !conn._writeFabric) return false;
      conn._writeFabric(buf);
      return true;
    }
    this.broadcast(buf);
    return true;
  }

  /**
   * @param {object} item
   * @param {object} req inventory request object
   * @param {string} contentHashHex
   * @param {number} amountSats
   * @returns {object|null}
   */
  _attachHtlcOfferToItem (item, req, contentHashHex, amountSats) {
    const buyerHex = req.buyerRefundPublicKey || req.buyerRefundPubkey;
    if (!buyerHex || !/^[0-9a-fA-F]{66}$/.test(String(buyerHex))) return null;
    let sellerCompressed = null;
    try {
      if (this.key && this.key.public && typeof this.key.public.encodeCompressed === 'function') {
        sellerCompressed = Buffer.from(this.key.public.encodeCompressed('hex'), 'hex');
      }
    } catch (_) { /* ignore */ }
    if (!sellerCompressed) return null;
    const lock = Number(this.settings.inventoryHtlcLocktimeHeight);
    if (!Number.isFinite(lock) || lock < 1) return null;
    const paymentHash32 = Buffer.from(String(contentHashHex), 'hex');
    if (paymentHash32.length !== 32) return null;
    const built = new Htlc({
      network: this.settings.network || 'regtest',
      claimPubkey: sellerCompressed,
      refundPubkey: Buffer.from(String(buyerHex), 'hex'),
      paymentHash: paymentHash32,
      refundLocktime: lock
    });
    const hints = built.fundingHints({
      amountSats: Math.round(Number(amountSats) || 0),
      label: String(item.id || '').slice(0, 32)
    });
    const sellerHex = sellerCompressed.toString('hex');
    return {
      paymentAddress: built.address,
      paymentHashHex: built.paymentHashHex,
      claimScriptHex: built.claimScript.toString('hex'),
      refundScriptHex: built.refundScript.toString('hex'),
      refundLocktimeHeight: lock,
      amountSats: Math.round(Number(amountSats) || 0),
      bitcoinUri: hints.bitcoinUri,
      sellerPublicKeyHex: sellerHex,
      sellerPubkey: sellerHex
    };
  }

  /**
   * @returns {object[]} pending DOCUMENT_REQUEST rows (consent mode)
   */
  listPendingDocumentRequests () {
    return Object.keys(this.pendingDocumentRequests).map((key) => {
      const row = this.pendingDocumentRequests[key];
      return Object.assign({ key }, row);
    });
  }

  /**
   * Approve a pending DOCUMENT_REQUEST and send `P2P_FILE_SEND`.
   * @param {string} requestKey pending key, or document id when unique
   * @returns {{ok: boolean, error: (string|undefined), documentId: (string|undefined), peerAddress: (string|undefined)}}
   */
  approveDocumentRequest (requestKey, opts = {}) {
    const row = this._findPendingDocumentRequest(requestKey);
    if (!row) return { ok: false, error: 'pending request not found' };
    if (!this._documentRequestNamesBlob(row.documentId, row.parsed || {})) {
      return { ok: false, error: 'blobIndex required for a per-blob sealed document' };
    }
    if (row.parsed && row.parsed.quote === true && this._getSealedBlobDocument(row.documentId)) {
      this._sendSealedBlobQuote(row.documentId, Number(row.parsed.blobIndex), row.peerAddress, { routeId: row.parsed.routeId });
    }
    const sendOpts = {};
    if (row.parsed && row.parsed.blobIndex != null) {
      sendOpts.blobIndex = Number(row.parsed.blobIndex);
    }
    const sealedMeta = this._getDocumentSealedMeta(row.documentId);
    // Sealed key reveal requires prior authorizeDocumentKeyReveal (or explicit force).
    if (sealedMeta && this._mayRevealDocumentContentKey(row.documentId, sealedMeta.paymentHashHex, row.parsed || {}, opts)) {
      sendOpts.revealKey = true;
    } else if (!sealedMeta && this._mayRevealSealedBlobKey(row.documentId, row.parsed || {}, Object.assign({}, opts, { peerAddress: row.peerAddress }))) {
      sendOpts.revealKey = true;
    }
    if (!this._sendP2pFileSendToPeer(row.documentId, row.peerAddress, sendOpts)) {
      return { ok: false, error: 'could not send P2P_FILE_SEND (missing document or connection)' };
    }
    delete this.pendingDocumentRequests[row.key];
    this.emit('documentRequestApproved', row);
    return { ok: true, documentId: row.documentId, peerAddress: row.peerAddress };
  }

  /**
   * Record that settlement for a sealed document was verified so a matching
   * DocumentRequest may receive the AES content key (not merely the ciphertext).
   * @param {object} opts
   * @param {string} opts.documentId
   * @param {string} opts.contentHashHex payment hash SHA256(K)
   * @param {string} [opts.settlementId]
   * @param {string} [opts.txid]
   * @returns {Object} `{ ok, error?, key? }`
   */
  authorizeDocumentKeyReveal (opts = {}) {
    const documentId = String(opts.documentId || '').trim();
    const contentHashHex = String(opts.contentHashHex || opts.paymentHashHex || '').trim().toLowerCase();
    if (!documentId) return { ok: false, error: 'documentId required' };
    if (!/^[0-9a-f]{64}$/.test(contentHashHex)) {
      return { ok: false, error: 'contentHashHex must be 64 hex chars' };
    }
    const settlementId = opts.settlementId != null ? String(opts.settlementId).trim() : '';
    const txid = opts.txid != null ? String(opts.txid).trim() : '';
    // Require a settlement handle so callers cannot authorize from public hash echo alone.
    if (!settlementId && !txid) {
      return { ok: false, error: 'settlementId or txid required to authorize key reveal' };
    }
    const key = `${documentId}|${contentHashHex}`;
    this._authorizedDocumentKeyReveals.set(key, {
      documentId,
      contentHashHex,
      settlementId: settlementId || null,
      txid: txid || null,
      authorizedAt: Date.now()
    });
    while (this._authorizedDocumentKeyReveals.size > 4096) {
      const first = this._authorizedDocumentKeyReveals.keys().next().value;
      this._authorizedDocumentKeyReveals.delete(first);
    }
    this.emit('documentKeyRevealAuthorized', this._authorizedDocumentKeyReveals.get(key));
    return { ok: true, key };
  }

  /**
   * @param {string} documentId
   * @param {string} paymentHashHex
   * @param {object} parsed
   * @param {Object} [opts]
   * @param {boolean} [opts.forceReveal]
   * @returns {boolean}
   */
  /**
   * Per-blob sealed documents: the request must name one blob (`blobIndex`)
   * and its payment hash `SHA256(K_i)`; authorization is keyed
   * `documentId|paymentHash_i` exactly like whole-document reveals.
   * @param {string} documentId
   * @param {Object} parsed DocumentRequest body
   * @param {Object} [opts]
   * @returns {boolean}
   * @private
   */
  _mayRevealSealedBlobKey (documentId, parsed, opts = {}) {
    const doc = this._getSealedBlobDocument(documentId);
    if (!doc || !parsed || parsed.blobIndex == null) return false;
    const pay = doc.paymentHashFor(Number(parsed.blobIndex));
    if (!pay) return false;
    if (this._mayRevealDocumentContentKey(documentId, pay, parsed, opts)) return true;
    if (parsed.credit !== true || opts.forceReveal === true) return false;
    return this._extendSealedBlobCredit(documentId, Number(parsed.blobIndex), pay, parsed, opts.peerAddress || null);
  }

  /**
   * A DocumentRequest for a per-blob sealed document must name one held blob:
   * answering an index-less request would send every blob (up to
   * `MAX_DOCUMENT_BLOBS` frames) for one small message.
   * @param {string} documentId
   * @param {Object} parsed DocumentRequest body
   * @returns {boolean} true when the request may be served
   * @private
   */
  _documentRequestNamesBlob (documentId, parsed) {
    const doc = this._getSealedBlobDocument(documentId);
    if (!doc) return true;
    if (!parsed || parsed.blobIndex == null || parsed.blobIndex === '') return false;
    const idx = Number(parsed.blobIndex);
    return Number.isInteger(idx) && !!doc.blob(idx);
  }

  /**
   * Seller: send a signed `DocumentBlobQuote` (per-buyer payment hash) for one blob.
   * @param {string} documentId
   * @param {number} blobIndex
   * @param {string} peerAddress
   * @param {Object} [opts] `{ routeId }`
   * @returns {Object|null} the quote sent
   * @private
   */
  _sendSealedBlobQuote (documentId, blobIndex, peerAddress, opts = {}) {
    const conn = peerAddress && this.connections[peerAddress];
    if (!conn || !conn._writeFabric) return null;
    const out = this.quoteSealedBlob({ documentId, blobIndex });
    if (!out.ok) {
      this.emit('warning', `[FABRIC:PEER] blob quote failed for ${documentId}#${blobIndex}: ${out.error}`);
      return null;
    }
    const object = Object.assign({}, out.quote);
    if (opts.routeId) object.routeId = String(opts.routeId);
    const msg = Message.fromVector(['GenericMessage', JSON.stringify({ type: BLOB_QUOTE_TYPE, object })]);
    msg.signWithKey(this.key);
    conn._writeFabric(msg.toBuffer());
    this.emit('documentBlobQuoted', { documentId, blobIndex, peerAddress, paymentHashHex: out.quote.paymentHashHex, amountSats: out.quote.amountSats });
    return out.quote;
  }

  /**
   * Buyer: keep a seller's `DocumentBlobQuote` so the HTLC preimage it
   * settles with (`s`) can be unwrapped to `K_i` ({@link Peer#openSealedBlobWithKey}).
   * The signed frame is kept as fraud evidence.
   * @param {Object} quote
   * @param {Object|string} [origin]
   * @param {Message|null} [wireMessage]
   * @returns {{ ok: boolean, error: (string|undefined), paymentHashHex: (string|undefined) }}
   */
  _ingestSealedBlobQuote (quote, origin = null, wireMessage = null) {
    if (!isWellFormedBlobQuote(quote)) return { ok: false, error: 'malformed DocumentBlobQuote' };
    const paymentHashHex = String(quote.paymentHashHex).toLowerCase();
    let frame = null;
    try {
      if (wireMessage && typeof wireMessage.toBuffer === 'function') frame = wireMessage.toBuffer();
    } catch (_) { /* synthetic — no evidence */ }
    const capSetting = Number(this.settings.maxSealedBlobQuotes);
    const cap = Number.isFinite(capSetting) && capSetting > 0 ? capSetting : 4096;
    this._receivedBlobQuotes.delete(paymentHashHex);
    while (this._receivedBlobQuotes.size >= cap) {
      this._receivedBlobQuotes.delete(this._receivedBlobQuotes.keys().next().value);
    }
    const originName = origin && typeof origin === 'object' ? (origin.name || origin.address || null) : (origin || null);
    this._receivedBlobQuotes.set(paymentHashHex, { quote: Object.assign({}, quote), origin: originName, frame, received: Date.now() });
    this.emit('documentBlobQuote', { quote: Object.assign({}, quote), origin: originName });
    return { ok: true, paymentHashHex };
  }

  _mayRevealDocumentContentKey (documentId, paymentHashHex, parsed, opts = {}) {
    if (opts.forceReveal === true) {
      if (this.settings.allowForceDocumentKeyReveal !== true) {
        this.emit('warning',
          '[FABRIC:PEER] forceReveal ignored (set allowForceDocumentKeyReveal to enable)');
        return false;
      }
      return requestMatchesPaymentHash(parsed, paymentHashHex);
    }
    const authKey = `${String(documentId)}|${String(paymentHashHex || '').toLowerCase()}`;
    const settlementVerified = this._authorizedDocumentKeyReveals.has(authKey);
    return requestUnlocksContentKey(parsed, paymentHashHex, { settlementVerified });
  }

  /**
   * Deny / drop a pending DOCUMENT_REQUEST without sending bytes.
   * @param {string} requestKey
   * @returns {{ok: boolean, error: (string|undefined)}}
   */
  denyDocumentRequest (requestKey) {
    const row = this._findPendingDocumentRequest(requestKey);
    if (!row) return { ok: false, error: 'pending request not found' };
    delete this.pendingDocumentRequests[row.key];
    this.emit('documentRequestDenied', row);
    return { ok: true, documentId: row.documentId, peerAddress: row.peerAddress };
  }

  _findPendingDocumentRequest (requestKey) {
    if (!requestKey) return null;
    if (this.pendingDocumentRequests[requestKey]) {
      return Object.assign({ key: requestKey }, this.pendingDocumentRequests[requestKey]);
    }
    const matches = Object.keys(this.pendingDocumentRequests).filter((k) => {
      return this.pendingDocumentRequests[k].documentId === requestKey;
    });
    if (matches.length === 1) {
      const key = matches[0];
      return Object.assign({ key }, this.pendingDocumentRequests[key]);
    }
    return null;
  }

  _queuePendingDocumentRequest (documentId, origin, parsed) {
    this._pendingDocumentRequestSeq += 1;
    const key = `req-${this._pendingDocumentRequestSeq}`;
    const row = {
      documentId,
      peerAddress: origin && origin.name,
      created: Date.now(),
      parsed: parsed || null
    };
    this.pendingDocumentRequests[key] = row;
    const payload = Object.assign({ key }, row);
    this.emit('documentRequestPending', payload);
    return payload;
  }

  /**
   * AMP buffers for one document: canonical `DocumentPublish`, then optional pricing `P2P_DOCUMENT_PUBLISH`.
   * @param {string} documentId
   * @param {string} body UTF-8 body
   * @param {number} rateSats
   * @returns {Buffer[]}
   */
  _buildPublishDocumentWireBuffers (documentId, body, rateSats) {
    const parsed = this._buildDocumentParsedForPublish(documentId, body);
    const dataStr = fabricCanonicalJson(whitelistedDocumentFields(documentId, parsed));
    const canonical = Message.fromVector(['DocumentPublish', dataStr]);
    canonical.signWithKey(this.key);
    const buffers = [canonical.toBuffer()];
    if (rateSats > 0) {
      const sealedMeta = this._getDocumentSealedMeta(documentId);
      const resolved = resolveDocumentContentHashHex({
        documentId,
        parsed,
        sealedMeta: sealedMeta || undefined,
        sealed: !!sealedMeta
      });
      const contentHash = resolved.contentHashHex;
      const rateMsg = Message.fromVector(['P2P_DOCUMENT_PUBLISH', JSON.stringify({
        type: 'P2P_DOCUMENT_PUBLISH',
        object: {
          hash: documentId,
          rate: rateSats,
          contentHash,
          contentHashHex: contentHash,
          binding: resolved.binding
        }
      })]);
      rateMsg.signWithKey(this.key);
      buffers.push(rateMsg.toBuffer());
    }
    return buffers;
  }

  /**
   * Re-send all local document publishes to one peer (same bytes as {@link Peer#_publishDocument}).
   * @param {string} peerAddress connection key in {@link Peer#connections}
   */
  _announceLocalDocumentsToPeer (peerAddress) {
    const docs = this._state.content.documents;
    if (!docs || typeof docs !== 'object') return;
    const rates = this._state.content.documentRates || {};
    const conn = peerAddress && this.connections[peerAddress];
    if (!conn || !conn._writeFabric) return;
    for (const docId of Object.keys(docs)) {
      const body = docs[docId];
      const rateSats = Object.prototype.hasOwnProperty.call(rates, docId) ? rates[docId] : 0;
      const buffers = this._buildPublishDocumentWireBuffers(docId, body, rateSats);
      for (const buf of buffers) {
        conn._writeFabric(buf);
      }
    }
  }

  /**
   * Store a document locally and gossip to peers.
   * 1) **Canonical** `DOCUMENT_PUBLISH` wire message (same bytes as hub `documentPublishEnvelope`) for L1 `contentHash`.
   * 2) If `rateSats > 0`, a **pricing** `GENERIC` `P2P_DOCUMENT_PUBLISH` with `rate` and `contentHash` (sat ask).
   * @param {String} documentId - Catalog key (e.g. CLI document name).
   * @param {String} [content=''] - UTF-8 body stored under {@link Peer#state}.documents.
   * @param {Number} [rateSats=0] - Ask price in satoshis (gossip only; not part of canonical hash).
   */
  _publishDocument (documentId, content = '', rateSats = 0) {
    if (!isWireDocumentId(documentId)) {
      this.emit('warning',
        `[FABRIC:PEER] Not publishing document: id must be 1–${MAX_DOCUMENT_ID_LENGTH} characters`);
      return false;
    }
    if (!this._state.content.documents) this._state.content.documents = {};
    if (!this._state.content.documentRates) this._state.content.documentRates = {};
    if (!this._state.content.documentSealed) this._state.content.documentSealed = {};
    if (!this._state.content.documentContentKeys) this._state.content.documentContentKeys = {};
    const body = (content === null || content === undefined) ? '' : String(content);
    this._state.content.documents[documentId] = body;
    this._state.content.documentRates[documentId] = rateSats;

    // Priced docs: seal plaintext; HTLC payment hash = SHA256(content key).
    if (rateSats > 0 && this.settings.sealPricedDocuments !== false) {
      const sale = prepareSealedSale(Buffer.from(body, 'utf8'));
      this._state.content.documentSealed[documentId] = {
        ciphertextBase64: sale.ciphertext.toString('base64'),
        paymentHashHex: sale.paymentHashHex,
        encryption: sale.encryption,
        plaintextSha256: sale.plaintextSha256
      };
      this._state.content.documentContentKeys[documentId] = sale.keyHex;
    } else {
      delete this._state.content.documentSealed[documentId];
      delete this._state.content.documentContentKeys[documentId];
    }

    this.commit();

    const buffers = this._buildPublishDocumentWireBuffers(documentId, body, rateSats);
    for (const buf of buffers) {
      this.broadcast(buf);
    }

    if (this.settings.debug) {
      this.emit('debug', '[FABRIC:PEER] Published canonical DOCUMENT_PUBLISH + pricing gossip (if rate > 0)');
    }
  }

  /**
   * Buyer: flood a signed bid to buy one chunk of a document, so peers holding
   * it can answer with a `P2P_DOCUMENT_ASK` routed back along the bid's path.
   * Each answer is emitted as `documentAsk` and, with `opts.book`, ranked there.
   * @param {Object} opts see {@link DocumentBook.createBid}
   * @param {DocumentBook} [opts.book] book that takes the asks
   * @returns {object} the bid ({@link DocumentBook.readBid} shape; `id` names it)
   */
  bidForDocumentChunk (opts = {}) {
    const { message, bid } = DocumentBook.createBid(opts);
    this._sweepDocumentBids();
    this._documentBids.set(bid.id, {
      bid,
      sentAt: Date.now(),
      book: opts.book || null,
      sellers: new Set()
    });
    this.broadcast(message.toBuffer());
    return bid;
  }

  /**
   * Seller: answer a bid relayed here for a chunk this Peer holds (a per-blob
   * sealed document), at `opts.priceSats` or the document's listed rate. The
   * ask goes only to the connection the bid came from.
   * @param {string} bidId
   * @param {Object} [opts]
   * @param {number} [opts.priceSats] at most the bid's `maxSats`
   * @param {number} [opts.expiresAt] unix seconds, no later than the bid's
   * @returns {{ ok: boolean, ask: (object|undefined), error: (string|undefined) }}
   */
  askDocumentBid (bidId, opts = {}) {
    const route = this._documentBidRoutes.get(String(bidId || '').toLowerCase());
    if (!route) return { ok: false, error: 'unknown bid' };
    const held = this._heldChunkForBid(route.bid);
    if (!held) return { ok: false, error: 'chunk not held' };
    const priceSats = opts.priceSats != null ? opts.priceSats : held.rateSats;
    return this._sendDocumentAsk(route, held, priceSats, opts.expiresAt);
  }

  /**
   * The chunk a bid asks for, when this Peer holds it as a per-blob sealed
   * document matching the bid's selectors.
   * @param {object} bid
   * @returns {{ documentId: string, blobIndex: number, merkleRootHex: string, blobHashHex: string, rateSats: number }|null}
   * @private
   */
  _heldChunkForBid (bid) {
    const doc = this._getSealedBlobDocument(bid.documentId);
    const root = doc && doc.merkleRootHex ? String(doc.merkleRootHex).toLowerCase() : null;
    const leaf = root ? doc.blob(bid.blobIndex) : null;
    if (!leaf || !leaf.blobHashHex) return null;
    if (bid.merkleRootHex && bid.merkleRootHex !== root) return null;
    if (bid.blobHashHex && bid.blobHashHex !== leaf.blobHashHex) return null;
    return {
      documentId: bid.documentId,
      blobIndex: bid.blobIndex,
      merkleRootHex: root,
      blobHashHex: leaf.blobHashHex,
      rateSats: this._sealedBlobPriceSats(bid.documentId)
    };
  }

  /**
   * Sign and send an ask for a routed bid back to the bid's previous hop; once per bid.
   * @private
   */
  _sendDocumentAsk (route, held, priceSats, expiresAt = null) {
    if (route.answered) return { ok: false, error: 'already answered' };
    const conn = this.connections[route.prevHop];
    if (!conn) return { ok: false, error: 'bid path closed' };
    let built;
    try {
      built = DocumentBook.createAsk(route.bid, {
        key: this.key,
        merkleRootHex: held.merkleRootHex,
        blobHashHex: held.blobHashHex,
        priceSats: Number(priceSats),
        expiresAt: expiresAt != null ? Number(expiresAt) : undefined
      });
    } catch (e) {
      return { ok: false, error: e.message };
    }
    route.answered = true;
    conn._writeFabric(built.message.toBuffer());
    return { ok: true, ask: built.ask };
  }

  /**
   * Seller side of an inbound bid, by `settings.answerDocumentBids`.
   * @private
   */
  _maybeAnswerDocumentBid (route) {
    const policy = this.settings.answerDocumentBids;
    if (!policy) return null;
    const held = this._heldChunkForBid(route.bid);
    if (!held) return null;
    let priceSats = held.rateSats;
    if (typeof policy === 'function') {
      try {
        priceSats = policy(Object.assign({}, route.bid), Object.assign({}, held));
      } catch (e) {
        this.emit('warning', `[FABRIC:PEER] answerDocumentBids failed: ${e.message}`);
        return null;
      }
      if (priceSats == null) return null;
    }
    const sent = this._sendDocumentAsk(route, held, priceSats);
    if (!sent.ok) this.emit('debug', `[FABRIC:PEER] bid ${route.bid.id.slice(0, 12)} not answered: ${sent.error}`);
    return sent.ok ? sent.ask : null;
  }

  /**
   * Drop expired own bids and bid routes; past the cap, the oldest go.
   * @private
   */
  _sweepDocumentBids () {
    const now = Math.floor(Date.now() / 1000);
    for (const map of [this._documentBids, this._documentBidRoutes]) {
      for (const [id, entry] of map) {
        if (entry.bid.expiresAt <= now) map.delete(id);
      }
      while (map.size >= PEER_MAX_DOCUMENT_BID_ROUTES) map.delete(map.keys().next().value);
    }
  }

  /**
   * Count one onward bid against its TCP origin; false once over the rolling minute's budget.
   * @private
   */
  _takeDocumentBidRelay (originName) {
    const now = Date.now();
    let w = this._documentBidRelayRate.get(originName);
    if (!w || now - w.windowStart >= 60 * 1000) {
      if (!w && this._documentBidRelayRate.size >= MAX_PEERS * 4) {
        for (const [k, v] of this._documentBidRelayRate) {
          if (now - v.windowStart >= 60 * 1000) this._documentBidRelayRate.delete(k);
        }
        if (this._documentBidRelayRate.size >= MAX_PEERS * 4) return false;
      }
      w = { windowStart: now, count: 0 };
      this._documentBidRelayRate.set(originName, w);
    }
    if (w.count >= DOCUMENT_BID_MAX_RELAYS_PER_ORIGIN_PER_MINUTE) return false;
    w.count += 1;
    return true;
  }

  /**
   * Inbound `P2P_DOCUMENT_BID` (signature already verified): keep the route
   * back to the previous hop, emit `documentBid`, answer per
   * `settings.answerDocumentBids`, and flood it on bit-identical. Expired,
   * far-future, repeated, or over-rate bids are dropped. Peeled / foreign-relay
   * deliveries only emit, since they carry no path to answer along.
   * @private
   */
  _handleDocumentBidWire (message, origin, socket, options = null) {
    const delivery = meshDeliveryContext(options, origin && origin.name);
    const originName = origin && origin.name ? origin.name : null;
    const read = DocumentBook.readBid(message, { verify: false });
    if (!read.ok) {
      this.emit('debug', `[FABRIC:PEER] dropping bid from ${originName || 'unknown'}: ${read.error}`);
      return;
    }
    const bid = read.bid;
    if (this._documentBids.has(bid.id) || this._documentBidRoutes.has(bid.id)) return;
    if (!delivery.allowTcpOriginSideEffects || !originName) {
      this.emit('documentBid', { bid, origin: null, routed: false });
      return;
    }
    if (!this._takeDocumentBidRelay(originName)) {
      this.emit('debug', `[FABRIC:PEER] bid rate exceeded from ${originName}`);
      return;
    }
    this._sweepDocumentBids();
    const route = { bid, prevHop: originName, sellers: new Set(), answered: false };
    this._documentBidRoutes.set(bid.id, route);
    this.emit('documentBid', { bid, origin: originName, routed: true });
    this._maybeAnswerDocumentBid(route);
    if (delivery.allowMeshRelay) this.relayFrom(originName, message);
  }

  /**
   * Inbound `P2P_DOCUMENT_ASK` (signature already verified). For our own bid:
   * check it against the bid, ingest it into the bid's book, emit
   * `documentAsk`. For a bid routed here: check it the same way and pass it to
   * the bid's previous hop only. Anything else is dropped, never flooded. One
   * ask per seller per bid, at most `PEER_MAX_ASKS_PER_DOCUMENT_BID`.
   * @private
   */
  _handleDocumentAskWire (message, origin, options = null) {
    const delivery = meshDeliveryContext(options, origin && origin.name);
    const originName = origin && origin.name ? origin.name : null;
    const pre = DocumentBook.readAsk(message, { verify: false });
    if (!pre.ok) return;
    const bidId = pre.ask.bidId;
    const own = this._documentBids.get(bidId);
    const route = own ? null : this._documentBidRoutes.get(bidId);
    const entry = own || route;
    if (!entry) return;
    const read = DocumentBook.readAsk(message, { bid: entry.bid, verify: false });
    if (!read.ok) {
      this.emit('debug', `[FABRIC:PEER] dropping ask from ${originName || 'unknown'}: ${read.error}`);
      return;
    }
    const ask = read.ask;
    if (entry.sellers.has(ask.seller) || entry.sellers.size >= PEER_MAX_ASKS_PER_DOCUMENT_BID) return;
    if (own) {
      entry.sellers.add(ask.seller);
      const row = entry.book
        ? entry.book.ingestAsk(ask, { origin: originName, latencyMs: Date.now() - entry.sentAt })
        : null;
      this.emit('documentAsk', { ask, bid: entry.bid, origin: originName, row });
      return;
    }
    if (!delivery.allowTcpOriginSideEffects || originName === route.prevHop) return;
    const conn = this.connections[route.prevHop];
    if (!conn) return;
    entry.sellers.add(ask.seller);
    conn._writeFabric(message.toBuffer());
  }

  /**
   * Handle inbound `DOCUMENT_REQUEST`: emit `documentRequest` / `DocumentRequest`, then either
   * send `P2P_FILE_SEND` (when {@link Peer#settings.autoFulfillDocumentRequests}), queue for
   * operator approve, or relay when the document is not held.
   *
   * Peel / foreign-signed `P2P_RELAY` deliveries are local-observe only: never fulfill or
   * queue against the TCP last hop, and never second-flood the inner under that hop.
   *
   * @param {Message} message
   * @param {{ name: string }} origin
   * @param {*} socket
   * @param {Object} [options] same delivery opts as {@link Peer#_handleFabricMessage}
   */
  _handleDocumentRequestWire (message, origin, socket, options = null) {
    const delivery = meshDeliveryContext(options, origin && origin.name);
    const rawDr = messageDataToString(message.data);
    const prDr = tryParseWireJsonBody(rawDr);
    if (!prDr.ok) return;
    let parsed = prDr.value;
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) return;

    const docId = parsed.document || parsed.id;
    if (!docId) return;
    if (!isWireDocumentId(docId)) {
      this.emit('warning', `[FABRIC:PEER] Ignoring DOCUMENT_REQUEST with an invalid document id from ${(origin && origin.name) || 'unknown'}`);
      return;
    }

    const docs = this._state.content.documents;
    const sealedBlobs = this._state.content.documentSealedBlobs;
    const held = !!(docs && Object.prototype.hasOwnProperty.call(docs, docId)) ||
      !!(sealedBlobs && Object.prototype.hasOwnProperty.call(sealedBlobs, docId));
    let pendingKey = null;
    // Only queue TCP fulfill when the TCP hop is a trustworthy delivery target.
    if (held && delivery.allowTcpOriginSideEffects &&
        this.settings.autoFulfillDocumentRequests === false) {
      const pending = this._queuePendingDocumentRequest(docId, origin, parsed);
      pendingKey = pending.key;
    }

    const payload = {
      message,
      origin,
      socket,
      documentId: docId,
      parsed,
      source: 'canonical',
      pendingKey,
      localObserveOnly: !delivery.allowTcpOriginSideEffects
    };
    this.emit('documentRequest', payload);
    this.emit('DocumentRequest', payload);

    if (!held) {
      // Outer envelope already transported this request — do not mesh-relay or
      // private-rewrite under the last hop (would bind reverse routes to that hop).
      if (!delivery.allowMeshRelay) return;
      const budgeted = parsed.maxSats != null && Number.isFinite(Number(parsed.maxSats));
      if (budgeted && this.settings.relayPrivateDocumentRequests) {
        this._privateRelayDocumentRequest(parsed, origin, message);
        return;
      }
      this.relayFrom(origin.name, message, socket);
      return;
    }

    if (!delivery.allowTcpOriginSideEffects) {
      if (this.settings.debug) {
        this.emit('debug',
          '[FABRIC:PEER] DOCUMENT_REQUEST held but peel/RELAY-as-is — observe only (no fulfill to last hop)');
      }
      return;
    }

    if (this.settings.autoFulfillDocumentRequests === false) {
      return;
    }

    if (!this._documentRequestNamesBlob(docId, parsed)) {
      this.emit('warning', `[FABRIC:PEER] DOCUMENT_REQUEST for per-blob document ${docId} without a valid blobIndex from ${(origin && origin.name) || 'unknown'}`);
      return;
    }
    if (parsed.quote === true && this._getSealedBlobDocument(docId)) {
      this._sendSealedBlobQuote(docId, Number(parsed.blobIndex), origin.name, { routeId: parsed.routeId });
    }
    const sendOpts = {};
    if (parsed.blobIndex != null) sendOpts.blobIndex = Number(parsed.blobIndex);
    if (parsed.routeId) sendOpts.routeId = String(parsed.routeId);
    const sealedMeta = this._getDocumentSealedMeta(docId);
    // Ciphertext anytime; content key only after authorizeDocumentKeyReveal (never hash echo).
    if (sealedMeta && this._mayRevealDocumentContentKey(docId, sealedMeta.paymentHashHex, parsed)) {
      sendOpts.revealKey = true;
    } else if (!sealedMeta && this._mayRevealSealedBlobKey(docId, parsed, { peerAddress: origin && origin.name })) {
      sendOpts.revealKey = true;
    }
    if (!this._sendP2pFileSendToPeer(docId, origin.name, sendOpts)) {
      this.emit('warning', `[FABRIC:PEER] DOCUMENT_REQUEST: could not send P2P_FILE_SEND to ${origin && origin.name}`);
    }
  }

  /**
   * Rewrite a budgeted DocumentRequest (privacy) and forward with reduced maxSats.
   * @param {object} parsed
   * @param {{ name: string }} origin
   * @param {Message} [originalMessage]
   */
  _privateRelayDocumentRequest (parsed, origin, originalMessage = null) {
    const seenKey = `${parsed.routeId || ''}:${parsed.document || parsed.id}:${parsed.maxSats}`;
    if (this._documentRelaySeen.has(seenKey)) {
      this.emit('warning', '[FABRIC:PEER] Dropping looped DocumentRequest rewrite');
      return;
    }
    this._documentRelaySeen.add(seenKey);
    if (this._documentRelaySeen.size > 2048) {
      const first = this._documentRelaySeen.values().next().value;
      this._documentRelaySeen.delete(first);
    }

    const policy = {
      documentRelayFeeSats: this.settings.documentRelayFeeSats,
      documentRelayFeeBps: this.settings.documentRelayFeeBps,
      documentRelayMinRemainingSats: this.settings.documentRelayMinRemainingSats,
      documentRelayMaxHops: this.settings.documentRelayMaxHops
    };
    const fwd = buildForwardedDocumentRequest(parsed, policy);
    if (!fwd.ok) {
      this.emit('warning', `[FABRIC:PEER] private relay abort: ${fwd.error}`);
      return;
    }
    this._documentRelayRoutes[fwd.body.routeId] = {
      prevHopAddress: origin && origin.name,
      prevRouteId: parsed.routeId || null,
      feeSats: fwd.feeSats,
      maxSatsIn: Number(parsed.maxSats),
      maxSatsOut: fwd.maxSatsOut,
      documentId: fwd.body.document,
      blobIndex: fwd.body.blobIndex,
      created: Date.now()
    };
    this._capDocumentRelayRoutes();
    const msg = Message.fromVector(['DocumentRequest', JSON.stringify(fwd.body)]);
    msg.signWithKey(this.key);
    const sent = this._sendPrivateRelayedDocumentRequest(msg, origin, parsed);
    if (!sent) {
      this.emit('warning', '[FABRIC:PEER] private relay: no outbound peer for rewritten DocumentRequest');
      return;
    }
    this.emit('documentRequestRelayed', {
      feeSats: fwd.feeSats,
      maxSatsOut: fwd.maxSatsOut,
      routeId: fwd.body.routeId,
      documentId: fwd.body.document,
      origin,
      directed: true
    });
    if (originalMessage && this.settings.debug) {
      this.emit('debug', '[FABRIC:PEER] Rewrote DocumentRequest (directed; did not mesh-broadcast)');
    }
  }

  /**
   * Deliver a rewritten private DocumentRequest without mesh broadcast.
   * Preference: onion `relayPath` → explicit `nextPeer` → fan-out to TCP peers
   * other than the inbound origin.
   * @param {Message} msg signed DocumentRequest
   * @param {{name: (string|undefined)}|null} origin
   * @param {object} parsed inbound request body
   * @returns {boolean}
   */
  _sendPrivateRelayedDocumentRequest (msg, origin, parsed = {}) {
    if (!msg) return false;
    const path = Array.isArray(parsed.relayPath) ? parsed.relayPath : null;
    if (path && path.length) {
      return this.sendOnion(path, msg);
    }

    const next = parsed.nextPeer != null ? String(parsed.nextPeer).trim() : '';
    if (next) {
      const addr = (this.connections && this.connections[next])
        ? next
        : (this._resolveToAddress(next) || this._resolveAddressByXOnly(next));
      if (addr && this.connections[addr] && this.connections[addr]._writeFabric) {
        if (!(origin && origin.name && addr === origin.name)) {
          this.connections[addr]._writeFabric(msg.toBuffer());
          return true;
        }
      }
    }

    const buf = msg.toBuffer();
    let wrote = 0;
    for (const addr of Object.keys(this.connections || {})) {
      if (origin && origin.name && addr === origin.name) continue;
      const conn = this.connections[addr];
      if (conn && typeof conn._writeFabric === 'function') {
        conn._writeFabric(buf);
        wrote += 1;
      }
    }
    return wrote > 0;
  }

  /**
   * Forward a relayed `P2P_FILE_SEND` / key reveal back toward the buyer using reverse routes.
   * @param {object} fileObj
   * @param {{ name: string }} origin
   * @returns {boolean} true if forwarded (caller should skip local ingest)
   */
  _maybeReverseRelayFileSend (fileObj, origin) {
    const routeId = fileObj && (fileObj.routeId || fileObj.relayRouteId);
    if (!routeId || !this._documentRelayRoutes[routeId]) return false;
    const route = this._documentRelayRoutes[routeId];
    const prev = route.prevHopAddress;
    if (!prev || !this.connections[prev] || !this.connections[prev]._writeFabric) return false;
    if (origin && origin.name && origin.name === prev) return false;

    const fwd = Object.assign({}, fileObj, {
      routeId: route.prevRouteId || routeId,
      relayedBy: this.id || null
    });
    const msg = Message.fromVector(['P2P_FILE_SEND', JSON.stringify(fwd)]);
    msg.signWithKey(this.key);
    this.connections[prev]._writeFabric(msg.toBuffer());
    this.emit('documentRelayReturn', {
      routeId,
      prevHopAddress: prev,
      documentId: fileObj.name || fileObj.documentId,
      origin
    });
    return true;
  }

  _registerActor (object) {
    if (this.settings.debug) {
      const name = object && object.name != null ? String(object.name) : '(unnamed)';
      this.emit('debug', `Registering actor: ${name}`);
    }
    const actor = new Actor(object);

    /* actor.adopt([
      { op: 'replace', path: '/status', value: 'REGISTERED' }
    ]); */

    if (this.actors[actor.id]) return this;

    this.actors[actor.id] = actor;
    const name = object && object.name != null ? String(object.name) : '';
    if (name) this._actorsByName[name] = actor.id;
    this.emit('actorset', this.actors);

    return this;
  }

  /**
   * Drop the ephemeral socket Actor keyed by `host:port`.
   * @param {string} address
   * @returns {void}
   */
  _unregisterSocketActor (address) {
    if (!address) return;
    const name = String(address);
    let id = this._actorsByName[name];
    if (!id) id = new Actor({ name: name }).id;
    delete this._actorsByName[name];
    if (!this.actors[id]) return;
    delete this.actors[id];
    if (this._state.content && this._state.content.actors) {
      delete this._state.content.actors[id];
    }
    this.emit('actorset', this.actors);
  }

  /**
   * When a publish body declares authority arrays, the AMP wire signer must be
   * present and listed. Bodies with no authorities are allowed (observe-only;
   * empty patch allow-list). Missing signer fail-closes when authorities exist.
   * @param {object} object
   * @param {string|null} signerPubkeyHex
   * @returns {boolean}
   */
  _contractPublishSignerAuthorized (object, signerPubkeyHex = null) {
    return Contract.publishSignerAuthorized(object, signerPubkeyHex);
  }

  /**
   * Federation validator pubkeys for sidechain patch verification (settings or env).
   * @returns {string[]}
   */
  _distributedFederationValidatorsFromSettings () {
    const env = process.env.FABRIC_DISTRIBUTED_FEDERATION_VALIDATORS;
    if (env && String(env).trim()) {
      return String(env).split(',').map((s) => s.trim()).filter(Boolean);
    }
    const v = this.settings.distributed && this.settings.distributed.federation &&
      this.settings.distributed.federation.validators;
    return Array.isArray(v) ? v.slice() : [];
  }

  /**
   * k for federation witnesses. Unset = strict majority of the configured validators.
   * @returns {number}
   */
  _distributedFederationThresholdFromSettings () {
    const validators = this._distributedFederationValidatorsFromSettings();
    // Env threshold is independent of how validators were supplied (settings vs env).
    const envThreshold = process.env.FABRIC_DISTRIBUTED_FEDERATION_THRESHOLD;
    if (envThreshold != null && String(envThreshold).trim()) {
      return Federation.resolveThreshold(envThreshold, validators);
    }
    const t = this.settings.distributed && this.settings.distributed.federation &&
      this.settings.distributed.federation.threshold;
    return Federation.resolveThreshold(t, validators);
  }

  /**
   * @param {object} object
   * @param {string|null} [publisherPubkeyHex]
   * @returns {boolean} true when newly registered (or already present no-op)
   */
  _registerContract (object, publisherPubkeyHex = null) {
    if (this.settings.debug) {
      const idHint = object && (object.id || object.contractId || object.name) || 'contract';
      this.emit('debug', `Registering contract: ${idHint}`);
    }
    const actor = new Actor(object);

    // Duplicate CONTRACT_PUBLISH must not expand the patch allow-list. Otherwise an
    // attacker can re-sign an observed publish body and merge their pubkey (or a
    // forged parties[] list) into `_contractPatchAllowList`, then apply ops.
    if (this.contracts[actor.id]) {
      if (this.settings.debug) {
        this.emit('debug',
          `[FABRIC:PEER] Ignoring CONTRACT_PUBLISH republish for ${actor.id} (allow-list unchanged)`);
      }
      return true;
    }

    if (!this._contractPublishSignerAuthorized(object, publisherPubkeyHex)) {
      this.emit('warning',
        `[FABRIC:PEER] CONTRACT_PUBLISH rejected for ${actor.id}: ` +
        'wire signer is not listed in parties/validators/owners/members(.signers)/' +
        'authorities/spendPolicy.validators/proposedPolicy.validators');
      return false;
    }

    this.contracts[actor.id] = actor;
    this._state.content.contracts[actor.id] = object.state;
    this._contractGenesis[actor.id] = object;
    // Patch rights come only from declared authority arrays — never from the AMP
    // wire signer alone (front-run with identical body must not elevate attacker).
    this._mergeContractPatchAllowList(actor.id, object, publisherPubkeyHex);

    this.commit();
    this.emit('contractset', this.contracts);

    return true;
  }

  /**
   * Build the set of pubkeys allowed to apply CONTRACT_MESSAGE ops for a newly
   * registered contract. Called only on first registration of a contract id —
   * republishes must not invoke this (see {@link Peer#_registerContract}).
   * Membership is taken **only** from body authority arrays (`parties`,
   * `validators`, `owners`, `members` / `members.signers`, `authorities`,
   * `spendPolicy.validators`). The wire signer is never granted rights unless
   * already listed there.
   * @param {string} contractId
   * @param {object} object contract publish body
   * @param {string|null} [_publisherPubkeyHex] ignored (kept for call-site compat)
   */
  _mergeContractPatchAllowList (contractId, object, _publisherPubkeyHex = null) {
    const id = String(contractId || '');
    if (!id) return;
    let set = this._contractPatchAllowList[id];
    if (!set) {
      set = new Set();
      this._contractPatchAllowList[id] = set;
    }
    for (const hex of Contract.authorityPubkeys(object)) {
      set.add(hex);
    }
  }

  /**
   * @param {string} contractId
   * @param {string|null} signerPubkeyHex
   * @returns {boolean}
   */
  _signerMayPatchContract (contractId, signerPubkeyHex) {
    const set = this._contractPatchAllowList[String(contractId || '')];
    if (!set || !set.size) return false; // fail closed: no parties recorded
    return Contract.hasAuthority(set, signerPubkeyHex);
  }

  /**
   * Periodic P2P_PING and track expected P2P_PONG replies so registry score cannot be
   * self-inflated by unsolicited pongs (see FLUSH_CHAIN trust gate).
   * @param {*} socket — connection object (stores `_fabricPingOutstanding`, `_keepalive`)
   * @param {*} encryptWrite — NOISE encrypt stream with `.write(Buffer)` (`client.encrypt` / `handler.encrypt`)
   */
  _startFabricPingKeepalive (socket, encryptWrite) {
    if (socket._keepalive) clearInterval(socket._keepalive);
    socket._fabricPingOutstanding = 0;
    socket._keepalive = setInterval(() => {
      // At most one unanswered PING per connection so burst P2P_PONG cannot inflate registry score
      // (FLUSH_CHAIN trust gate uses _registryScoreForConnectionAddress).
      if ((socket._fabricPingOutstanding | 0) >= 1) return;
      const P2P_PING = Message.fromLegacyBody('P2P_PING', {
        nonce: this._freshKeepaliveNonce()
      }).signWithKey(this.key);
      socket._fabricPingOutstanding = 1;
      try {
        const buf = P2P_PING.toBuffer();
        encryptWrite.write(buf);
        this._recordPeerBandwidth(socket._fabricPeerAddress, 'out', buf);
      } catch (exception) {
        socket._fabricPingOutstanding = 0;
        if (exception && (exception.code === 'EPIPE' || exception.code === 'ECONNRESET')) {
          this.emit('warning', `Suppressing transient write error (${exception.code}) during ping.`);
        } else {
          this.emit('debug', `Cannot write ping: ${exception}`);
        }
      }
    }, 60000);
  }

  /**
   * Keepalive nonce. BIP340 signing here is deterministic, so a repeated body
   * would yield a byte-identical frame that wire-hash dedup drops.
   * @private
   * @returns {string}
   */
  _freshKeepaliveNonce () {
    return `${crypto.randomBytes(8).toString('hex')}-${Date.now().toString(36)}`;
  }

  _registerNOISEClient (name, socket, client) {
    // Assign socket properties
    // Failure counter
    socket._failureCount = 0;
    socket._lastMessage = null;
    socket._messageLog = [];
    socket._noiseClient = client;
    socket._fabricPeerAddress = name;

    this._startFabricPingKeepalive(socket, client.encrypt);

    // TODO: reconcile APIs for these methods
    // Map destroy function
    socket._destroyFabric = () => {
      this._destroyFabric(socket, name);
    };

    // Map write function
    socket._writeFabric = (msg) => {
      const written = this._writeFabric(msg, client);
      if (written) this._recordPeerBandwidth(name, 'out', msg);
      return written;
    };

    this.connections[name] = socket;

    return this;
  }

  _registerPeer (data) {
    const peer = new Actor({
      type: 'Peer',
      data: data
    });

    if (this.peers[peer.id]) return this;

    this.peers[peer.id] = peer;

    return this;
  }

  _scheduleReconnect (target, when = 250) {
    this.emit('debug', `Scheduled reconnect to ${target} in ${when} milliseconds...`);
    const reconnect = setTimeout(() => {
      this._connect(target);
    }, when);

    this.emit('debug', `Scheduled: ${reconnect}`);
  }

  _selectBestPeerCandidate () {
    const candidates = [];

    for (const id of Object.entries(this.peers)) {
      candidates.push(id);
    }

    candidates.sort((a, b) => {
      return (a.score > b.score) ? 1 : 0;
    });

    return candidates[0] || null;
  }

  _verifyNOISE (localPrivateKey, localPublicKey, remotePublicKey, done) {
    // When static keys are present, refuse a NOISE peer that is ourselves.
    try {
      const local = normalizePeerPubkeyHex(localPublicKey);
      const remote = normalizePeerPubkeyHex(remotePublicKey);
      if (local && remote && local === remote) {
        this.emit('warning', '[FABRIC:PEER] NOISE verify rejected: remote static key is local');
        this.emit('peer:self', { address: null, reason: 'NOISE remote static key is local' });
        return done(null, false);
      }
      if (remote && this._isOwnFabricPubkey(remote)) {
        this.emit('warning', '[FABRIC:PEER] NOISE verify rejected: remote static matches Fabric identity');
        this.emit('peer:self', { address: null, reason: 'NOISE remote static matches Fabric identity' });
        return done(null, false);
      }
    } catch (exception) {
      this.emit('warning',
        `[FABRIC:PEER] NOISE verify rejected: self-key check failed: ${exception && exception.message ? exception.message : exception}`);
      return done(null, false);
    }
    done(null, true);
  }

  /**
   * Write an AMP frame onto a NOISE encrypt stream.
   * @param {Buffer} msg
   * @param {object} stream Noise handler/client (`encrypt.write`)
   * @returns {boolean} True only when the local encrypt stream accepted the write.
   */
  _writeFabric (msg, stream) {
    const hash = crypto.createHash('sha256').update(msg).digest('hex');
    this._rememberWireHash(hash);
    if (!stream || !stream.encrypt) return false;

    const encrypt = stream.encrypt;
    const isWritable = (encrypt.writable !== false) && !encrypt.writableEnded && !encrypt.destroyed;

    if (!isWritable) {
      this.emit('warning', 'Attempted to write to a closed or destroyed stream; skipping.');
      return false;
    }

    const remoteCap = stream._fabricRemoteMaxFrameBytes;
    if (Number.isInteger(remoteCap) && msg && msg.length > remoteCap) {
      const type = (Buffer.isBuffer(msg) && msg.length >= 76) ? msg.readUInt32BE(72) : null;
      this.emit('warning',
        `[FABRIC:PEER] Not sending ${msg.length}-byte frame (type=${type}) over remote frame cap ${remoteCap}`);
      return false;
    }

    try {
      encrypt.write(msg);
      return true;
    } catch (error) {
      if (error && (error.code === 'EPIPE' || error.code === 'ECONNRESET')) {
        this.emit('warning', `Suppressing transient write error (${error.code}) during NOISE write.`);
      } else {
        this.emit('error', error);
      }
      return false;
    }
  }

  /**
   * Start the Peer.
   */
  async start () {
    await this._loadPeerRegistry();

    // Log settings at start
    if (this.settings.debug) {
      this.emit('debug', `[FABRIC:PEER:START] networking: ${this.settings.networking}`);
      this.emit('debug', `[FABRIC:PEER:START] peers: ${JSON.stringify(this.settings.peers)}`);
    }

    let address = null;
    this.emit('log', 'Peer starting...');

    // Ensure initial peers from config are in the registry
    if (this.settings.peers && Array.isArray(this.settings.peers)) {
      for (const candidate of this.settings.peers) {
        this._upsertPeerRegistry(candidate, { address: candidate });
      }
    }

    if (this.settings.debug) {
      this.emit('debug', `[FABRIC:PEER] Listening on port: ${this.settings.port}`);
      this.emit('debug', `[FABRIC:PEER] Peer list: ${JSON.stringify(this.settings.peers)}`);
    }

    if (this.settings.listen) {
      this.emit('log', 'Listener starting...');

      const maxAttemptsRaw = this.settings.listenPortAttempts;
      const maxAttempts = (typeof maxAttemptsRaw === 'number' && maxAttemptsRaw > 0)
        ? Math.min(256, Math.floor(maxAttemptsRaw))
        : 20;
      const basePort = (typeof this.settings.port === 'number' && !Number.isNaN(this.settings.port))
        ? this.settings.port
        : 7777;

      for (let attempt = 0; attempt < maxAttempts; attempt++) {
        this.settings.port = basePort + attempt;
        if (this.public && typeof this.public === 'object') this.public.port = this.settings.port;

        if (this.settings.debug) {
          this.emit('debug', `Starting listener on ${this.interface}:${this.settings.port} (attempt ${attempt + 1}/${maxAttempts})`);
        }

        try {
          address = await this.listen();
          if (this.settings.debug) this.emit('debug', `got address: ${JSON.stringify(address)}`);
          this.listenAddress = address;
          if (attempt > 0) {
            this.emit('log', `[FABRIC:PEER] Port ${basePort} was busy; listening on ${this.settings.port} instead.`);
          }
          this.emit('log', 'Listener started!');
          break;
        } catch (exception) {
          const inUse = exception && exception.code === 'EADDRINUSE';
          if (inUse && attempt < maxAttempts - 1) {
            this.emit('warning', `[FABRIC:PEER] Port ${this.settings.port} in use, trying ${this.settings.port + 1}...`);
            continue;
          }
          // Do not emit('error') here — with no listener Node throws ERR_UNHANDLED_ERROR; callers get the throw below.
          this.emit('warning', 'Could not listen:', exception);
          throw new Error('Peer failed to listen: ' + (exception && exception.message ? exception.message : exception));
        }
      }

      this._registerActor({ name: `${this.interface}:${this.port}` });
    } else {
      this._registerActor({ name: `${this.interface}:${this.port}` });
    }

    if (this.settings.networking && this.settings.peers && this.settings.peers.length) {
      this.emit('warning', `Networking enabled.  Connecting to peers: ${JSON.stringify(this.settings.peers)}`);
      for (const candidate of this.settings.peers) {
        this.emit('debug', `[FABRIC:PEER] Connecting to peer: ${candidate}`);
        try {
          this._connect(candidate);
          this.emit('debug', `[FABRIC:PEER] Connection attempt initiated for: ${candidate}`);
        } catch (error) {
          this.emit('error', `[FABRIC:PEER] Failed to initiate connection to ${candidate}: ${error.message}`);
        }
      }
    }

    // Reconnect to known peers from the persistent registry (if not already connected).
    // Only do this when a persistent registry is configured and the caller hasn't provided
    // an explicit peer list (prevents duplicate outbound connects and avoids test hangs).
    if (
      this.settings.networking !== false &&
      this.settings.reconnectToKnownPeers !== false &&
      this.settings.peersDb &&
      (!this.settings.peers || this.settings.peers.length === 0) &&
      this._state.peers &&
      typeof this._state.peers === 'object'
    ) {
      const registry = this._state.peers;
      const toReconnect = Object.keys(registry).filter((addr) => {
        if (this.connections[addr]) return false;
        if (this._outboundDialTargets && this._outboundDialTargets.has(addr)) return false;
        const listenAddr = this.listenAddress || `${this.interface}:${this.port}`;
        if (addr === listenAddr) return false;
        if (this._isPeerBanned(addr)) return false;
        return true;
      });
      if (toReconnect.length > 0) {
        this.emit('debug', `[FABRIC:PEER] Reconnecting to ${toReconnect.length} known peers from registry`);
        toReconnect.forEach((addr, i) => {
          setTimeout(() => {
            try {
              this._connect(addr);
              this.emit('debug', `[FABRIC:PEER] Reconnect attempt for: ${addr}`);
            } catch (err) {
              this.emit('debug', `[FABRIC:PEER] Reconnect failed for ${addr}: ${err && err.message}`);
            }
          }, i * 150);
        });
      }
    }

    if (this.settings.debug) this.emit('debug', `Observing state...`);

    try {
      this.observer = manager.observe(this._state.content);
    } catch (exception) {
      this.emit('error', `Could not observe state: ${exception}`);
    }

    await this._startHeart();

    if (this.settings.debug) this.emit('debug', `Peer ready!  State: ${JSON.stringify(this.state, null, '  ')}`);

    this.emit('ready', {
      id: this.id,
      address: address,
      pubkey: this.key.pubkey
    });

    if (this.settings.debug) this.emit('debug', `Peer started!`);

    /*
    const PACKET_PEER_ANNOUNCE = Message.fromVector(['P2P_PEER_ANNOUNCE', JSON.stringify({
      type: 'P2P_PEER_ANNOUNCE',
      object: {
        host: this._externalIP,
        port: this.settings.port
      }
    })]).signWithKey(this.key);
    const announcement = PACKET_PEER_ANNOUNCE.toBuffer();
    // this.emit('debug', `Announcing peer: ${announcement.toString('utf8')}`);
    this.connections[origin.name]._writeFabric(announcement, socket);
    */

    return this;
  }

  /**
   * Stop the peer.
   */
  async stop () {
    // Alert listeners
    this.emit('log', 'Peer stopping...');
    this._state.status = 'STOPPING';

    // Stop the heart
    if (this._heart) clearInterval(this._heart);

    if (this._musigSessions) {
      for (const session of this._musigSessions.values()) {
        musig2Session.wipeSession(session);
      }
      this._musigSessions.clear();
      this._musigSessionOrder = [];
    }

    this.emit('debug', 'Closing all connections...');
    for (const id in this.connections) {
      const c = this.connections[id];
      if (c && typeof c.destroy === 'function') c.destroy();
    }

    // Cancel pending registry save and close LevelDB
    if (this._peerRegistrySaveScheduled) clearTimeout(this._peerRegistrySaveScheduled);
    if (this._peersDb) {
      try {
        await this._peersDb.close();
      } catch { /* ignore */ }
      this._peersDb = null;
    }

    const terminator = async () => {
      return new Promise((resolve, reject) => {
        // Always attempt to close the server, even if address() returns null
        // This ensures cleanup even if the server failed to start properly
        if (!this.server || typeof this.server.close !== 'function') {
          return resolve();
        }

        // Check if server is listening
        const address = this.server.address();
        if (!address) {
          // Server not listening, but still try to close to be safe
          // Some server states might not have address() but still need cleanup
          try {
            this.server.close(() => resolve());
          } catch {
            // If close fails, it's likely already closed - resolve anyway
            resolve();
          }
          return;
        }

        // Server is listening, close it properly
        return this.server.close(function serverClosed (error) {
          // Ignore errors if server wasn't running or already closed
          if (error && error.code !== 'ERR_SERVER_NOT_RUNNING') {
            return reject(error);
          }
          resolve();
        });
      });
    };

    this.emit('debug', 'Closing network...');
    await terminator();

    this._state.status = 'STOPPED';
    this.commit();

    this.emit('log', 'Peer stopped!');

    return this;
  }

  async _setState (value) {
    if (!value) return new Error('You must provide a State to set the value to.');
    this._state.content = value;
    return this.state;
  }

  _disconnect (address) {
    this.emit('debug', `Disconnect request for address: ${address}`);
    const socket = this.connections[address];
    if (!socket) return false;

    if (socket._keepalive) clearInterval(socket._keepalive);
    if (socket.heartbeat) clearInterval(socket.heartbeat);
    this._teardownNoiseClient(socket);
    if (this._outboundDialTargets) this._outboundDialTargets.delete(address);
    delete this.connections[address];
    delete this.peers[address];
    this._unregisterSocketActor(address);
    if (typeof socket.destroy === 'function') socket.destroy();

    this._upsertPeerRegistry(address, { lastSeen: new Date().toISOString() });

    this.emit('connections:close', { address, name: address });
    return true;
  }

  _maintainConnection (address) {
    const peer = this;
    if (!peer.connections[address]) return new Error(`Connection for address "${address}" does not exist.`);
  }

  _updateLiveness (address) {
    // Return Error if no connection
    if (!this.connections[address]) {
      const error = `No connection for address: ${address}`;
      this.emit('error', error);
      return new Error(error);
    }

    // Set the _lastMessage property
    this.connections[address]._lastMessage = Date.now();

    // Make chainable
    return this;
  }

  _registerHandler (type, method) {
    if (this.handlers[type]) return new Error(`Handler for method "${type}" is already registered.`);
    this.handlers[type] = method.bind(this);
    return this.handlers[type];
  }

  async _requestStateFromAllPeers () {
    const message = Message.fromVector(['StateRequest']);
    this.broadcast(message);
  }

  /**
   * Start listening for connections.
   * @return {Peer} Chainable method.
   */
  async listen () {
    return new Promise((resolve, reject) => {
      if (this.settings.debug) this.emit('debug', `Listening on ${this.interface}:${this.port}`);
      let settled = false;

      const rejectListen = (error) => {
        if (settled) return;
        settled = true;
        this.server.removeListener('error', errorHandler);
        if (this.listenerCount('error') > 0) {
          this.emit('error', `Server socket error: ${error}`);
        }
        return reject(error);
      };

      // Handle server errors before attempting to listen
      const errorHandler = (error) => {
        if (error.code === 'EADDRINUSE') {
          // Ensure server resources are released before retrying upstream.
          // Recreate the TCP server after close — a closed Server can retain
          // sticky listen state and spuriously fail the next port attempt.
          this.server.close(() => {
            if (this.settings.listen) {
              this.server = net.createServer(this._NOISESocketHandler.bind(this));
              this._peerServerRuntimeErrorBound = false;
            }
            rejectListen(error);
          });
          return;
        }
        rejectListen(error);
      };

      this.server.once('error', errorHandler);

      this.server.listen(this.port, this.interface, (error) => {
        if (settled) return;
        // Remove the error handler since we're handling the result here
        this.server.removeListener('error', errorHandler);

        if (error) {
          return rejectListen(error);
        }
        settled = true;

        const details = this.server.address();
        const address = `${details.address}:${details.port}`;

        // Runtime errors after listen succeeds; attach once so port-retry does not stack handlers.
        if (!this._peerServerRuntimeErrorBound) {
          this._peerServerRuntimeErrorBound = true;
          this.server.on('error', (runtimeError) => {
            if (runtimeError.code !== 'EADDRINUSE' && this.listenerCount('error') > 0) {
              this.emit('error', `Server socket error: ${runtimeError}`);
            }
          });
        }

        this.emit('log', `Now listening on tcp://${address} [!!!]`);
        return resolve(address);
      });
    });
  }
}

class Swarm extends Actor {
  constructor (config = {}) {
    super(config);

    this.name = 'Swarm';
    this.settings = Object.assign({
      name: 'fabric',
      seeds: [],
      peers: [],
      contract: 0xC0D3F33D
    }, config);

    this.agent = new Peer(this.settings);

    this.nodes = {};
    this.peers = {};

    return this;
  }

  broadcast (msg) {
    if (this.settings.verbosity >= 5) this.emit('debug', `broadcasting: ${JSON.stringify(msg)}`);
    this.agent.broadcast(msg);
  }

  connect (address) {
    if (this.settings.verbosity >= 4) this.emit('debug', `[FABRIC:SWARM] Connecting to: ${address}`);

    try {
      this.agent._connect(address);
    } catch (E) {
      this.error('Error connecting:', E);
    }
  }

  trust (source) {
    super.trust(source);
    const swarm = this;

    swarm.agent.on('ready', function (agent) {
      swarm.emit('agent', agent);
    });

    swarm.agent.on('message', function (message) {
      swarm.emit('message', message);
    });

    swarm.agent.on('state', function (state) {
      this.emit('debug', `[FABRIC:SWARM] Received state from agent: ${JSON.stringify(state)}`);
      swarm.emit('state', state);
    });

    swarm.agent.on('change', function (change) {
      this.emit('debug', `[FABRIC:SWARM] Received change from agent: ${JSON.stringify(change)}`);
      swarm.emit('change', change);
    });

    swarm.agent.on('patches', function (patches) {
      this.emit('debug', `[FABRIC:SWARM] Received patches from agent: ${JSON.stringify(patches)}`);
      swarm.emit('patches', patches);
    });

    swarm.agent.on('peer', function (peer) {
      this.emit('debug', `[FABRIC:SWARM] Received peer from agent: ${JSON.stringify(peer)}`);
      swarm._registerPeer(peer);
    });

    swarm.agent.on('connections:open', function (connection) {
      swarm.emit('connections:open', connection);
    });

    swarm.agent.on('connections:close', function (connection) {
      swarm.emit('connections:close', connection);
      swarm._fillPeerSlots();
    });

    swarm.agent.on('collections:post', function (message) {
      swarm.emit('collections:post', message);
    });

    swarm.agent.on('socket:data', function (message) {
      swarm.emit('socket:data', message);
    });

    swarm.agent.on('ready', function (info) {
      swarm.log(`swarm is ready (${info.id})`);
      swarm.emit('ready');
      swarm._fillPeerSlots();
    });

    return this;
  }

  _broadcastTypedMessage (type, msg) {
    if (!type) return new Error('Message type must be supplied.');
    this.agent._broadcastTypedMessage(type, msg);
  }

  _registerPeer (peer) {
    const swarm = this;
    if (!swarm.peers[peer.id]) swarm.peers[peer.id] = peer;
    swarm.emit('peer', peer);
  }

  _scheduleReconnect (peer) {
    const swarm = this;
    this.log('schedule reconnect:', peer);

    if (swarm.peers[peer.id]) {
      if (swarm.peers[peer.id].timer) return true;
      swarm.peers[peer.id].timer = setTimeout(function () {
        clearTimeout(swarm.peers[peer.id].timer);
        swarm.connect(peer);
      }, 60000);
    }
  }

  _fillPeerSlots () {
    const swarm = this;
    const slots = MAX_PEERS - Object.keys(this.nodes).length;
    const peers = Object.keys(this.peers).map(function (id) {
      if (swarm.settings.verbosity >= 5) swarm.emit('debug', `[FABRIC:SWARM] _fillPeerSlots() checking: ${JSON.stringify(swarm.peers[id])}`);
      return swarm.peers[id].address;
    });
    const candidates = swarm.settings.peers.filter(function (address) {
      return !peers.includes(address);
    });

    if (slots) {
      for (let i = 0; (i < candidates.length && i < slots); i++) {
        swarm._scheduleReconnect(candidates[i]);
      }
    }
  }

  async _connectSeedNodes () {
    if (this.settings.verbosity >= 4) this.emit('debug', `[FABRIC:SWARM] Connecting to seed nodes: ${JSON.stringify(this.settings.seeds)}`);
    for (const id in this.settings.seeds) {
      if (this.settings.verbosity >= 5) this.emit('debug', `[FABRIC:SWARM] Iterating on seed: ${this.settings.seeds[id]}`);
      this.connect(this.settings.seeds[id]);
    }
  }

  async start () {
    if (this.settings.verbosity >= 4) this.emit('debug', '[FABRIC:SWARM] Starting...');
    await this.agent.start();
    await this._connectSeedNodes();
    if (this.settings.verbosity >= 4) this.emit('debug', '[FABRIC:SWARM] Started!');
    return this;
  }

  async stop () {
    if (this.settings.verbosity >= 4) this.emit('debug', '[FABRIC:SWARM] Stopping...');
    await this.agent.stop();
    if (this.settings.verbosity >= 4) this.emit('debug', '[FABRIC:SWARM] Stopped!');
    return this;
  }
}

module.exports = Peer;
module.exports.Swarm = Swarm;
/** @private Test/debug helper — never log private material. */
Peer.debugDerivedPublicSummary = peerDebugDerivedPublicSummary;
