'use strict';

const crypto = require('crypto');
const { EventEmitter } = require('events');
const monitor = require('fast-json-patch');
const Witness = require('./witness');

/**
 * @classdesc <strong>Structured document</strong> type: extends {@link EventEmitter} (not {@link Actor}) with
 * <code>@type</code> / <code>@data</code> shape, JSON serialization, and <code>id</code> = SHA256(<code>toJSON()</code>).
 * <strong>Different model from {@link Actor#id}</strong> (sorted generic envelope). <code>Entity.Transition</code> (JSON Patch
 * between entity states) is the supported migration path — see <strong>DEVELOPERS.md</strong> (<em>Consolidated prototypes</em>).
 * @class Entity
 * @extends EventEmitter
 */
class Entity extends EventEmitter {
  constructor (data = {}) {
    super(data);

    // allow this entity to be run without the new keyword
    if (!(this instanceof Entity)) return new Entity(data);

    // set internal properties
    this.settings = {
      verbosity: 2 // Information && Warnings
    };

    // configure defaults
    this.actor = Object.assign({}, this._downsample(data));
    this.data = Object.assign({}, data);

    // TODO: use getters/setters to restrict access to these elements
    // remove EventEmitter cruft
    Object.defineProperty(this, '_events', { enumerable: false });
    Object.defineProperty(this, '_eventsCount', { enumerable: false });
    Object.defineProperty(this, '_maxListeners', { enumerable: false });

    // remove mutable variables
    Object.defineProperty(this, 'actor', { enumerable: false });
    // Object.defineProperty(this, 'machine', { enumerable: false });

    // return instance
    return this;
  }

  get version () {
    return 1;
  }

  set state (state) {
    if (!state) throw new Error('State must be provided.');
    this._state = state;
  }

  get state () {
    return Object.assign({}, this._state);
  }

  get buffer () {
    let entity = this;
    return function buffer () {
      return Buffer.from(entity.toJSON(), 'utf8');
    };
  }

  get id () {
    let data = this.toJSON();
    let hash = crypto.createHash('sha256').update(data).digest('hex');
    if (this.settings.verbosity >= 5) console.log('[FABRIC:ENTITY (pending upstream!)]', 'hash:', hash, 'data:', data);
    return hash;
  }

  serialize () {
    return this.toJSON();
  }

  toBuffer () {
    return Buffer.from(this.toString(), 'utf8');
  }

  /**
   * Produces a string of JSON, representing the entity.
   * @return {String} JSON-encoded object.
   */
  toJSON () {
    let result = null;

    switch (this.actor['@type']) {
      default:
        result = JSON.stringify(this.toObject());
        break;
      case 'Function':
        result = this._downsample();
        break;
      case 'Buffer':
      case 'String':
        result = JSON.stringify(this.toString());
        break;
    }

    return result;
  }

  toString () {
    let result = null;

    switch (this.actor['@type']) {
      default:
        result = JSON.stringify(this.actor['@data']);
        break;
      case 'Buffer':
        void new Uint8Array(this.data);
        const values = Object.values(this.data);
        result = JSON.stringify(values);
        break;
      case 'String':
        // TODO: write up longer-form explanation as to why we use an Array here
        result = this.actor['@data'].map(x => String.fromCharCode(x)).join('');
        // console.log('was string in array? now:', result);
        break;
    }

    return result;
  }

  toObject () {
    return this.actor['@data'];
  }

  /**
   * As a {@link Buffer}.
   * @return {Buffer} Slice of memory.
   */
  toRaw () {
    return Buffer.from(this.toJSON(), 'utf8');
  }

  /**
   * Return a {@link Fabric}-labeled {@link Object} for this {@link Entity}.
   * @param {Mixed} [input] Input to downsample.  If not provided, current Entity will be used. 
   */
  _downsample (input = this.data) {
    let result = {};

    if (typeof input === 'string') {
      result = {
        '@type': 'String',
        '@data': input.split('').map(x => x.charCodeAt(0))
      };
    } else if (input instanceof Array) {
      result = {
        '@type': 'Array',
        '@data': input
      };
    } else if (input instanceof Buffer) {
      result = {
        '@type': 'Buffer',
        '@data': JSON.parse(JSON.stringify(input))[0]
      };
    } else if (input instanceof Function) {
      try {
        result = {
          '@type': 'Function',
          '@data': JSON.stringify(input)
        };
      } catch (E) {
        console.error('Something could not be converted:', E, input);
        process.exit();
      }
    } else {
      try {
        result = {
          '@type': 'Entity',
          '@data': JSON.parse(JSON.stringify(input))
        };
      } catch (E) {
        console.error('Something could not be converted:', E, input);
        process.exit();
      }
    }

    return result;
  }
}

/**
 * @classdesc JSON Patch <strong>diff</strong> between two {@link Entity} snapshots (<code>origin</code>,
 * <code>target</code>, <code>changes</code>). Built via {@link Transition.between}, {@link Transition#fromTarget}, or manual
 * <code>changes</code>; uses <code>fast-json-patch</code> observe/generate.
 * @memberof Entity
 * @class Transition
 * @extends Entity
 */
class Transition extends Entity {
  constructor (settings = {}) {
    super(settings);

    this.status = 'constructing';
    this._state = {
      origin: null,
      target: null,
      changes: [],
      program: [],
      witness: null
    };

    this.settings = Object.assign({}, this._state, settings);
    this.witness = new Witness(this.settings);

    this._setOrigin(this.settings.origin);
    this._setTarget(this.settings.target);

    this.status = 'constructed';
  }

  static between (origin, target) {
    const x = new Entity(origin);
    const y = new Entity(target);

    const actor = Object.assign({}, origin);
    const observer = monitor.observe(actor);

    Object.assign(actor, target);

    return new Transition({
      origin: x.id,
      target: y.id,
      changes: monitor.generate(observer)
    });
  }

  fromTarget (target) {
    const base = new Entity();
    const entity = this._describeTarget(target);
    return new Transition({
      origin: base.id,
      target: entity.id
    });
  }

  _applyTo (state) {
    if (!state) throw new Error('State must be provided.');
    if (!(state instanceof Entity)) throw new Error('State not of known Entity type.');

    const instance = Object.assign({}, state);
    const observer = monitor.observe(instance);

    try {
      monitor.applyPatch(instance, this._state.changes);
    } catch (E) {
      console.error('Could not apply changes:', E);
    }

    monitor.generate(observer);
    return instance;
  }

  _setChanges (changes) {
    if (!changes) throw new Error('No changes specified.');
    this._state.changes = changes;
  }

  _setOrigin (origin) {
    if (!origin) throw new Error('No origin specified.');
    this._state.origin = origin;
  }

  _setTarget (target) {
    if (!target) throw new Error('No target specified.');
    this._state.target = target;
  }

  _describeTarget (target) {
    if (!target) throw new Error('No target specified.');
    const entity = new Entity(target);
    this._setTarget(entity.id);
    return entity;
  }
}

Entity.Transition = Transition;

module.exports = Entity;
module.exports.Transition = Transition;
