'use strict';

const PATCHES_ENABLED = true;
const { tryParsePersistedJson, tryParseWireJson, utf8FromPersistedRaw } = require('../functions/wireJson');

// Dependencies
const crypto = require('crypto');
const stream = require('stream');
const path = require('path');
const EventEmitter = require('events').EventEmitter;

// Public modules
// TODO: remove
const merge = require('lodash.merge');
const pointer = require('json-pointer');
const manager = require('fast-json-patch');

// Fabric Types
const Actor = require('./actor');
const Collection = require('./collection');
const Entity = require('./entity');
const Filesystem = require('./filesystem');
const Hash256 = require('./hash256');
const Identity = require('./identity');
const Key = require('./key');
const Message = require('./message');
const Resource = require('./resource');
const Store = require('./store');
const { SERVICE_COMMIT_HISTORY_MAX } = require('../constants');
const {
  createDefaultOpcodeRegistry,
  defineOpcode: defineOpcodeEntry,
  resolveOpcodeContract,
  normalizePubkeyHex
} = require('../functions/opcodeRegistry');

/**
 * @classdesc Long-lived application surface extending {@link Actor}. Integrates external systems and the Fabric
 * network: peers consume and produce {@link Message} (AMP) instances, not ad-hoc JSON. Subclasses implement routing,
 * resources, and lifecycle (<code>start</code>/<code>stop</code> patterns — see <strong>AGENTS.md</strong>). The CLI/browser shell is {@link Service.FabricShell}.
 * @class Service
 * @extends Actor
 * @access protected
 * @property map The "map" is a hashtable of "key" => "value" pairs.
 */
class Service extends Actor {
  /**
   * Create an instance of a Service.
   * @param {Object} [settings] Configuration for this service.
   * @param {Boolean} [settings.networking=true] Whether or not to connect to the network.
   * @param {Object} [settings.frequency] Interval frequency in hertz.
   * @param {Object} [settings.state] Initial state to assign.
   */
  constructor (settings = {}) {
    // State (extends Actor) carries logging / lifecycle helpers formerly on Scribe
    super(settings);

    this.name = this.constructor.name;

    // Configure (with defaults)
    this.settings = merge({
      name: 'Service',
      path: './stores/service',
      frequency: 0.0133333334, // Hz
      networking: true,
      persistent: false,
      constraints: {
        tolerance: 100,
        memory: {
          max: 67108864
        }
      },
      fs: {
        path: `./stores/fabric-service-${this.name}`
      },
      key: null,
      state: {
        ...super.state,
        actors: {}, // TODO: schema
        channels: {}, // TODO: schema
        messages: {}, // TODO: schema
        services: {}
      },
      interval: 60000, // Mandatory Checkpoint Interval
      verbosity: 2, // 0 none, 1 error, 2 warning, 3 notice, 4 debug
      // TODO: export this as the default data in `inputs/fabric.json`
      // If the sha256(JSON.stringify(this.data)) is equal to this, it's
      // considered a valid Fabric object (for now!)
      /* '@data': {
        channels: {},
        messages: {},
        members: {}
      } */
    }, settings);

    // Reserve a place for ourselves
    this.agent = null;
    this.actor = null;
    this.name = this.settings.name;

    this.aliases = {};
    this.collections = {};
    this.definitions = {};
    this.resources = {};
    this.services = {};
    this.methods = {};
    this.opcodes = createDefaultOpcodeRegistry();
    this.clients = {};
    this.targets = [];
    this.history = [];
    this.origin = '';

    // TODO: fix this
    //   2) RPG Lite
    //      Canvas
    //        can draw a canvas:
    //          Error: Not implemented yet
    this.key = new Key(this.settings.key);
    this.identity = new Identity(this.settings.key);
    this.fs = new Filesystem({ ...this.settings.fs, key: this.settings.key });

    if (this.settings.persistent) {
      try {
        this.store = new Store(this.settings);
      } catch (E) {
        this.emit('error', `Store Error: ${E.message || E}`);
      }
    }

    this._clock = 0;

    // set local state to whatever configuration supplies...
    /* this.state = Object.assign({
      messages: {} // always define a list of messages for Fabric services
    }, this.config['@data']); */
    this._state = {
      clock: 0,
      epochs: {}, // snapshots of history (by ID)
      history: [], // list of ...
      services: {}, // stores sub-service state
      status: 'PAUSED',
      content: this.settings.state,
      version: 0 // TODO: change to 1 for 0.1.0
    };

    // Keeps track of changes
    this.observer = null;
    this.cache = {
      _data: new Map(),
      _ttl: new Map(),
      get: async (key) => {
        const now = Date.now();
        const expiresAt = this.cache._ttl.get(key);
        if (expiresAt !== undefined && expiresAt < now) {
          this.cache._data.delete(key);
          this.cache._ttl.delete(key);
          return null;
        }
        return this.cache._data.get(key);
      },
      /** @param {string} key @param {*} value @param {number} [ttlMs=60000] time-to-live in milliseconds */
      set: async (key, value, ttlMs = 60000) => {
        this.cache._data.set(key, value);
        this.cache._ttl.set(key, Date.now() + ttlMs);
      }
    };

    /* if (this.settings.networking) {
      this.swarm = new Swarm(this.settings);
    } */

    // Remove mutable variables
    Object.defineProperty(this, '@version', { enumerable: false });
    Object.defineProperty(this, '@input', { enumerable: false });
    Object.defineProperty(this, '@data', { enumerable: false });
    Object.defineProperty(this, '@meta', { enumerable: false });
    Object.defineProperty(this, '@encoding', { enumerable: false });
    Object.defineProperty(this, '@entity', { enumerable: false });
    Object.defineProperty(this, '@allocation', { enumerable: false });
    Object.defineProperty(this, '@buffer', { enumerable: false });

    // Remove sensitive objects
    // Object.defineProperty(this, 'store', { enumerable: false });
    Object.defineProperty(this, 'observer', { enumerable: false });

    // Provide the instance
    return this;
  }

  get clock () {
    return parseInt(this._clock);
  }

  get heartbeat () {
    return this._heart;
  }

  get interval () {
    return 1000 / this.settings.frequency;
  }

  get status () {
    return this._state.status;
  }

  get members () {
    return this['@data'].members;
  }

  get targets () {
    return this._targets;
  }

  get state () {
    return Object.assign({}, this._state.content);
  }

  set clock (value) {
    this._state.clock = parseInt(value);
  }

  set state (value) {
    // console.trace('[FABRIC:SERVICE]', 'Setting state:', value);
    this._state = value;
  }

  set status (value) {
    if (!value) return this.status;
    if (!this._state.status) this._state.status = 'PAUSED';
    this._state.status = value.toUpperCase();
    return this.status;
  }

  set targets (value) {
    this._targets = value;
  }

  static fromName (name) {
    let local = `services/${name}`;
    let deep = `/../node_modules/@fabric/core/${local}.js`;
    let fallback = path.dirname(require.main.filename) + deep;
    let plugin = null;

    try {
      plugin = require(local);
    } catch {
      // Avoid direct stdout writes from library internals.
      try {
        plugin = require(fallback);
      } catch {
        // no-op: return null plugin below
      }
    }

    return plugin;
  }

  alert (msg) {
    // TODO: promise
    // return Promise.all(Object.entries(this.services).filter().map())
    for (const [name, service] of Object.entries(this.services)) {
      if (!this.settings.services.includes(name)) continue;
      if (!service.alert) {
        this.emit('warning', `Service ${name} does not have an alert function`);
        continue;
      }

      service.alert(msg);
    }
  }

  /**
   * @param {String} msg Warning text (used by {@link Service#_registerService} duplicate guard).
   * @returns {Service} This instance.
   */
  _appendWarning (msg) {
    this.emit('warning', msg);
    return this;
  }

  identify () {
    this.emit('auth', this.key.pubkey);
    return this.key.pubkey;
  }

  /**
   * Called by Web Components.
   * TODO: move to @fabric/http/types/spa
   */
  init () {
    this.components = {};
  }

  /**
   * Move forward one clock cycle.
   * @returns {Number}
   */
  tick () {
    return this.beat();
  }

  /**
   * Compute latest state.
   * @emits Message#beat
   * @returns {Service}
   */
  beat () {
    const now = (new Date()).toISOString();

    // Increment clock
    ++this._clock;

    // Create Generic Message
    const beat = Message.fromVector(['Generic', {
      clock: this._clock,
      created: now,
      state: this._state.content
    }]);

    if (!beat) {
      this.emit('error', 'Beat could not construct a Message!');
      throw new Error('Beat could not construct a Message');
    }

    // TODO: remove JSON parser here — only needed for verification
    // TODO: parse JSON types in @fabric/core/types/message
    const data = beat.data;

    try {
      const pr = tryParseWireJson(typeof data === 'string' ? data : String(data ?? ''));
      if (!pr.ok) {
        this.emit('error', `Exception parsing beat: ${pr.error.message}`);
      }
    } catch (exception) {
      this.emit('error', `Exception parsing beat: ${exception}`);
    }

    this.emit('beat', beat);
    this.commit();

    return this;
  }

  append (block) {
    if (this.best !== block.parent) throw new Error(`Block does not attach to current chain.  Block ID: ${block.id} Block Parent: ${block.parent} Current Best: ${this.best}`);
  }

  /**
   * Retrieve a key from the {@link State}.
   * @param {Path} path Key to retrieve.
   * @returns {Mixed} Returns the target value if found, otherwise null.
   */
  get (path = '') {
    let result = null;
    try {
      result = pointer.get(this._state.content, path);
    } catch (exception) {
      this.emit('error', `[FABRIC:STATE] Could not retrieve path ${path}: ${exception.message || exception}`);
    }
    return result;
  }

  /**
   * Set a key in the {@link State} to a particular value.
   * @param {Path} path Key to retrieve.
   * @returns {Mixed}
   */
  set (path, value) {
    const result = pointer.set(this._state.content, path, value);
    this.commit();
    return result;
  }

  // Synchronize with any external sources
  sync () {
    if (!this._sources) this._sources = [];
    return this;
  }

  /**
   * Explicitly trust all events from a known source.
   * @param  {EventEmitter} source Emitter of events.
   * @return {Service} Instance of Service after binding events.
   */
  trust (source, name) {
    if (!(source instanceof EventEmitter)) throw new Error('Source is not an EventEmitter.');
    const label = name != null && name !== '' ? String(name) : source.constructor.name;

    // Constants
    const self = this;

    // Attach Event Listeners
    if (source.settings && source.settings.debug) source.on('debug', this._handleTrustedDebug.bind(this));
    if (source.settings && source.settings.verbosity >= 0) {
      source.on('audit', async function _handleTrustedAudit (_audit) {
        /*
        const now = (new Date()).toISOString();
        const template = {
          content: audit,
          created: now,
          type: 'Audit'
        };

        const actor = new Actor(template);
        // TODO: transaction log
        */
      });
    }

    return {
      _handleActor: source.on('actor', async function (actor) {
        self.emit('debug', `[FABRIC:SERVICE] Source "${label}" emitted actor: ${JSON.stringify(actor, null, '  ')}`);
      }),
      _handleAlert: source.on('alert', async function (alert) {
        self.alert(`[FABRIC:SERVICE] [ALERT] [!!!] ${label} alerted: ${alert}`);
      }),
      _handleBeat: source.on('beat', async function (beat) {
        self.emit('debug', `[FABRIC:SERVICE] Source "${label}" emitted beat: ${JSON.stringify(beat, null, '  ')}`);

        const _ops = [
          { op: 'add', path: `/actors`, value: {} },
          { op: 'add', path: `/services`, value: {} },
          { op: 'replace', path: `/services/${label}`, value: beat.state }
        ];

        /*
        try {
          manager.applyPatch(self._state.content, _ops);
          await self.commit();
        } catch (exception) {
          self.emit('warning', `Could not process beat: ${exception}`);
        }
        */
      }),
      _handleChanges: source.on('changes', async function (changes) {
        self.emit('debug', `[FABRIC:SERVICE] Source "${label}" emitted changes: ${changes}`);
      }),
      _handleChannel: source.on('channel', async function (channel) {
        self.emit('debug', `[FABRIC:SERVICE] Source "${label}" emitted channel: ${JSON.stringify(channel, null, '  ')}`);
      }),
      _handleCommit: source.on('commit', async function (commit) {
        self.emit('debug', `[FABRIC:SERVICE] Source "${label}" committed: ${JSON.stringify(commit, null, '  ')}`);
      }),
      _handleError: source.on('error', async function _handleTrustedError (error) {
        self.emit('debug', `[FABRIC:SERVICE] Source "${label}" emitted error: ${error}`);
      }),
      _handleLog: source.on('log', async function _handleTrustedLog (log) {
        if (self.settings.debug) self.emit('log', `[FABRIC:SERVICE] Source "${label}" emitted log: ${log}`);
      }),
      _handleMessage: source.on('message', async function (message) {
        self.emit('debug', `[FABRIC:SERVICE] Source "${label}" emitted message: ${JSON.stringify(message.toObject ? message.toObject() : message, null, '  ')}`);
        await self._handleTrustedMessage(message);
      }),
      _handlePatches: source.on('patches', async function (patches) {
        self.emit('debug', `[FABRIC:SERVICE] [${label}] Service State: ${JSON.stringify(source.state, null, '  ')}`);
        self.emit('debug', `[FABRIC:SERVICE] [${label}] Patches: ${JSON.stringify(patches)}`);
        self.emit('patches', patches);
      }),
      _handleReady: source.on('ready', async function _handleTrustedReady (info) {
        self.emit('log', `[FABRIC:SERVICE] Source "${label}" emitted ready: ${JSON.stringify(info)}`);
      }),
      _handleTip: source.on('tip', async function (hash) {
        self.alert(`[FABRIC:SERVICE] New ${label} chaintip: ${hash}`);
      }),
      _handleWarning: source.on('warning', async function _handleTrustedWarning (warning) {
        if (self.settings?.verbosity >= 2) self.emit('warning', `[FABRIC:SERVICE] Source "${label}" emitted warning: ${warning}`);
      })
    };
  }

  define (name, value) {
    if (String(name || '').startsWith('OP_')) {
      this.defineOpcode(name, Object.assign({ family: 'bitcoin' }, value || {}));
    }
    this.definitions[name] = Object.assign({
      data: {},
      handler: function handler (_msg) {
        return null;
      }
    }, value);

    return this;
  }

  ready () {
    this.emit('ready');
  }

  replay (list = []) {
    for (let i = 0; i < list.length; i++) {
      this.route(list[i]);
    }

    return this;
  }

  toString () {
    let entity = new Entity(this.state);
    return entity.toString();
  }

  /**
   * Default route handler for an incoming message.  Follows the Activity
   * Streams 2.0 spec: https://www.w3.org/TR/activitystreams-core/
   * @param  {Activity}  message Message object.
   * @return {Service}         Chainable method.
   */
  handler (message) {
    try {
      this.emit('message', {
        actor: message.actor,
        target: message.target,
        object: message.object
      });
    } catch (E) {
      this.emit('error', `Malformed message: ${E && E.message ? E.message : E}`);
    }

    return this;
  }

  /**
   * Attempt to acquire a lock for `duration` seconds.
   * @param {Number} [duration=1000] Number of milliseconds to hold lock.
   * @returns {Boolean} true if locked, false if unable to lock.
   */
  lock (duration = 1000) {
    if (this._state.status === 'LOCKED') return false;
    this._state.status = 'LOCKED';
    if (this._lockTimer) clearTimeout(this._lockTimer);
    this._lockTimer = setTimeout(() => {
      this._lockTimer = null;
      delete this.locker;
      this._state.status = 'UNLOCKED';
    }, duration);
    this.locker = new Actor({
      created: (new Date()).toISOString(),
      contract: 'locked'
    });

    return true;
  }

  /**
   * Bind a method to an event, with current state as the immutable context.
   * @param {String} event Name of the event upon which to execute `method` as a function.
   * @param {Function} method Function to execute when named {@link Event} `event` is encountered.
   * @returns {EventEmitter} Instance of EventEmitter.
   */
  when (event, method) {
    return this.on(event, method.call(this.state));
  }

  _defineResource (name, definition) {
    const resource = Object.assign({ name }, definition);
    this.resources[name] = new Resource(resource);
    this.emit('resource', this.resources[name]);
    return this.resources[name];
  }

  /**
   * Register a single opcode entry in the service registry.
   * @param {string} name Opcode symbol (e.g. `OP_SHA256`, `P2P_FLUSH_CHAIN`)
   * @param {Object} [definition]
   * @returns {Object}
   */
  defineOpcode (name, definition = {}) {
    return defineOpcodeEntry(this.opcodes, name, definition);
  }

  /**
   * Register Bitcoin-style primitive opcode metadata.
   * @param {string} name
   * @param {Object} [definition]
   * @returns {Object}
   */
  defineBitcoinOpcode (name, definition = {}) {
    return this.defineOpcode(name, Object.assign({}, definition, { family: 'bitcoin' }));
  }

  /**
   * Register Fabric opcode metadata.
   * @param {string} name
   * @param {Object} [definition]
   * @returns {Object}
   */
  defineFabricOpcode (name, definition = {}) {
    return this.defineOpcode(name, Object.assign({}, definition, { family: 'fabric' }));
  }

  /**
   * Register a newline-delimited opcode contract.
   * Contract body example:
   * `OP_DUP\nOP_HASH160\nP2P_FLUSH_CHAIN`
   * @param {string} name Contract label
   * @param {string} body Newline-delimited opcode list
   * @param {Object} [meta]
   * @returns {Object}
   */
  defineOpcodeContract (name, body, meta = {}) {
    const resolved = resolveOpcodeContract(this.opcodes, body);
    if (resolved.unknown.length) {
      throw new Error(`Unknown opcodes in contract "${name}": ${resolved.unknown.join(', ')}`);
    }

    const author = (meta && meta.author != null) ? String(meta.author) : null;
    const authorPubkey = normalizePubkeyHex(meta.authorPubkey || meta.pubkey || '');
    if (!author) throw new Error(`Contract "${name}" must include author.`);
    if (!authorPubkey) throw new Error(`Contract "${name}" must include a valid author pubkey.`);

    const proposedPolicy = (meta && typeof meta.policy === 'object' && meta.policy) ? meta.policy : {};
    const policyPubkeys = Array.isArray(proposedPolicy.pubkeys)
      ? proposedPolicy.pubkeys.map((x) => normalizePubkeyHex(x)).filter(Boolean)
      : [];
    if (policyPubkeys.length && (policyPubkeys.length !== 1 || policyPubkeys[0] !== authorPubkey)) {
      throw new Error(`Contract "${name}" policy pubkeys must be 1-of-1 and match author pubkey.`);
    }

    const policy = Object.assign({}, proposedPolicy, {
      type: 'taproot-multisig',
      threshold: 1,
      participants: 1,
      pubkeys: [authorPubkey]
    });

    const contract = Object.assign({
      name,
      body: String(body || ''),
      lines: resolved.lines,
      opcodes: resolved.resolved.map((entry) => entry.name),
      author,
      authorPubkey,
      policy
    }, meta);

    this.define(name, {
      data: contract,
      handler: function handler (msg) {
        return Object.assign({}, msg, { contract });
      }
    });

    return contract;
  }

  /**
   * Snapshot opcode registry for UI / API use.
   * @returns {Object[]}
   */
  listOpcodes () {
    return Object.values(this.opcodes || {}).map((entry) => Object.assign({}, entry));
  }

  _handleTrustedDebug (message) {
    this.emit('debug', `[FABRIC:SERVICE] Trusted Source emitted debug: ${message}`);
  }

  _handleTrustedMessage (message) {
    this.emit('message', message);
  }

  async process () {
    if (this.settings?.verbosity >= 4 || this.settings?.debug) {
      this.emit('debug', '[FABRIC:SERVICE] process() created');
    }
  }

  async broadcast (msg) {
    if (!msg['@type']) throw new Error('Message must have a @type property.');
    if (!msg['@data']) throw new Error('Message must have a @data property.');

    for (let name in this.clients) {
      let target = this.clients[name];
      if (this.settings?.verbosity >= 4 || this.settings?.debug) {
        this.emit('debug', `[FABRIC:SERVICE] Sending broadcast to client: ${target}`);
      }
    }

    this.emit('message', msg);
  }

  /**
   * Resolve a {@link State} from a particular {@link Message} object.
   * @param  {Message}  msg Explicit Fabric {@link Message}.
   * @return {Promise}     Resolves with resulting {@link State}.
   */
  async route (msg) {
    if (this.settings?.verbosity >= 4 || this.settings?.debug) {
      this.emit('debug', `[FABRIC:SERVICE] routing message: ${JSON.stringify(msg)}`);
      this.emit('debug', `[FABRIC:SERVICE] definitions: ${JSON.stringify(Object.keys(this.definitions))}`);
    }

    let result = null;

    if (this.definitions[msg.type]) {
      if (this.settings?.verbosity >= 4 || this.settings?.debug) {
        this.emit('debug', `[FABRIC:SERVICE] ${this.name} handling message type: ${msg.type}`);
      }

      let handler = this.definitions[msg.type].handler;
      let state = handler.apply(this.state, [msg]);

      if (this.settings?.verbosity >= 4 || this.settings?.debug) {
        this.emit('debug', `[FABRIC:SERVICE] route state sample: ${JSON.stringify(state)}`);
      }

      result = state;

      let commit = await this.commit();
      if (this.settings?.verbosity >= 4 || this.settings?.debug) {
        this.emit('debug', `[FABRIC:SERVICE] route commit: ${commit}`);
      }
    }

    return result;
  }

  /**
   * Start the service, including the initiation of an outbound connection
   * to any peers designated in the service's configuration.
   */
  async start () {
    this.emit('debug', `[FABRIC:SERVICE] Starting as ${this.id}...`);

    const service = this;

    // Assign status and process
    this.status = 'starting';

    // Define an Actor with all current settings
    this.actor = new Actor(this.settings);

    /* await this.define('message', {
      name: 'message',
      handler: this.process.bind(this.state),
      exclusive: true // override all previous types
    }); */

    for (const name in this.settings.resources) {
      const resource = this.settings.resources[name];
      const attribute = resource.routes.list.split('/')[1];
      const key = crypto.createHash('sha256').update(resource.routes.list).digest('hex');

      // Assign collection
      this.collections[key] = new Collection(resource);

      // Add to targets
      this.targets.push(this.collections[key].routes.list);

      // Define mappings
      Object.defineProperty(this, attribute, {
        get: function () {
          return this.collections[key];
        }
      });

      // Attach events
      this.collections[key].on('commit', (_commit) => {
        service.broadcast({
          '@type': 'StateUpdate',
          '@data': service.state
        });
      });

      this.collections[key].on('message', (message) => {
        service.emit('debug', `[FABRIC:SERVICE] Internal message (${key}): ${JSON.stringify(message)}`);
      });

      this.collections[key].on('transaction', (transaction) => {
        service.emit('debug', `[FABRIC:SERVICE] Internal transaction (${key}): ${JSON.stringify(transaction)}`);
      });

      this.collections[key].on('changes', (changes) => {
        service._applyChanges(changes);
        service.emit('change', {
          type: 'Change',
          data: changes
        });
      });
    }

    if (this.settings.persistent) {
      try {
        await this.store.start();
      } catch (E) {
        this.emit('error', `[FABRIC:SERVICE] Could not start store: ${E.message || E}`);
      }
    }

    await this._startAllServices();

    if (this.settings.networking) {
      await this.connect();
    }

    // TODO: re-re-evaluate a better approach... oh how I long for Object.observe!
    // this.observer = manager.observe(this.state, this._handleStateChange.bind(this));
    try {
      this.observer = manager.observe(this._state.content);
    } catch (exception) {
      this.emit('error', `[FABRIC:SERVICE] Could not observe state: ${exception.message || exception}`);
    }

    // Set a heartbeat
    await this._startHeart();

    this.status = 'ready';
    this.emit('log', '[FABRIC:SERVICE] Started!');
    this.ready();

    return this;
  }

  async stop () {
    this.emit('debug', 'Stopping...');

    if (this.settings.networking) {
      await this.disconnect();
    }

    if (this._heart) {
      clearInterval(this._heart);
    }

    if (this.settings.persistent) {
      try {
        await this.store.stop();
      } catch (E) {
        this.emit('error', `[FABRIC:SERVICE] Exception stopping store: ${E.message || E}`);
      }
    }

    return this;
  }

  /**
   * Retrieve a value from the Service's state.
   * @param  {String}  path Path of the value to retrieve.
   * @return {Promise}      Resolves with the result.
   */
  async _GET (path) {
    let result = null;
    if (typeof path !== 'string') return null;

    let parts = path.split('/');
    let list = `/${parts[1]}`;
    let name = crypto.createHash('sha256').update(list).digest('hex');

    if (path === '/') return this.state;
    if (this.collections[name]) {
      if (parts[2]) {
        let inner = this.collections[name].filter((x) => {
          return (x.address === parts[2]);
        })[0];
        return inner;
      }
    }

    try {
      result = pointer.get(this.state, path);
    } catch (exception) {
      this.emit('debug', `Could not _GET() ${path}:\n${exception}\n\tState: ${JSON.stringify(this.state, null, '  ')}`);
    }

    return result;
  }

  /**
   * Store a value in the Service's state.
   * @param  {String}  path  Path to store the value at.
   * @param  {Object}  value Document to store.
   * @param  {Boolean} [commit=false] Sign the resulting state.
   * @return {Promise}       Resolves with with stored document.
   */
  async _PUT (path, value, commit = true) {
    let result = null;

    if (path === '/') {
      this.state = value;
    } else {
      try {
        result = pointer.set(this.state, path, value);
      } catch (E) {
        this.emit('error', `Could not _PUT() ${path}: ${E && E.message ? E.message : E}`);
      }
    }

    if (commit) {
      await this.commit();
    }

    return result;
  }

  async _POST (path, data, commit = true) {
    if (!path) throw new Error('Path must be provided.');
    if (!data) throw new Error('Data must be provided.');

    const name = crypto.createHash('sha256').update(path).digest('hex');
    const hash = crypto.createHash('sha256').update(JSON.stringify(data)).digest('hex');

    let result = null;

    // always use locally computed values
    data.address = hash;

    let object = new Entity(data);
    let collection = null;
    let memory = null;

    try {
      memory = await pointer.get(this.state, path);
    } catch {
      this.emit('warning', `[FABRIC:SERVICE] posting to unloaded collection: ${path}`);
      memory = [];
    }

    try {
      collection = new Collection(memory);
    } catch (E) {
      this.emit('error', `Could not create collection: ${E.message || E}`);
      return null;
    }

    // TODO: use Resource definition to de-deuplicate by fields.id
    collection.push(object.toObject());
    this.collections[name] = await collection.populate();

    // TODO: reduce storage to references
    try {
      await this._PUT(path, await collection.populate());
      await this.set(path, await collection.populate());
      result = `${path}/${data.address}`;
    } catch (E) {
      this.emit('error', `Could not persist collection update: ${E.message || E}`);
    }

    if (commit) await this.commit();

    return result;
  }

  /**
   * Attach to network.
   * @param  {Boolean}  notify Commit to changes.
   * @return {Promise}        Resolves to {@link Fabric}.
   */
  async connect (notify = true) {
    // TODO: implement a basic Stream
    this.status = 'connecting';

    // stub for a transform stream
    this.fabric = new stream.Transform({
      transform (chunk, encoding, callback) {
        callback(null, chunk);
      }
    });

    if (this.store) {
      try {
        const prior = await this.store.get('/');
        const pr = tryParsePersistedJson(utf8FromPersistedRaw(prior));
        if (pr.ok && pr.value != null && typeof pr.value === 'object' && !Array.isArray(pr.value)) {
          const v = pr.value;
          if (Object.prototype.hasOwnProperty.call(v, 'content')) {
            if (v.content != null && typeof v.content === 'object' && !Array.isArray(v.content)) {
              this._state.content = Object.assign({}, this._state.content, v.content);
              if (typeof v.status === 'string') this._state.status = v.status;
              if (Number.isFinite(Number(v.clock))) this._state.clock = Number(v.clock);
              if (v.version != null) this._state.version = v.version;
            } else {
              this.emit('warning', '[FABRIC:SERVICE] Ignoring restored state: invalid content envelope');
            }
          } else {
            this._state.content = Object.assign({}, this._state.content, v);
          }
        } else if (pr.ok) {
          this.emit('warning', '[FABRIC:SERVICE] Ignoring restored state: expected a plain object');
        } else {
          this.emit('warning', `[FABRIC:SERVICE] Could not restore state: ${pr.error.message}`);
        }
      } catch (exception) {
        this.emit('warning', `[FABRIC:SERVICE] Could not restore state: ${exception}`);
      }
    }

    if (this.settings.networking && this.swarm) {
      await this.swarm.start();
    }

    this.connection = null;
    this.status = 'connected';

    if (notify) {
      await this.ready();
    }

    return this.fabric;
  }

  async disconnect () {
    this.status = 'disconnecting';
    // if (this.status !== 'active') return this;
    if (this.settings.networking && this.swarm) await this.swarm.stop();
    this.status = 'disconnected';
    return this;
  }

  async subscribe (actorID, channelID) {
    if (!actorID) throw new Error('Must provide actor ID.');
    if (!channelID) throw new Error('Must provide channel ID.');

    const label = Hash256.digest(actorID + channelID);
    const actor = await this._getActor(actorID);
    const channel = await this._getChannel(channelID);

    if (!actor) throw new Error(`Actor does not exist: ${actorID}`);
    if (!channel) throw new Error(`Channel does not exist: ${channelID}`);

    const link = await this._POST('/subscriptions', { label });

    await this._applyChanges([
      { op: 'add', value: channelID, path: `/actors/${actor.id}/subscriptions/0` },
      { op: 'add', value: channelID, path: `/channels/${channel.id}/members/0` }
    ]);

    await this.commit();

    const result = await this._GET(link);
    this.emit('subscription', result);

    return result;
  }

  async join (_id) {
    this.log('join() is not yet implemented for this service.');
  }

  async whisper (_target, _message) {
    this.log('The "whisper" function is not yet implemented.');
    return this;
  }

  /**
   * Send a message to a channel.
   * @param  {String} channel Channel name to which the message will be sent.
   * @param  {String} message Content of the message to send.
   * @return {Service}        Chainable method.
   */
  async send (channel, message, _extra) {
    if (this.debug) this.emit('debug', `[SERVICE] send() Sending: ${channel}`);

    const path = Buffer.alloc(256);
    const payload = Buffer.alloc(2048);
    const checksum = Buffer.alloc(64);
    const entropy = Buffer.alloc(1726); // fill to 4096

    path.write(channel);
    payload.write(message);

    const msg = Buffer.concat([ path, payload ]);
    const hash = crypto.createHash('sha256').update(msg).digest('hex');

    checksum.write(hash);

    const block = Buffer.concat([
      Buffer.from([0x01]), // version byte
      Buffer.from([0x00]), // placeholder
      checksum,
      msg,
      entropy
    ]);

    this.fabric.write(block);

    return this;
  }

  /**
   * Record outstanding JSON Patch deltas and emit a compact commitment id.
   * Does **not** wrap {@link Service#state} in a new {@link Actor} — that
   * JSON-cloned the entire tree on every write/connect and OOMed Hub.
   * @returns {String} 32-byte commitment id
   */
  commit () {
    // this.emit('debug', `[FABRIC:SERVICE] Committing ${OP_TRACE()}`);
    let patches = [];
    if (PATCHES_ENABLED && this.observer) {
      try {
        const generated = manager.generate(this.observer);
        patches = Array.isArray(generated) ? generated : [];
        if (patches.length) {
          this.history.push(patches);
          this.emit('patches', patches);
        }
      } catch (E) {
        this.emit('error', `Could not generate patches: ${E.message || E}`);
      }
    }

    const maxRaw = this.settings && this.settings.commitHistoryMax;
    const max = (typeof maxRaw === 'number' && Number.isFinite(maxRaw) && maxRaw >= 0)
      ? Math.floor(maxRaw)
      : SERVICE_COMMIT_HISTORY_MAX;
    while (this.history.length > max) this.history.shift();

    const clock = (this._clock | 0);
    const commit = new Actor({
      type: 'Commit',
      clock: clock,
      patchCount: patches.length
    });
    const id = commit.id;

    this.emit('commit', { type: 'Commit', clock: clock, id: id, patchCount: patches.length });
    // this.emit('state', this.state);

    return id;
  }

  async _handleBitcoinCommit (commit) {
    this.emit('debug', `[FABRIC:SERVICE] Handling (Bitcoin?) commit: ${JSON.stringify(commit)}`);
  }

  async _attachBindings (emitter) {
    const service = this;

    emitter.on('attached', function () {
      service.emit('attached', {
        type: 'Notification',
        message: 'Bindings complete!'
      });
    });

    emitter.emit('attached');

    return service;
  }

  async _bindStore (store) {
    this.store = store;
    return this;
  }

  async _getActor (id) {
    if (!id) {
      this.emit('error', 'Parameter "id" is required.');
      return null;
    }
    let path = pointer.escape(id);
    return this._GET(`/actors/${path}`);
  }

  async _getChannel (id) {
    if (!id) {
      this.emit('error', 'Parameter "id" is required.');
      return null;
    }
    let target = pointer.escape(id);
    return this._GET(`/channels/${target}`);
  }

  /**
   * Register an {@link Actor} with the {@link Service}.
   * @param  {Object}  actor Instance of the {@link Actor}.
   * @return {Promise}       Resolves upon successful registration.
   */
  async _registerActor (actor = {}) {
    if (!actor.id) {
      const entity = new Actor(actor);
      actor = { ...entity.toObject(), id: entity.id };
    }

    const id = pointer.escape(actor.id);
    const path = `/actors/${id}`;

    try {
      await this._PUT(path, merge({
        name: actor.id,
        subscriptions: []
      }, actor, { id }));
    } catch (E) {
      this.emit('error', `Something went wrong saving: ${E && E.message ? E.message : E}`);
      return null;
    }

    await this.commit();

    const registration = await this._GET(path);
    this.emit('actor', registration);

    return registration;
  }

  async _registerChannel (channel) {
    if (!channel.id) {
      const entity = new Actor(channel);
      channel = merge({
        id: entity.id,
        members: []
      }, channel);
      return channel;
    }

    const target = pointer.escape(channel.id);
    const path = `/channels/${target}`;

    try {
      await this._PUT(path, merge({
        members: []
      }, channel));
    } catch (E) {
      this.log(`Failed to register channel "${channel.id}":`, E);
    }

    await this.commit();

    const registration = await this._GET(path);
    this.emit('channel', registration);

    return registration;
  }

  async _addMemberToChannel (memberID, channelID) {
    return this.subscribe(memberID, channelID);
  }

  async _registerMethod (name, method) {
    this.methods[name] = method.bind(this);
  }

  async _updatePresence (id, status) {
    const target = pointer.escape(id);
    const presence = (status === 'online') ? 'online' : 'offline';
    return this._PUT(`/actors/${target}/presence`, presence);
  }

  async _getPresence (id) {
    const member = await this._GET(`/actors/${id}`);
    return member.presence || null;
  }

  async _getMembers (id) {
    const channel = await this._GET(`/channels/${id}`);
    if (!channel) throw new Error(`No such channel: ${id}`);
    return channel.members || null;
  }

  async _getSubscriptions (id) {
    const member = await this._GET(`/actors/${id}`);
    return member.subscriptions || null;
  }

  async _listActors () {
    return Object.values(await this._GET('/actors'));
  }

  async _listChannels () {
    return Object.values(await this._GET('/channels'));
  }

  async _applyChanges (changes) {
    let result = { ok: false, error: 'not applied' };
    const requireCap = this.settings && this.settings.requirePatchCapability === true;
    const hasCap = !!(this.settings && this.settings.patchCapability);
    if (requireCap && !hasCap) {
      const msg = 'Service patch requires settings.patchCapability when requirePatchCapability is set';
      if (this.listenerCount('error') > 0) this.emit('error', new Error(msg));
      return { ok: false, error: msg };
    }

    const ops = Array.isArray(changes) ? changes : [];
    const sensitive = /\/(mnemonic|seed|xprv|privateKey|private|passphrase)(\/|$)/i;
    for (const operation of ops) {
      const pointers = [];
      if (operation && operation.path != null) pointers.push(['path', String(operation.path)]);
      // RFC6902 copy/move read through `from`; guard both so a move from
      // /mnemonic to /public cannot leak credentials into Service.state.
      if (operation && operation.from != null) pointers.push(['from', String(operation.from)]);
      for (const [kind, pointer] of pointers) {
        if (sensitive.test(pointer)) {
          const msg = 'Service patch refused sensitive ' + kind + ': ' + pointer;
          if (this.listenerCount('error') > 0) this.emit('error', new Error(msg));
          return { ok: false, error: msg };
        }
      }
    }

    try {
      manager.applyPatch(this._state.content, ops, function isValid () {
        return true;
      }, true /* mutate doc (1st param) */);
      result = { ok: true };
    } catch (exception) {
      const msg = exception.message || String(exception);
      console.error(`Could not apply changes: ${msg}`);
      result = { ok: false, error: msg };
      if (this.listenerCount('error') > 0) {
        this.emit('error', exception instanceof Error ? exception : new Error(msg));
      }
      return result;
    }

    this.commit();

    return result;
  }

  async _handleStateChange (changes) {
    this.emit('debug', `[FABRIC:SERVICE] State change: ${JSON.stringify(changes)}`);
    this.emit('message', {
      '@type': 'Transaction',
      '@data': {
        // TODO: update this in constructor
        parent: this.origin,
        changes: changes
      }
    });
  }

  async _heartbeat () {
    return this.tick();
  }

  /**
   * Sends a message.
   * @param {Mixed} message Message to send.
   */
  async _send (message) {
    const entity = new Entity(message);
    await this._PUT(`/messages/${entity.id}`, message);
    return entity.id;
  }

  async _registerService (name, Service) {
    const self = this;
    const settings = merge({}, this.settings, this.settings[name]);
    const service = new Service(settings);

    if (this.services[name]) {
      return this._appendWarning(`Service already registered: ${name}`);
    }

    this.services[name] = service;
    this.services[name].on('error', function (msg) {
      self.emit('error', `Service "${name}" emitted error: ${JSON.stringify(msg, null, '  ')}`);
    });

    this.services[name].on('warning', function (msg) {
      self.emit('warning', `Service warning from ${name}: ${JSON.stringify(msg, null, '  ')}`);
    });

    this.services[name].on('message', function (msg) {
      self.emit('message', `Service message from ${name}: ${JSON.stringify(msg, null, '  ')}`);
    });

    this.on('identity', async function _registerActor (identity) {
      if (self.settings.services && self.settings.services.includes(name)) {
        self.emit('log', `Registering actor on service "${name}": ${JSON.stringify(identity)}`);

        try {
          let registration = await self.services[name]._registerActor(identity);
          self.emit('log', `Registered Actor: ${JSON.stringify(registration, null, '  ')}`);
        } catch (exception) {
          self.emit('error', `Error from service "${name}" during _registerActor: ${exception}`);
        }
      }
    });

    if (service.routes && service.routes.length) {
      for (let i = 0; i < service.routes.length; i++) {
        const route = service.routes[i];
        this.http._addRoute(route.method, route.path, route.handler);
      }
    }

    await this.commit();

    return this;
  }

  async _startAllServices () {
    if (!this.services) return this.emit('warning', 'Tried to start subservices, but none existed.');
    this.emit('debug', `Service entries: ${Object.keys(this.services)}`);

    // Start all Services
    for (const [name, _service] of Object.entries(this.services)) {
      // TODO: re-evaluate inclusion on Service itself
      if (this.settings.services && this.settings.services.includes(name)) {
        this.emit('debug', `Starting service "${name}" (with trust)...`);
        // TODO: evaluate @fabric/core/types/store
        // TODO: isomorphic @fabric/core/types/store
        // await this.services[name]._bindStore(this.store);
        this.trust(this.services[name], name);

        try {
          await this.services[name].start();
        } catch (exception) {
          this.emit('warning', `Could not start the "${name}" service due to exception: ${JSON.stringify(exception, null, '  ')}`);
        }
      }
    }

    return this;
  }

  async _startHeart () {
    if (this._heart) clearInterval(this._heart);
    this._heart = setInterval(this.beat.bind(this), this.settings.interval);
    return this;
  }
}

/**
 * Browser / CLI application shell: encrypted store, peer node, resources.
 * @private
 * @class FabricShell
 */
class FabricShell extends Service {
  constructor (definition = {}) {
    super(definition);

    const Peer = require('./peer');
    const Machine = require('./machine');

    if (!definition.resources) definition.resources = {};

    this.settings = Object.assign({
      seed: null,
      listen: false,
      path: './stores/fabric-application',
      prefix: '/',
      services: [],
      verbosity: 1
    }, definition);

    this.node = new Peer(this.settings);
    this.actor = new Actor(this.settings);
    this.machine = new Machine(this.settings);
    this.store = Store.openEncrypted(this.settings);

    this.tips = new Store({ path: './stores/tips' });
    this.stash = new Store({ path: './stores/stash' });

    this.name = 'application';
    this.network = {};

    this.bindings = {};
    this.authorities = {};
    this.components = {};
    this.elements = {};
    this.services = {};
    this.commands = {};
    this.resources = {};
    this.templates = {};
    this.keys = [];

    this.stash.on('patches', (patches) => {
      this.emit('debug', `[FABRIC:APP] heard patches: ${JSON.stringify(patches)}`);
    });

    if (this.settings.resources) {
      for (const name in this.resources) {
        this.set(this.settings.prefix + this.resources[name].components.list, []);
      }
    }

    this._state = {
      anchor: 'BTC',
      chains: {}
    };

    this.commit();

    return this;
  }

  _bindEvents (element) {
    for (const name in this.bindings) element.addEventListener(name, this.bindings[name]);
    return element;
  }

  _unbindEvents (element) {
    for (const name in this.bindings) element.removeEventListener(this.bindings[name]);
    return element;
  }

  async bootstrap () {
    return true;
  }

  async _signWithOwnID (input) {
    return this.key.sign(input);
  }

  async start () {
    this._appendMessage(`[FABRIC:APP] @${this.id} -- Starting...`);
    this.status = 'STARTING';

    for (const [name, _service] of Object.entries(this.services)) {
      this._appendWarning(`@${this.id} -- Checking for Service: ${name}`);
      if (this.settings.services.includes(name)) {
        this._appendWarning(`Starting service: ${name}`);
        await this.services[name]._bindStore(this.store);
        await this.services[name].start();
      }
    }

    this.node.start();
    this.status = 'STARTED';
    this.emit('ready');
    this._appendMessage(`[FABRIC:APP] @${this.id} -- Started!`);

    return this;
  }

  async stop () {
    this.emit('log', '[FABRIC:APP] Stopping...');
    await this.node.stop();
    await this.tips.close();
    await this.stash.close();
    this.emit('log', '[FABRIC:APP] Stopped!');
    return this;
  }

  async define (name, structure) {
    const self = this;

    self.log('[APP]', 'defining:', name, structure);

    try {
      const resource = new Resource(structure);

      resource.trust(self.stash);

      self.resources[name] = resource;
    } catch (E) {
      this.emit('error', E.message || String(E));
    }

    return this;
  }

  async register (component) {
    this.components[component.name] = component;
  }

  async defer (authority) {
    const self = this;
    let resources = {};

    this.emit('warning', `[APP] deferring authority: ${authority}`);

    if (!resources) {
      resources = {};
    }

    self.consume(resources);

    if (typeof window !== 'undefined' && window.page) {
      window.page('/', function (context) {
        self.log('Hello, navigator.');
        self.log('Context:', context);
        self.element.navigate('fabric-splash', context);
      });

      window.page();
    }

    return this;
  }

  async _appendMessage (msg) {
    this.emit('log', `[${(new Date()).toISOString()}]: ${msg}`);
  }

  async _appendWarning (msg) {
    this.emit('warning', `[${(new Date()).toISOString()}]: ${msg}`);
  }

  async _appendError (msg) {
    const line = `[${(new Date()).toISOString()}]: ${msg}`;
    // Emitting `error` with no listener throws in Node.js EventEmitter.
    if (this.listenerCount('error') > 0) {
      this.emit('error', line);
    } else {
      this.emit('warning', line);
    }
  }

  attach (element) {
    this.element = element;
    return this;
  }

  consume (resources) {
    const self = this;

    self.element.resources = resources;

    for (const key in resources) {
      const def = resources[key];
      self.define(def.name, def);
    }

    return this;
  }

  envelop (selector) {
    try {
      const element = document.querySelector(selector);

      if (!element) {
        this.log('[FABRIC:APP]', 'envelop()', 'could not find element:', selector);
        return null;
      }

      this._bindEvents(element);
      this.attach(element);
    } catch (E) {
      this.emit('error', `Could not envelop element: ${E.message || E}`);
    }

    return this;
  }

  use (name, definition) {
    this.log('[APP]', 'using:', name, definition);
    super.use(name, definition);
    return this;
  }

  render () {
    const actor = new Actor(this._state);
    const html = `<fabric-${this.name.toLowerCase()}>` +
      `\n  <fabric-state id="${actor.id}">` +
      `\n    <fabric-state-json integrity="sha256:${actor.preimage}">${actor.serialize()}</fabric-state-json>` +
      '\n  </fabric-state>' +
      `\n</fabric-${this.name.toLowerCase()}>\n`;

    const sample = new Actor(html);

    if (this.element) {
      this.element.setAttribute('integrity', `sha256:${sample.preimage}`);
      this.element.innerHTML = html;
    }

    return html;
  }

  _registerCommand (command, method) {
    this.commands[command] = method.bind(this);
  }

  _registerService (name, ServiceClass) {
    const self = this;
    const service = new ServiceClass(merge({}, this.settings, this.settings[name]));

    if (this.services[name]) {
      return this._appendWarning(`Service already registered: ${name}`);
    }

    this.services[name] = service;

    this.services[name].on('error', function (msg) {
      self._appendError(`Service "${name}" emitted error: ${JSON.stringify(msg, null, '  ')}`);
    });

    this.services[name].on('warning', function (msg) {
      self._appendWarning(`Service warning from ${name}: ${JSON.stringify(msg, null, '  ')}`);
    });

    this.services[name].on('message', function (msg) {
      self._appendMessage(`@services/${name} -- <FabricServiceMessage>(${typeof msg}) ${JSON.stringify(msg, null, '  ')}`);
      switch (msg['@type']) {
        case 'ChatMessage': {
          const { chatTextOf } = require('../functions/fabricChatText');
          const text = chatTextOf(msg) || chatTextOf(msg.object) || '';
          if (text.trim()) {
            const packet = Message.fromVector(['P2P_CHAT_MESSAGE', String(text)]);
            if (self.node.key) packet.signWithKey(self.node.key);
            self.node.relayFrom(self.node.id, packet);
          }
          break;
        }
        default:
          break;
      }
    });

    this.on('identity', function _registerActor (identity) {
      if (this.settings.services.includes(name)) {
        self._appendMessage(`Registering actor on service "${name}": ${JSON.stringify(identity)}`);

        try {
          this.services[name]._registerActor(identity);
        } catch (exception) {
          self._appendError(`Error from service "${name}" during _registerActor: ${exception}`);
        }
      }
    });

    return this.services[name];
  }
}

module.exports = Service;
module.exports.FabricShell = FabricShell;
